import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Home, MessageCircle, Newspaper, Bell, Grid } from 'lucide-react';
import { motion } from 'framer-motion';

const BottomNav: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const tabs = [
    { id: 'home', icon: Home, label: 'Home', path: '/home' },
    { id: 'support', icon: MessageCircle, label: 'Support', path: '/support' },
    { id: 'news', icon: Newspaper, label: 'News', path: '/news' },
    { id: 'notifications', icon: Bell, label: 'Notifications', path: '/notifications' },
    { id: 'more', icon: Grid, label: 'More', path: '/more' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 max-w-[430px] mx-auto z-50 px-2 pb-2">
      <div className="glass-panel rounded-2xl h-16 flex items-center justify-around px-1 shadow-lg shadow-black/40">
        {tabs.map((tab) => {
          const isActive = location.pathname === tab.path;
          const Icon = tab.icon;

          return (
            <button
              key={tab.id}
              onClick={() => navigate(tab.path)}
              className="flex flex-col items-center justify-center w-12 h-12 relative"
            >
              {isActive && (
                <motion.div
                  layoutId="activeTab"
                  className="absolute inset-0 bg-primary/10 rounded-xl"
                  initial={false}
                  transition={{ type: "spring", stiffness: 500, damping: 30 }}
                />
              )}
              <Icon
                size={20}
                className={`transition-colors duration-300 ${
                  isActive ? 'text-primary drop-shadow-[0_0_8px_rgba(29,183,240,0.6)]' : 'text-slate-400'
                }`}
              />
              <span className={`text-[9px] mt-1 font-medium transition-colors duration-300 ${
                isActive ? 'text-primary' : 'text-slate-500'
              }`}>
                {tab.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default BottomNav;

