export type NotificationType = 'system' | 'success' | 'warning' | 'message' | 'payment';

export interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  timestamp: number;
  read: boolean;
  dismissed: boolean;
}

const STORAGE_KEY = 'raiyansoft_notifications';

const DEMO_MESSAGES = [
  { type: 'message' as const, title: 'New Lead Received', message: 'A customer requested a quote for an iOS e-commerce app.' },
  { type: 'payment' as const, title: 'Invoice Paid', message: 'Payment confirmed for Project Koshk (Invoice #9921).' },
  { type: 'system' as const, title: 'System Update', message: 'Raiyan CRM has been updated to v1.2.1 with performance fixes.' },
  { type: 'warning' as const, title: 'Server Load High', message: 'Warning: CPU usage on EasyShop instance #4 exceeded 85%.' },
  { type: 'success' as const, title: 'Deployment Successful', message: 'EasyShop v3.4.1 has been successfully deployed to production.' },
  { type: 'message' as const, title: 'Support Ticket #402', message: 'Customer asked about KNET integration details.' },
  { type: 'system' as const, title: 'Scheduled Maintenance', message: 'Reminder: Database maintenance scheduled for tonight at 3 AM.' },
];

const generateDemoData = (): Notification[] => {
  const now = Date.now();
  const hour = 3600000;

  return Array.from({ length: 12 }).map((_, i) => {
    const template = DEMO_MESSAGES[i % DEMO_MESSAGES.length];
    return {
      id: `notif_${now - i * 1000}`, // unique enough for demo
      type: template.type,
      title: template.title,
      message: template.message,
      timestamp: now - (Math.random() * 48 * hour), // Random time in last 48h
      read: i > 4, // First 5 are unread
      dismissed: false
    };
  }).sort((a, b) => b.timestamp - a.timestamp);
};

class NotificationStore {
  private notifications: Notification[] = [];
  private listeners: (() => void)[] = [];
  private simulationInterval: any = null;

  constructor() {
    this.load();
    this.startSimulation();
  }

  private load() {
    if (typeof window === 'undefined') return;
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      this.notifications = JSON.parse(stored);
    } else {
      this.notifications = generateDemoData();
      this.save();
    }
  }

  private save() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.notifications));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getNotifications() {
    return this.notifications.filter(n => !n.dismissed);
  }

  getUnreadCount() {
    return this.notifications.filter(n => !n.read && !n.dismissed).length;
  }

  markAsRead(id: string) {
    const notif = this.notifications.find(n => n.id === id);
    if (notif && !notif.read) {
      notif.read = true;
      this.save();
    }
  }

  markAllAsRead() {
    this.notifications.forEach(n => n.read = true);
    this.save();
  }

  dismiss(id: string) {
    const notif = this.notifications.find(n => n.id === id);
    if (notif) {
      notif.dismissed = true;
      this.save();
    }
  }

  // Simulation: Add a new notification every 20-35s
  private startSimulation() {
    if (this.simulationInterval) return;

    const scheduleNext = () => {
      const delay = Math.floor(Math.random() * 15000) + 20000; // 20-35s
      this.simulationInterval = setTimeout(() => {
        const template = DEMO_MESSAGES[Math.floor(Math.random() * DEMO_MESSAGES.length)];
        const newNotif: Notification = {
          id: `notif_${Date.now()}`,
          type: template.type,
          title: template.title,
          message: template.message,
          timestamp: Date.now(),
          read: false,
          dismissed: false
        };
        this.notifications.unshift(newNotif);
        this.save();
        scheduleNext();
      }, delay);
    };

    scheduleNext();
  }
}

export const notificationStore = new NotificationStore();

export const useNotifications = () => {
  const [data, setData] = useState({
    notifications: notificationStore.getNotifications(),
    unreadCount: notificationStore.getUnreadCount()
  });

  useEffect(() => {
    const update = () => {
      setData({
        notifications: notificationStore.getNotifications(),
        unreadCount: notificationStore.getUnreadCount()
      });
    };

    // Initial sync
    update();

    return notificationStore.subscribe(update);
  }, []);

  return data;
};

