import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center text-slate-400">
          <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mb-4 border border-white/5">
            <AlertTriangle className="text-amber-500" size={32} />
          </div>
          <h2 className="text-xl font-bold text-white mb-2">Something went wrong</h2>
          <p className="text-sm mb-6">We couldn't load this section.</p>
          <button
            onClick={() => {
              this.setState({ hasError: false, error: null });
              window.location.reload();
            }}
            className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Calendar, Clock, ArrowRight } from 'lucide-react';
import { Notification } from '../lib/notificationStore';

interface Props {
  notification: Notification | null;
  onClose: () => void;
}

const NotificationSheet: React.FC<Props> = ({ notification, onClose }) => {
  if (!notification) return null;

  const dateStr = new Date(notification.timestamp).toLocaleDateString(undefined, { 
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
  });
  const timeStr = new Date(notification.timestamp).toLocaleTimeString(undefined, {
    hour: '2-digit', minute: '2-digit'
  });

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        // z-[60] ensures it sits above the BottomNav (z-50)
        // items-center ensures it is vertically centered on the screen
        className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[60] flex items-center justify-center p-4"
      >
        <motion.div
          initial={{ scale: 0.9, opacity: 0, y: 20 }}
          animate={{ scale: 1, opacity: 1, y: 0 }}
          exit={{ scale: 0.9, opacity: 0, y: 20 }}
          transition={{ type: 'spring', damping: 25, stiffness: 300 }}
          onClick={(e) => e.stopPropagation()}
          className="w-full max-w-[380px] bg-[#0f172a] rounded-3xl border border-white/10 p-6 shadow-2xl relative overflow-hidden"
        >
          {/* Decorative background gradient */}
          <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />

          {/* Header */}
          <div className="flex items-start justify-between mb-6 relative z-10">
            <h2 className="text-xl font-bold text-white leading-tight pr-4">{notification.title}</h2>
            <button 
              onClick={onClose}
              className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors border border-white/5"
            >
              <X size={20} />
            </button>
          </div>

          {/* Metadata */}
          <div className="flex items-center space-x-4 mb-6 text-xs text-slate-400 relative z-10">
            <div className="flex items-center space-x-1">
              <Calendar size={14} />
              <span>{dateStr}</span>
            </div>
            <div className="flex items-center space-x-1">
              <Clock size={14} />
              <span>{timeStr}</span>
            </div>
          </div>

          {/* Body */}
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-white/5 mb-8 relative z-10">
            <p className="text-slate-300 leading-relaxed text-sm">
              {notification.message}
            </p>
          </div>

          {/* Actions */}
          <div className="flex space-x-3 relative z-10">
            <button 
              onClick={onClose}
              className="flex-1 py-3.5 rounded-xl bg-slate-800 text-white font-medium text-sm hover:bg-slate-700 transition-colors border border-white/5"
            >
              Dismiss
            </button>
            <button 
              onClick={onClose}
              className="flex-1 py-3.5 rounded-xl bg-primary text-white font-medium text-sm shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center space-x-2"
            >
              <span>View Details</span>
              <ArrowRight size={16} />
            </button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default NotificationSheet;

