class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.loadMessages();
  }

  private loadMessages() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          // Sanitize messages to ensure createdAt is a number (handle legacy string dates)
          this.messages = parsed.map((msg: any) => ({
            ...msg,
            createdAt: typeof msg.createdAt === 'string' ? new Date(msg.createdAt).getTime() : msg.createdAt
          })).filter(msg => !isNaN(msg.createdAt)); // Remove completely invalid messages
        } else {
          this.messages = generateDemoData();
          this.saveMessages();
        }
      } else {
        this.messages = generateDemoData();
        this.saveMessages();
      }
    } catch (e) {
      console.error("Failed to load chat messages", e);
      this.messages = generateDemoData();
      this.saveMessages();
    }
  }

  private saveMessages() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.messages));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  sendMessage(text: string) {
    const newMessage: Message = {
      id: `msg_${Date.now()}`,
      roomId: ROOM_ID,
      senderId: CURRENT_USER_ID,
      senderName: localStorage.getItem('user_name') || 'Nader Ahmed',
      senderRole: 'customer',
      text,
      createdAt: Date.now()
    };

    this.messages.push(newMessage);
    this.saveMessages();

    // Simulate auto-reply
    this.simulateStaffResponse();
  }

  addStaffMessage(text: string, senderName = 'Support Team') {
    const newMessage: Message = {
      id: `msg_${Date.now()}_staff`,
      roomId: ROOM_ID,
      senderId: 'staff_auto',
      senderName,
      senderRole: 'staff',
      text,
      createdAt: Date.now()
    };
    this.messages.push(newMessage);
    this.saveMessages();
  }

  private simulateStaffResponse() {
    // 1.5s delay then "typing" (handled by UI state), then 3s total delay for message
    setTimeout(() => {
      this.addStaffMessage("Thanks for the update. We are looking into it right now.");
    }, 3000);
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());

  useEffect(() => {
    const unsubscribe = chatStore.subscribe(() => {
      setMessages(chatStore.getMessages());
    });
    return unsubscribe;
  }, []);

  return messages;
};

import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null
    };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center text-slate-400">
          <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mb-4 border border-white/5">
            <AlertTriangle className="text-amber-500" size={32} />
          </div>
          <h2 className="text-xl font-bold text-white mb-2">Something went wrong</h2>
          <p className="text-sm mb-6">We couldn't load this section.</p>
          <button
            onClick={() => {
              this.setState({ hasError: false, error: null });
              window.location.reload();
            }}
            className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

