import { useState, useEffect } from 'react';

export interface Project {
  id: string;
  name: string;
  description: string;
  logoUrl: string;
  link: string;
  createdAt: number;
}

const STORAGE_KEY = 'raiyansoft_projects';

const DEFAULT_PROJECTS: Project[] = [
  {
    id: 'proj_1',
    name: "Koshk",
    description: "Multi-vendor eCommerce app for local sellers.",
    logoUrl: "https://ui-avatars.com/api/?name=Koshk&background=0D8ABC&color=fff&size=128&font-size=0.5",
    link: "https://raiyansoft.com",
    createdAt: Date.now() - 1000000
  },
  {
    id: 'proj_2',
    name: "EasyShop",
    description: "SaaS storefront platform with KNET payments.",
    logoUrl: "https://ui-avatars.com/api/?name=EasyShop&background=10B981&color=fff&size=128&font-size=0.5",
    link: "https://raiyansoft.com",
    createdAt: Date.now() - 500000
  },
  {
    id: 'proj_3',
    name: "RGPT",
    description: "AI support widget for websites and lead capture.",
    logoUrl: "https://ui-avatars.com/api/?name=RGPT&background=8B5CF6&color=fff&size=128&font-size=0.5",
    link: "https://raiyansoft.com",
    createdAt: Date.now()
  }
];

class ProjectStore {
  private projects: Project[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.load();
  }

  private load() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.projects = JSON.parse(stored);
      } else {
        this.projects = DEFAULT_PROJECTS;
        this.save();
      }
    } catch (e) {
      console.error("Failed to load projects", e);
      this.projects = DEFAULT_PROJECTS;
    }
  }

  private save() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.projects));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getProjects() {
    // Return copy sorted by newest first
    return [...this.projects].sort((a, b) => b.createdAt - a.createdAt);
  }

  addProject(project: Omit<Project, 'id' | 'createdAt'>) {
    const newProject: Project = {
      ...project,
      id: `proj_${Date.now()}`,
      createdAt: Date.now()
    };
    this.projects.push(newProject);
    this.save();
  }

  updateProject(id: string, updates: Partial<Omit<Project, 'id' | 'createdAt'>>) {
    const index = this.projects.findIndex(p => p.id === id);
    if (index !== -1) {
      this.projects[index] = { ...this.projects[index], ...updates };
      this.save();
    }
  }

  deleteProject(id: string) {
    this.projects = this.projects.filter(p => p.id !== id);
    this.save();
  }
}

export const projectStore = new ProjectStore();

export const useProjects = () => {
  const [projects, setProjects] = useState<Project[]>(projectStore.getProjects());

  useEffect(() => {
    const update = () => setProjects(projectStore.getProjects());
    // Initial sync
    update();
    return projectStore.subscribe(update);
  }, []);

  return { projects };
};

import React, { useEffect } from 'react';
import { HashRouter, Routes, Route, useLocation, Navigate } from 'react-router-dom';
import { AnimatePresence } from 'framer-motion';
import MobileShell from './components/MobileShell';
import BottomNav from './components/BottomNav';
import ErrorBoundary from './components/ErrorBoundary';

// Client App Pages
import Splash from './pages/Splash';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Home from './pages/Home';
import Projects from './pages/Projects';
import SupportChat from './pages/SupportChat';
import Notifications from './pages/Notifications';
import Placeholder from './pages/Placeholder';
import More from './pages/More';
import MoreSettings from './pages/MoreSettings';
import MoreAbout from './pages/MoreAbout';
import MoreTerms from './pages/MoreTerms';
import MorePrivacy from './pages/MorePrivacy';

// Admin Pages
import AdminLogin from './pages/admin/AdminLogin';
import AdminProjects from './pages/admin/AdminProjects';
import AdminLayout from './components/admin/AdminLayout';

// Scrolls the container to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    const scrollContainer = document.querySelector('.overflow-y-auto');
    if (scrollContainer) {
      scrollContainer.scrollTop = 0;
    }
  }, [pathname]);
  return null;
}

// Layout for the Mobile App
const MobileAppLayout = () => {
  const location = useLocation();

  const mainTabs = ['/home', '/support', '/news', '/notifications', '/more'];
  const showBottomNav = mainTabs.includes(location.pathname);

  return (
    <MobileShell>
      <ScrollToTop />
      {/* Route Content with Error Boundary */}
      <ErrorBoundary>
        <AnimatePresence mode="wait">
          <Routes location={location} key={location.pathname}>
            <Route path="/" element={<Splash />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/home" element={<Home />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/support" element={<SupportChat />} />
            <Route path="/news" element={<Placeholder title="News" />} />
            <Route path="/notifications" element={<Notifications />} />

            {/* More Section */}
            <Route path="/more" element={<More />} />
            <Route path="/more/settings" element={<MoreSettings />} />
            <Route path="/more/about" element={<MoreAbout />} />
            <Route path="/more/terms" element={<MoreTerms />} />
            <Route path="/more/privacy" element={<MorePrivacy />} />

            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </AnimatePresence>
      </ErrorBoundary>

      {/* Persistent Bottom Navigation */}
      {showBottomNav && <BottomNav />}
    </MobileShell>
  );
};

// Admin Guard
const ProtectedAdminRoute = ({ children }: { children: React.ReactNode }) => {
  const isAdminAuth = localStorage.getItem('adminAuth') === 'true';
  if (!isAdminAuth) {
    return <Navigate to="/admin/login" replace />;
  }
  return <>{children}</>;
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <Routes>
        {/* Admin Routes - Full Screen, No MobileShell */}
        <Route path="/admin/login" element={<AdminLogin />} />

        <Route path="/admin/*" element={
          <ProtectedAdminRoute>
            <AdminLayout>
              <Routes>
                <Route path="projects" element={<AdminProjects />} />
                {/* Default admin route */}
                <Route path="*" element={<Navigate to="/admin/projects" replace />} />
              </Routes>
            </AdminLayout>
          </ProtectedAdminRoute>
        } />

        {/* Main App Routes - Wrapped in MobileShell */}
        <Route path="/*" element={<MobileAppLayout />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

