import React, { ErrorInfo, ReactNode } from 'react';
import { AlertTriangle } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center text-slate-400">
          <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mb-4 border border-white/5">
            <AlertTriangle className="text-amber-500" size={32} />
          </div>
          <h2 className="text-xl font-bold text-white mb-2">Something went wrong</h2>
          <p className="text-sm mb-6">We couldn't load this section.</p>
          <button
            onClick={() => {
              this.setState({ hasError: false, error: null });
              window.location.reload();
            }}
            className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import { GoogleGenAI } from "@google/genai";

// Initialize the client with the API key from the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

/**
 * Fetches a response from the Gemini model.
 * Mirrors the dialect and style of the conversation history based on the system prompt.
 */
export async function getGeminiReply(
  messages: ChatMessage[],
  systemPrompt: string
): Promise<string | null> {
  try {
    // Map internal role names to Gemini API roles ('user' -> 'user', 'assistant' -> 'model')
    const contents = messages.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content }]
    }));

    // Use gemini-3-flash-preview for fast, high-quality conversational responses
    const response = await ai.models.generateContent({
      model: process.env.GEMINI_MODEL || 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7, // Balance between creativity and adherence to facts
      }
    });

    return response.text || null;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return null;
  }
}

import { useEffect, useState } from 'react';
import { getGeminiReply, ChatMessage } from './gemini';

export interface Message {
  id: string;
  roomId: string;
  senderId: string;
  senderName: string;
  senderRole: 'customer' | 'staff';
  text: string;
  createdAt: number;
}

const STORAGE_KEY = 'raiyansoft_chat_messages';
const PROMPT_STORAGE_KEY = 'rs_ai_system_prompt';
const CURRENT_USER_ID = 'user_123';
const ROOM_ID = 'support-room';

// Default prompt if admin hasn't set one
const DEFAULT_SYSTEM_PROMPT = `You are Raiyansoft Support, the official support assistant for Raiyansoft®. Your job is to help customers with questions about Raiyansoft products and services.
1) Always reply in the same language, dialect, and tone as the user’s most recent message.
2) Keep replies concise and practical.
3) If troubleshooting: give a short diagnostic checklist.
4) Do not invent technical facts.`;

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private isThinking: boolean = false;

  constructor() {
    this.loadMessages();
  }

  private loadMessages() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          this.messages = parsed.map((msg: any) => ({
            ...msg,
            createdAt: typeof msg.createdAt === 'string' ? new Date(msg.createdAt).getTime() : msg.createdAt
          })).filter(msg => !isNaN(msg.createdAt));
        }
      }
      // If no messages, start empty or add welcome message (optional)
      if (this.messages.length === 0) {
        // Optional: Add a welcome message if empty
      }
    } catch (e) {
      console.error("Failed to load chat messages", e);
      this.messages = [];
    }
  }

  private saveMessages() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.messages));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  getThinkingState() {
    return this.isThinking;
  }

  setThinking(state: boolean) {
    this.isThinking = state;
    this.notify();
  }

  async sendMessage(text: string) {
    // 1. Add User Message
    const userMessage: Message = {
      id: `msg_${Date.now()}`,
      roomId: ROOM_ID,
      senderId: CURRENT_USER_ID,
      senderName: localStorage.getItem('user_name') || 'Nader Ahmed',
      senderRole: 'customer',
      text,
      createdAt: Date.now()
    };

    this.messages.push(userMessage);
    this.saveMessages();

    // 2. Trigger AI Response
    this.setThinking(true);

    try {
      // Get System Prompt from storage or default
      const storedPrompt = localStorage.getItem(PROMPT_STORAGE_KEY);
      const systemPrompt = storedPrompt || DEFAULT_SYSTEM_PROMPT;

      // Prepare History for AI (Convert store messages to simple format)
      // We only take the last 10 messages to keep context relevant and fast
      const recentMessages = this.messages.slice(-10).map(m => ({
        role: m.senderRole === 'customer' ? 'user' : 'assistant',
        content: m.text
      } as ChatMessage));

      // Fetch reply
      const replyText = await getGeminiReply(recentMessages, systemPrompt);

      if (replyText) {
        this.addStaffMessage(replyText);
      } else {
        // Fallback if API fails
        this.addStaffMessage("I'm having trouble connecting to the support server. Please try again later or email support@raiyansoft.com.");
      }
    } catch (error) {
      console.error("AI Generation Error", error);
      this.addStaffMessage("Sorry, something went wrong. Please try again.");
    } finally {
      this.setThinking(false);
    }
  }

  addStaffMessage(text: string, senderName = 'Raiyansoft Support') {
    const newMessage: Message = {
      id: `msg_${Date.now()}_staff`,
      roomId: ROOM_ID,
      senderId: 'staff_ai',
      senderName,
      senderRole: 'staff',
      text,
      createdAt: Date.now()
    };
    this.messages.push(newMessage);
    this.saveMessages();
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());
  const [isThinking, setIsThinking] = useState(chatStore.getThinkingState());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
      setIsThinking(chatStore.getThinkingState());
    };

    // Initial sync
    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages, isThinking };
};

