export type UserRole = 'Customer' | 'Guest' | 'Admin';
export type UserStatus = 'Active' | 'Disabled';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  role: UserRole;
  status: UserStatus;
