}

const STORAGE_KEY = 'rs_admin_users';

// Helpers for demo data
const FIRST_NAMES = ['Nader', 'Sarah', 'Ahmed', 'Layla', 'Mohammed', 'Fatima', 'Ali', 'Zainab', 'Omar', 'Noura', 'Khalid', 'Dana', 'Yousef', 'Mariam', 'Fahad', 'Hessa'];
const LAST_NAMES = ['Al-Sabah', 'Ahmed', 'Khoury', 'Ali', 'Al-Mutairi', 'Al-Otaibi', 'Salem', 'Hassan', 'Abdullah', 'Al-Rashid'];
const DOMAINS = ['gmail.com', 'yahoo.com', 'outlook.com', 'icloud.com', 'raiyansoft.com'];

const generateDemoUsers = (count: number): User[] => {
  const users: User[] = [];
  const now = Date.now();
  const day = 86400000;

  for (let i = 0; i < count; i++) {
    const firstName = FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)];
    const lastName = LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)];
