    users.push({
      id: `user_${now - i * 1000}`,
      firstName,
      lastName,
      email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}${Math.floor(Math.random() * 99)}@${DOMAINS[Math.floor(Math.random() * DOMAINS.length)]}`,
      phone: `+965 ${Math.floor(Math.random() * 90000000) + 50000000}`,
      role,
      status: Math.random() > 0.9 ? 'Disabled' : 'Active',
      registeredAt: now - Math.floor(Math.random() * 365 * day),
      lastLoginAt: now - Math.floor(Math.random() * 30 * day),
      projectsCount: role === 'Guest' ? 0 : Math.floor(Math.random() * 5)
    });
  }

  // Ensure specific demo user exists
  users.unshift({
    id: 'user_demo_1',
    firstName: 'Nader',
    lastName: 'Ahmed',
    email: 'nader@demo.com',
    phone: '+965 5555 0000',
    role: 'Customer',
    status: 'Active',
    registeredAt: now - 10 * day,
    lastLoginAt: now - 2 * 3600000,
    projectsCount: 3
  });

  return users;
};

class UserStore {
  private users: User[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.load();
  }

  private load() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.users = JSON.parse(stored);
      } else {
        this.users = generateDemoUsers(20);
        this.save();
      }
    } catch (e) {
      console.error("Failed to load users", e);
      this.users = [];
    }
  }

  private save() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.users));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getUsers() {
    // Return sorted by registration date (newest first)
    return [...this.users].sort((a, b) => b.registeredAt - a.registeredAt);
  }

  toggleStatus(id: string) {
    const user = this.users.find(u => u.id === id);
    if (user) {
      user.status = user.status === 'Active' ? 'Disabled' : 'Active';
      this.save();
    }
  }

  deleteUser(id: string) {
    this.users = this.users.filter(u => u.id !== id);
    this.save();
  }
}

export const userStore = new UserStore();

export const useUsers = () => {
  const [users, setUsers] = useState<User[]>(userStore.getUsers());

  useEffect(() => {
    const update = () => setUsers(userStore.getUsers());
    update();
    return userStore.subscribe(update);
  }, []);

  return { users };
};

