// Scrolls the container to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    const scrollContainer = document.querySelector('.overflow-y-auto');
    if (scrollContainer) {
      scrollContainer.scrollTop = 0;
    }
  }, [pathname]);
  return null;
}

// Layout for the Mobile App
const MobileAppLayout = () => {
  const location = useLocation();

  const mainTabs = ['/home', '/support', '/news', '/notifications', '/more'];
  const showBottomNav = mainTabs.includes(location.pathname);

  return (
    <MobileShell>
      <ScrollToTop />
      {/* Route Content with Error Boundary */}
      <ErrorBoundary>
        <AnimatePresence mode="wait">
          <Routes location={location} key={location.pathname}>
            <Route path="/" element={<Splash />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/home" element={<Home />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/support" element={<SupportChat />} />
            <Route path="/news" element={<Placeholder title="News" />} />
            <Route path="/notifications" element={<Notifications />} />

            {/* More Section */}
            <Route path="/more" element={<More />} />
            <Route path="/more/settings" element={<MoreSettings />} />
            <Route path="/more/about" element={<MoreAbout />} />
            <Route path="/more/terms" element={<MoreTerms />} />
            <Route path="/more/privacy" element={<MorePrivacy />} />

            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </AnimatePresence>
      </ErrorBoundary>

      {/* Persistent Bottom Navigation */}
      {showBottomNav && <BottomNav />}
    </MobileShell>
  );
};

// Admin Guard
const ProtectedAdminRoute = ({ children }: { children?: React.ReactNode }) => {
  const isAdminAuth = localStorage.getItem('adminAuth') === 'true';
  if (!isAdminAuth) {
    return <Navigate to="/admin/login" replace />;
  }
  return <>{children}</>;
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <Routes>
        {/* Admin Routes - Full Screen, No MobileShell */}
        <Route path="/admin/login" element={<AdminLogin />} />

        <Route path="/admin/*" element={
          <ProtectedAdminRoute>
            <AdminLayout>
              <Routes>
                <Route path="projects" element={<AdminProjects />} />
                <Route path="users" element={<AdminUsers />} />
                <Route path="ai" element={<AdminAI />} />
                {/* Default admin route */}
                <Route path="*" element={<Navigate to="/admin/projects" replace />} />
              </Routes>
            </AdminLayout>
          </ProtectedAdminRoute>
        } />

        {/* Main App Routes - Wrapped in MobileShell */}
        <Route path="/*" element={<MobileAppLayout />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    error: null
  };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center text-slate-400">
          <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mb-4 border border-white/5">
            <AlertTriangle className="text-amber-500" size={32} />
          </div>
          <h2 className="text-xl font-bold text-white mb-2">Something went wrong</h2>
          <p className="text-sm mb-6">We couldn't load this section.</p>
          <button
            onClick={() => {
              this.setState({ hasError: false, error: null });
              window.location.reload();
            }}
            className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

