class RoleStore {
  private roles: Role[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.load();
  }

  private load() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.roles = JSON.parse(stored);
      } else {
        this.roles = DEFAULT_ROLES;
        this.save();
      }
    } catch (e) {
      console.error("Failed to load roles", e);
      this.roles = DEFAULT_ROLES;
    }
  }

  private save() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.roles));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getRoles() {
    return [...this.roles];
  }

  getRole(id: string) {
    return this.roles.find(r => r.id === id);
  }

  addRole(role: Omit<Role, 'id' | 'createdAt'>) {
    const newRole: Role = {
      ...role,
      id: `role_${Date.now()}`,
      createdAt: Date.now()
    };
    this.roles.push(newRole);
    this.save();
  }

  updateRole(id: string, updates: Partial<Omit<Role, 'id' | 'createdAt'>>) {
    const index = this.roles.findIndex(r => r.id === id);
    if (index !== -1) {
      this.roles[index] = { ...this.roles[index], ...updates };
      this.save();
    }
  }

  deleteRole(id: string) {
    // Prevent deleting seeded super admin if needed, but for demo allow everything except maybe hardcoded logic
    this.roles = this.roles.filter(r => r.id !== id);
    this.save();
  }
}

export const roleStore = new RoleStore();

export const useRoles = () => {
  const [roles, setRoles] = useState<Role[]>(roleStore.getRoles());

  useEffect(() => {
    const update = () => setRoles(roleStore.getRoles());
    update();
    return roleStore.subscribe(update);
  }, []);

  return { roles };
};

