import { useState, useEffect } from 'react';

export type TargetType = 'all' | 'single';

export interface NotificationTarget {
  type: TargetType;
  userId?: string;
  userName?: string; // For display in history
}

export interface NotificationPayload {
  id: string;
  target: NotificationTarget;
  title: string;
  body: string;
  imageUrl?: string;
  deepLink?: string;
  scheduledAt?: number; // timestamp, if null/undefined it means "now"
  createdAt: number;
  status: 'sent' | 'scheduled';
}

const STORAGE_KEY = 'rs_marketing_notifications_history';

class MarketingStore {
  private history: NotificationPayload[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.load();
  }

  private load() {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.history = JSON.parse(stored);
      }
    } catch (e) {
      console.error("Failed to load marketing history", e);
      this.history = [];
    }
  }

  private save() {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.history));
    this.notify();
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getHistory() {
    return [...this.history].sort((a, b) => b.createdAt - a.createdAt);
  }

  async sendNotification(data: Omit<NotificationPayload, 'id' | 'createdAt' | 'status'>): Promise<void> {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1200));

    const newNotification: NotificationPayload = {
      ...data,
      id: `notif_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      createdAt: Date.now(),
      status: data.scheduledAt && data.scheduledAt > Date.now() ? 'scheduled' : 'sent'
    };

    this.history.unshift(newNotification);
    // Keep only last 50 items
    if (this.history.length > 50) {
      this.history = this.history.slice(0, 50);
    }
    this.save();
  }
}

export const marketingStore = new MarketingStore();

export const useMarketingHistory = () => {
  const [history, setHistory] = useState<NotificationPayload[]>(marketingStore.getHistory());

  useEffect(() => {
    const update = () => setHistory(marketingStore.getHistory());
    update();
    return marketingStore.subscribe(update);
  }, []);

  return { history };
};

import { useState, useEffect } from 'react';

export interface UserProject {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  name: string;
  description: string;
  createdAt: number;
  updatedAt: number;
  version?: string; // Optional for display
  iconBg?: string; // Optional for display
}

const STORAGE_KEY = 'rs_user_projects';
const BROADCAST_CHANNEL = 'rs_user_projects_sync';

// Demo Data Seeding
const DEMO_NAMES = ['Raiyan CRM', 'EasyShop', 'RGPT Support', 'HealthTrack', 'EduLearn', 'Foodie App', 'CryptoDash', 'TaskMaster', 'FitLife', 'TravelGo'];
const DEMO_OWNERS = [
  { name: 'Nader Ahmed', email: 'nader@demo.com' },
  { name: 'Sarah Al-Salem', email: 'sarah@demo.com' },
  { name: 'John Doe', email: 'john@demo.com' }
];

const generateDemoProjects = (): UserProject[] => {
  return Array.from({ length: 12 }).map((_, i) => {
    const owner = DEMO_OWNERS[i % DEMO_OWNERS.length];
    return {
      id: `u_proj_${Date.now() - i * 100000}`,
      ownerId: `user_${i % 3}`, // Simple mapping for demo
      ownerName: owner.name,
      ownerEmail: owner.email,
      name: DEMO_NAMES[i % DEMO_NAMES.length] + (i > 9 ? ` ${i}` : ''),
      description: 'A comprehensive solution for managing business operations and customer relationships effectively.',
      createdAt: Date.now() - (i * 86400000),
      updatedAt: Date.now() - (i * 3600000),
      version: `v1.${i}.0`,
      iconBg: ['bg-blue-600', 'bg-emerald-600', 'bg-violet-600', 'bg-amber-600'][i % 4]
    };
  });
};

class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private channel: BroadcastChannel | null = null;

  constructor() {
    if (typeof window !== 'undefined') {
      this.channel = new BroadcastChannel(BROADCAST_CHANNEL);
      this.channel.onmessage = (event) => {
        if (event.data === 'update') {
          this.load(false); // Reload without broadcasting back
        }
      };

      // Also listen to storage events for cross-tab sync fallback
      window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY) {
          this.load(false);
        }
      });

      this.load();
    }
  }

  private load(shouldBroadcast = true) {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.projects = JSON.parse(stored);
      } else {
        this.projects = generateDemoProjects();
        this.save(false); // Initial save don't broadcast loop
      }
      this.notify();
    } catch (e) {
      console.error("Failed to load user projects", e);
      this.projects = [];
    }
  }

  private save(shouldBroadcast = true) {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.projects));
    this.notify();
    if (shouldBroadcast && this.channel) {
      this.channel.postMessage('update');
    }
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects].sort((a, b) => b.updatedAt - a.updatedAt);
  }

  getUserProjects(ownerId?: string) {
    // If no ownerId (e.g. guest), return empty or specific guest logic
    if (!ownerId) return [];

    // For demo purposes, we map the hardcoded 'Nader Ahmed' login to 'user_0'
    // In a real app, this would be the actual auth ID.
    const effectiveId = ownerId === 'auth_true' ? 'user_0' : ownerId; 

    return this.projects.filter(p => p.ownerId === effectiveId || p.ownerName === localStorage.getItem('user_name'))
      .sort((a, b) => b.createdAt - a.createdAt);
  }

  addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    const newProject: UserProject = {
      ...project,
      id: `u_proj_${Date.now()}`,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      version: 'v1.0.0', // Default
      iconBg: 'bg-primary' // Default
    };
    this.projects.unshift(newProject);
    this.save();
    return newProject;
  }

  updateProject(id: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    const index = this.projects.findIndex(p => p.id === id);
    if (index !== -1) {
      this.projects[index] = { 
        ...this.projects[index], 
        ...updates, 
        updatedAt: Date.now() 
      };
      this.save();
    }
  }

  deleteProject(id: string) {
    this.projects = this.projects.filter(p => p.id !== id);
    this.save();
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

