);

interface ProjectCardProps {
  name: string;
  description: string;
  logoUrl: string;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ name, description, logoUrl }) => (
  <motion.div
    whileHover={{ y: -2, backgroundColor: "rgba(30, 41, 59, 0.6)" }}
    whileTap={{ scale: 0.98 }}
    className="bg-slate-800/40 border border-white/5 p-3 rounded-2xl mb-3 flex items-center space-x-3 transition-colors cursor-pointer"
  >
    <div className="w-12 h-12 rounded-xl overflow-hidden shrink-0 border border-white/10 relative bg-slate-800 shadow-md">
      <SafeImage
        src={logoUrl}
        alt={name}
