const Home: React.FC = () => {
  const navigate = useNavigate();
  const userName = localStorage.getItem('user_name') || 'Guest';
  const userEmail = localStorage.getItem('user_email') || 'guest@demo.com'; 

  const { projects: clientProjects } = useProjects();
  const displayedClientProjects = clientProjects.slice(0, 3);

  const { store } = useUserProjects(); 
  const userCreatedProjects = store.getUserProjects(userName);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newProjectData, setNewProjectData] = useState({ name: '', description: '' });

  const handleAddProject = (e: React.FormEvent) => {
    e.preventDefault();
    userProjectsStore.addProject({
      name: newProjectData.name,
      description: newProjectData.description,
      ownerName: userName,
      ownerEmail: userEmail,
      ownerId: userName,
      estimatedPrice: null,
      estimatedDuration: null,
      status: 'pricing',
      projectUrl: null
    });
    setNewProjectData({ name: '', description: '' });
    setIsAddModalOpen(false);
  };

  return (
    <div className="flex flex-col h-full pb-20 relative overflow-y-auto no-scrollbar">
      {/* Header */}
      <header className="p-6 pb-2 flex justify-between items-center z-20">
        <motion.button 
          whileTap={{ scale: 0.9 }}
          className="w-10 h-10 bg-slate-800/50 rounded-full flex items-center justify-center border border-white/5"
        >
          <Bell size={20} className="text-white" />
        </motion.button>

        <div className="flex items-center space-x-3 bg-slate-800/50 pl-4 pr-1 py-1 rounded-full border border-white/5">
          <span className="text-sm font-medium text-white">Hi, {userName} 👋</span>
          <div className="w-8 h-8 rounded-full border-2 border-primary/30 overflow-hidden">
            <AvatarInitial name={userName} className="w-full h-full text-sm" />
          </div>
        </div>
      </header>

      <div className="p-6 space-y-8">
        {/* My Apps Section */}
        <section>
          <h2 className="text-lg font-bold text-white mb-4 flex items-center">
            <span className="w-1 h-5 bg-primary rounded-full mr-2"></span>
            My Apps
          </h2>
          <div className="flex flex-col">
            {userCreatedProjects.length > 0 ? (
              userCreatedProjects.map(app => (
                <AppCard 
                  key={app.id}
                  id={app.id}
                  name={app.name} 
                  version={app.version || 'v1.0.0'} 
                  description={app.description}
                  iconBg={app.iconBg || 'bg-slate-700'}
                  onOpen={() => navigate(`/projects/${app.id}`)}
                />
              ))
            ) : (
              // Fallback UI (Non-interactive)
              <>
                <div className="opacity-50 pointer-events-none">
                  <AppCard id="demo1" name="Raiyan CRM" version="v1.2.0" iconBg="bg-blue-600" onOpen={() => {}} />
                  <AppCard id="demo2" name="EasyShop" version="v3.4.1" iconBg="bg-emerald-600" onOpen={() => {}} />
                  <AppCard id="demo3" name="RGPT Support" version="v0.9.8" iconBg="bg-violet-600" onOpen={() => {}} />
                </div>
                <p className="text-xs text-center text-slate-500 mt-2">Create your first project to enable details view.</p>
              </>
            )}
          </div>
        </section>

        {/* CTA Button */}
        <motion.button
          onClick={() => setIsAddModalOpen(true)}
          whileHover={{ scale: 1.02, shadow: "0 0 25px rgba(29,183,240,0.4)" }}
          whileTap={{ scale: 0.98 }}
          className="w-full bg-gradient-to-r from-primary to-blue-500 rounded-2xl p-4 flex items-center justify-between shadow-[0_0_15px_rgba(29,183,240,0.2)] group"
        >
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
              <Plus size={24} className="text-white" />
            </div>
            <span className="text-white font-semibold">Add your first project 🚀</span>
          </div>
          <ChevronRight className="text-white/70 group-hover:translate-x-1 transition-transform" />
        </motion.button>

        {/* Latest Client Projects Section */}
        <section>
          <div className="flex justify-between items-end mb-4">
            <h2 className="text-lg font-bold text-white flex items-center">
              <span className="w-1 h-5 bg-primary rounded-full mr-2"></span>
              Latest Client Projects
            </h2>
            <button 
              onClick={() => navigate('/projects')}
              className="text-xs text-primary font-medium hover:text-blue-300 transition-colors"
            >
              View all
            </button>
          </div>
          <div className="grid gap-1">
            {displayedClientProjects.length > 0 ? (
              displayedClientProjects.map((project) => (
