            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-[#0f172a] w-full max-w-[350px] rounded-2xl border border-white/10 shadow-2xl overflow-hidden"
