                <button onClick={() => setIsAddModalOpen(false)} className="text-slate-400 hover:text-white">
                  <X size={20} />
                </button>
              </div>
              <div className="p-4">
                <form id="addProjectForm" onSubmit={handleAddProject} className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-300 ml-1">Project Name</label>
                    <input 
                      type="text" 
                      required
                      autoFocus
                      value={newProjectData.name}
                      onChange={e => setNewProjectData({...newProjectData, name: e.target.value})}
                      className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none transition-colors"
                      placeholder="My Awesome App"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-300 ml-1">Short Description</label>
                    <textarea 
                      required
                      maxLength={100}
                      value={newProjectData.description}
                      onChange={e => setNewProjectData({...newProjectData, description: e.target.value})}
                      className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none transition-colors h-20 resize-none"
                      placeholder="What does it do?"
                    />
                  </div>
                </form>
              </div>
              <div className="p-4 border-t border-white/10 bg-slate-900/50 flex gap-3">
                 <button 
                   onClick={() => setIsAddModalOpen(false)}
                   className="flex-1 py-2.5 rounded-xl text-slate-400 hover:text-white font-medium text-sm transition-colors"
                 >
                   Cancel
                 </button>
                 <button 
                   form="addProjectForm"
                   type="submit"
                   className="flex-1 py-2.5 rounded-xl bg-primary hover:bg-sky-400 text-white font-medium text-sm shadow-lg shadow-primary/20 flex items-center justify-center gap-2"
                 >
                   <Save size={16} /> Create
                 </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Home;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, LayoutGrid, Edit2, X, Save, Clock, User as UserIcon, Link as LinkIcon, DollarSign, Activity } from 'lucide-react';
import { useUserProjects, UserProject, ProjectStatus } from '../../lib/userProjectsStore';
import AvatarInitial from '../../components/AvatarInitial';

const statusOptions: ProjectStatus[] = ["pricing", "design", "development", "publishing", "support", "cancelled"];

const AdminUserProjects: React.FC = () => {
  const { projects, store } = useUserProjects();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'All' | 'Active' | 'Archived'>('All');

  // Edit Modal State
  const [editingProject, setEditingProject] = useState<UserProject | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    estimatedPrice: '' as string | number,
    estimatedDuration: '' as string | number,
    status: 'pricing' as ProjectStatus,
    projectUrl: ''
  });
  const [isSaving, setIsSaving] = useState(false);

  // Filter Logic
  const filteredProjects = projects.filter(p => {
    const matchesSearch = 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.ownerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.ownerEmail.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch; 
  });

  const handleEdit = (project: UserProject) => {
    setEditingProject(project);
    setFormData({ 
      name: project.name, 
      description: project.description,
      estimatedPrice: project.estimatedPrice || '',
      estimatedDuration: project.estimatedDuration || '',
      status: project.status || 'pricing',
      projectUrl: project.projectUrl || ''
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProject) return;

    setIsSaving(true);
    // Simulate network delay
    setTimeout(() => {
      store.updateProject(editingProject.id, {
        name: formData.name,
        description: formData.description,
        estimatedPrice: formData.estimatedPrice ? Number(formData.estimatedPrice) : null,
        estimatedDuration: formData.estimatedDuration ? Number(formData.estimatedDuration) : null,
        status: formData.status,
        projectUrl: formData.projectUrl || null
      });
      setEditingProject(null);
      setIsSaving(false);
    }, 600);
  };

  const formatDate = (ts: number) => new Date(ts).toLocaleDateString('en-UK', { day: 'numeric', month: 'short', year: 'numeric' });

  return (
    <div className="space-y-8 pb-20">

      {/* Header */}
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-bold text-white flex items-center gap-3">
          User Projects
          <span className="text-xs font-normal text-slate-400 bg-slate-800 px-2 py-1 rounded-full border border-white/5">
            {filteredProjects.length} Total
          </span>
        </h1>
        <p className="text-slate-400 text-sm">Projects created by customers inside their accounts.</p>
      </div>

      {/* Controls */}
      <div className="flex flex-col md:flex-row gap-4 bg-[#0f172a] p-4 rounded-2xl border border-white/5 shadow-lg">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search by project, customer, or email..."
            className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl py-2.5 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:border-primary transition-colors"
          />
        </div>
      </div>

      {/* Projects Table */}
      <div className="bg-[#0f172a] border border-white/5 rounded-2xl shadow-xl overflow-hidden min-h-[400px]">
        {filteredProjects.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-500">
            <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mb-4 border border-white/5">
