      <div className="space-y-5">

        {/* Basic Info Block */}
        <div className="space-y-3 bg-slate-800/30 p-4 rounded-2xl border border-white/5">
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase">Project Name</label>
            <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none" />
          </div>
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Description (Auto-generated)</label>
             <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full h-24 bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none resize-none text-sm leading-relaxed" />
          </div>
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Brand Color</label>
             <div className="flex gap-2">
                <input type="color" value={formData.brandColor} onChange={e => setFormData({...formData, brandColor: e.target.value})} className="h-9 w-12 rounded cursor-pointer bg-transparent" />
                <input type="text" value={formData.brandColor} onChange={e => setFormData({...formData, brandColor: e.target.value})} className="flex-1 bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none uppercase font-mono" />
             </div>
          </div>
        </div>

        {/* Configuration Block */}
        <div className="space-y-4 bg-slate-800/30 p-4 rounded-2xl border border-white/5">

          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Platforms</label>
            <div className="flex flex-wrap gap-2">
              {PLATFORMS.map(p => (
                <button key={p} onClick={() => toggleArray(formData.platforms, p, 'platforms')} className={`px-3 py-1.5 rounded-lg text-xs font-medium border ${formData.platforms.includes(p) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10'}`}>{p}</button>
              ))}
            </div>
          </div>

          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Languages</label>
            <div className="flex flex-wrap gap-2">
              {LANGUAGES.map(l => (
                <button key={l} onClick={() => toggleArray(formData.languages, l, 'languages')} className={`px-3 py-1.5 rounded-lg text-xs font-medium border ${formData.languages.includes(l) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10'}`}>{l}</button>
              ))}
            </div>
          </div>

          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Markets</label>
            <div className="flex flex-wrap gap-2">
              {MARKETS.map(m => (
                <button key={m} onClick={() => toggleArray(formData.markets, m, 'markets')} className={`px-3 py-1.5 rounded-lg text-xs font-medium border ${formData.markets.includes(m) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10'}`}>{m}</button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 pt-2">
             <div>
               <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Payments</label>
               <select 
                 value={formData.hasPayments ? 'yes' : 'no'} 
                 onChange={e => setFormData({...formData, hasPayments: e.target.value === 'yes'})}
                 className="w-full bg-slate-900 border border-white/10 rounded-lg px-2 py-2 text-white text-sm"
               >
                 <option value="yes">Yes</option>
                 <option value="no">No</option>
               </select>
             </div>
             <div>
               <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Existing Biz</label>
               <select 
                 value={formData.hasExistingBusiness ? 'yes' : 'no'} 
                 onChange={e => setFormData({...formData, hasExistingBusiness: e.target.value === 'yes'})}
                 className="w-full bg-slate-900 border border-white/10 rounded-lg px-2 py-2 text-white text-sm"
               >
                 <option value="yes">Yes</option>
                 <option value="no">No</option>
               </select>
             </div>
          </div>

          <div>
             <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Service Model</label>
             <select 
                 value={formData.serviceModel} 
                 onChange={e => setFormData({...formData, serviceModel: e.target.value})}
                 className="w-full bg-slate-900 border border-white/10 rounded-lg px-2 py-2 text-white text-sm"
               >
                 {SERVICE_MODELS.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          <div>
             <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Closest App</label>
             <select 
                 value={formData.closestApp} 
                 onChange={e => setFormData({...formData, closestApp: e.target.value})}
                 className="w-full bg-slate-900 border border-white/10 rounded-lg px-2 py-2 text-white text-sm"
               >
                 {CLOSEST_APPS.map(a => <option key={a} value={a}>{a}</option>)}
             </select>
          </div>

        </div>

      </div>
    </div>
  );

  // Main Render Switch
  const renderStep = () => {
    switch (step) {
      case 0: return renderIntro();
      case 1: return renderMultiSelect("Which platforms do you need?", PLATFORMS, formData.platforms, 'platforms');
      case 2: return renderMultiSelect("Which languages do you need?", LANGUAGES, formData.languages, 'languages');
      case 3: return renderMultiSelect("Which markets are you targeting?", MARKETS, formData.markets, 'markets');
      case 4: return renderSingleChoice("Will your app include in-app payments?", [{label:'Yes', value: true}, {label: 'No', value: false}], formData.hasPayments, 'hasPayments', true);
      case 5: return renderSingleChoice("Do you already have an active business?", [{label:'Yes', value: true}, {label: 'No', value: false}], formData.hasExistingBusiness, 'hasExistingBusiness', true);
      case 6: return renderSingleChoice("How will the service be delivered?", SERVICE_MODELS, formData.serviceModel, 'serviceModel');
      case 7: return renderSingleChoice("Which app is closest to your idea?", CLOSEST_APPS, formData.closestApp, 'closestApp');
      case 8: return renderTextInput("What is the initial name for your app?", formData.name, 'name', "e.g. Super Delivery");
      case 9: return renderColorPicker();
      case 10: return renderGuestSignup();
      case 11: return renderReview();
      default: return null;
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-[#020617] flex flex-col h-full w-full">
      {/* Header */}
      <div className="px-6 py-4 flex items-center justify-between border-b border-white/5 bg-[#0f172a]">
        <button onClick={step === 0 ? onClose : prevStep} className="p-2 -ml-2 text-slate-400 hover:text-white transition-colors">
          {step === 0 ? <X size={24} /> : <ChevronLeft size={24} />}
        </button>
        <div className="flex space-x-1.5">
          {Array.from({ length: isAuthenticated ? 11 : 12 }).map((_, i) => (
             <div 
               key={i} 
               className={`h-1.5 rounded-full transition-all duration-300 ${i === step ? 'w-6 bg-primary' : i < step ? 'w-1.5 bg-primary/50' : 'w-1.5 bg-slate-800'}`}
             />
          ))}
        </div>
        <div className="w-10" /> {/* Spacer for centering */}
      </div>

      {/* Content Area */}
      <div className="flex-1 relative overflow-hidden">
        <AnimatePresence initial={false} custom={direction}>
          <motion.div
            key={step}
            custom={direction}
            initial={{ x: direction > 0 ? 300 : -300, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: direction > 0 ? -300 : 300, opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="absolute inset-0 w-full h-full"
          >
            {renderStep()}
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Footer / Controls */}
      <div className="p-6 pb-8 border-t border-white/5 bg-[#0f172a] z-20">

        {/* Error Message */}
        {errors.length > 0 && (
          <motion.div 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }}
            className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-medium text-center"
          >
            {errors[0]}
          </motion.div>
        )}

        {step === 0 ? null : (
          <button 
            onClick={step === 11 ? handleCreate : nextStep}
            className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center space-x-2"
          >
            <span>{step === 11 ? (isAuthenticated ? 'Create Project' : 'Create Account & Project') : step === 10 ? 'Create Account' : 'Next'}</span>
            {step !== 11 && <ChevronRight size={20} />}
          </button>
        )}
      </div>
    </div>
  );
};

export default ProjectWizard;

