        />
      </div>
    </div>
  );

  const renderGuestSignup = () => (
    <div className="flex flex-col h-full p-6 overflow-y-auto no-scrollbar">
       <h2 className="text-2xl font-bold text-white mb-2">Create your account</h2>
       <p className="text-slate-400 text-sm mb-6">Save your project progress by creating an account.</p>

       <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
               <label className="text-xs text-slate-400 ml-1">First Name</label>
               <input type="text" value={formData.guestFirstName} onChange={e => setFormData({...formData, guestFirstName: e.target.value})} className="w-full bg-slate-800 rounded-xl px-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
            </div>
            <div className="space-y-1">
               <label className="text-xs text-slate-400 ml-1">Last Name</label>
               <input type="text" value={formData.guestLastName} onChange={e => setFormData({...formData, guestLastName: e.target.value})} className="w-full bg-slate-800 rounded-xl px-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
            </div>
          </div>
          <div className="space-y-1">
             <label className="text-xs text-slate-400 ml-1">Email</label>
             <div className="relative">
                <Mail size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/>
                <input type="email" value={formData.guestEmail} onChange={e => setFormData({...formData, guestEmail: e.target.value})} className="w-full bg-slate-800 rounded-xl pl-10 pr-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
