class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private channel: BroadcastChannel | null = null;

  constructor() {
    if (typeof window !== 'undefined') {
      this.channel = new BroadcastChannel(BROADCAST_CHANNEL);
      this.channel.onmessage = (event) => {
        if (event.data === 'update') {
          this.load(false); // Reload without broadcasting back
        }
      };

      // Also listen to storage events for cross-tab sync fallback
      window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY) {
          this.load(false);
        }
      });

      this.load();
    }
  }

  private load(shouldBroadcast = true) {
    if (typeof window === 'undefined') return;
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.projects = JSON.parse(stored);
      } else {
        this.projects = generateDemoProjects();
        this.save(false); // Initial save don't broadcast loop
      }
      this.notify();
    } catch (e) {
      console.error("Failed to load user projects", e);
      this.projects = [];
    }
  }

  private save(shouldBroadcast = true) {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.projects));
    this.notify();
    if (shouldBroadcast && this.channel) {
      this.channel.postMessage('update');
    }
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects].sort((a, b) => b.updatedAt - a.updatedAt);
  }

  getUserProjects(ownerId?: string) {
    // If no ownerId (e.g. guest), return empty or specific guest logic
    if (!ownerId) return [];

    // For demo purposes, we map the hardcoded 'Nader Ahmed' login to 'user_0'
    // In a real app, this would be the actual auth ID.
    // Also matching by name for demo simplicity if ID mismatch occurs
    const currentUserName = localStorage.getItem('user_name');

    return this.projects.filter(p => 
      p.ownerId === ownerId || 
      p.ownerName === currentUserName ||
      (ownerId === 'user_0' && p.ownerId === 'user_0') // Demo fallback
    ).sort((a, b) => b.createdAt - a.createdAt);
  }

  addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    const newProject: UserProject = {
      ...project,
      id: `u_proj_${Date.now()}`,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      version: 'v1.0.0', // Default
      iconBg: project.brandColor 
        ? undefined // If brand color is set, UI might handle it, or we fallback to bg-primary
        : 'bg-primary' 
    };
    this.projects.unshift(newProject);
    this.save();
    return newProject;
  }

  updateProject(id: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    const index = this.projects.findIndex(p => p.id === id);
    if (index !== -1) {
      this.projects[index] = { 
        ...this.projects[index], 
        ...updates, 
        updatedAt: Date.now() 
      };
      this.save();
    }
  }

  deleteProject(id: string) {
    this.projects = this.projects.filter(p => p.id !== id);
    this.save();
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

