               <select 
                 value={formData.hasExistingBusiness ? 'yes' : 'no'} 
                 onChange={e => setFormData({...formData, hasExistingBusiness: e.target.value === 'yes'})}
                 className="w-full bg-slate-900 border border-white/10 rounded-lg px-2 py-2 text-white text-sm"
               >
                 <option value="yes">Yes</option>
                 <option value="no">No</option>
               </select>
