    <div className="flex flex-col h-full relative overflow-y-auto no-scrollbar pb-24">

      {/* Header */}
      <div className="sticky top-0 z-20 bg-slate-900/90 backdrop-blur-md px-6 py-5 border-b border-white/5">
        <h1 className="text-2xl font-bold text-white">More</h1>
      </div>

      <div className="p-4 space-y-6">

        {/* Profile Card */}
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-slate-800/40 border border-white/5 p-4 rounded-2xl flex items-center space-x-4 shadow-lg backdrop-blur-sm relative overflow-hidden group"
        >
          {/* Subtle background gradient */}
          <div className="absolute inset-0 bg-gradient-to-r from-primary/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

          <div className="w-16 h-16 shrink-0">
            <AvatarInitial name={userName} className="w-full h-full text-2xl border-2 border-slate-700" />
          </div>

          <div className="flex-1 min-w-0 relative z-10">
            <h2 className="text-lg font-bold text-white truncate">{userName}</h2>
            <p className="text-slate-400 text-xs truncate mb-1">{userEmail}</p>
            <span className="text-xs text-primary font-medium">View profile</span>
          </div>
        </motion.div>

        {/* Menu Items */}
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="rounded-2xl border border-white/5 overflow-hidden shadow-lg"
        >
          <MoreListItem 
            icon={FolderOpen} 
            label="Files & Documents" 
            onClick={() => navigate('/more/files')} 
          />
          <MoreListItem 
            icon={Settings} 
            label="Settings" 
            onClick={() => navigate('/more/settings')} 
          />
          <MoreListItem 
            icon={Info} 
            label="About us" 
            onClick={() => navigate('/more/about')} 
          />
          <MoreListItem 
            icon={FileText} 
            label="Terms of Use" 
            onClick={() => navigate('/more/terms')} 
          />
          <MoreListItem 
            icon={ShieldCheck} 
            label="Privacy Policy" 
            onClick={() => navigate('/more/privacy')} 
          />
        </motion.div>

        {/* Actions */}
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="space-y-3"
