class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];

  constructor() {
    this.initFirestore();
  }

  private initFirestore() {
    if (typeof window === 'undefined' || !db) return;

    // Subscribe to the 'projects' collection, ordered by creation time
    try {
      const q = query(collection(db, 'projects'), orderBy('createdAt', 'desc'));
      onSnapshot(q, (snapshot) => {
        this.projects = snapshot.docs.map(doc => {
          const data = doc.data();
          return {
            ...data,
            id: doc.id,
            // Handle Firestore timestamps (convert to millis for app usage)
            createdAt: data.createdAt?.toMillis?.() || Date.now(),
            updatedAt: data.updatedAt?.toMillis?.() || Date.now(),
            // Ensure status fallback
            status: data.status || 'pricing'
          } as UserProject;
