    // userProjectsStore uses 'raiyansoft_projects' NO wait, that's projectStore (Portfolio).
    // userProjectsStore (My Apps) usually doesn't have a persisted key in the provided code, 
    // it was just a mock. But assuming it might have stored data:
    // We will look for common keys.

    // NOTE: The previous code for userProjectsStore actually didn't use localStorage in the provided snippet!
    // It was using a hardcoded array or empty.
    // However, projectStore used 'raiyansoft_projects'. 
    // chatStore used 'raiyansoft_chat_messages'.
    // notificationStore used 'raiyansoft_notifications'.

    // 2. Migrate Chat Messages
    const chatKey = 'raiyansoft_chat_messages';
    const storedChats = localStorage.getItem(chatKey);
    if (storedChats) {
      const chats = JSON.parse(storedChats);
      if (Array.isArray(chats)) {
        chats.forEach((msg: any) => {
           const newDocRef = doc(collection(db, 'users', uid, 'chats'));
           batch.set(newDocRef, {
             ...msg,
             migrated: true,
             createdAt: msg.createdAt || Date.now()
           });
           operationCount++;
        });
      }
    }

    // 3. Migrate Notifications
    const notifKey = 'raiyansoft_notifications';
    const storedNotifs = localStorage.getItem(notifKey);
    if (storedNotifs) {
      const notifs = JSON.parse(storedNotifs);
      if (Array.isArray(notifs)) {
        notifs.forEach((n: any) => {
          const newDocRef = doc(collection(db, 'users', uid, 'notifications'));
          batch.set(newDocRef, {
            ...n,
            migrated: true,
            timestamp: n.timestamp || Date.now()
          });
          operationCount++;
        });
      }
    }

    // 4. Mark Migration Complete
    batch.set(migrationRef, {
      migratedFromLocalStorage: true,
      migratedAt: serverTimestamp(),
      appVersion: '1.0.0'
    });
    operationCount++;

    if (operationCount > 0) {
      await batch.commit();
      console.log(`Migration complete. Moved ${operationCount} items.`);

      // Clear LocalStorage items that were migrated
      localStorage.removeItem(chatKey);
      localStorage.removeItem(notifKey);
    } else {
      console.log("No local data to migrate.");
       // Still mark as migrated so we don't check again
       await batch.commit();
    }

  } catch (error) {
    console.error("Migration failed:", error);
  }
}

import { useState, useEffect } from 'react';
import { 
  collection, 
  onSnapshot, 
  addDoc, 
