export type ProjectStatus = "pricing" | "design" | "development" | "publishing" | "support" | "cancelled";

export interface UserProject {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  name: string;
  description: string;
  estimatedPrice: number | null;
  estimatedDuration: number | null; // in days
  status: ProjectStatus;
  projectUrl?: string | null;
  createdAt: number;
  updatedAt: number;
  version?: string; // Optional for display
  iconBg?: string; // Optional for display

  // Wizard Fields
  platforms?: string[];
  languages?: string[];
  markets?: string[];
  industry?: string;
  industryOther?: string | null;
  hasPayments?: boolean;
  hasExistingBusiness?: boolean;
  serviceModel?: string;
  closestApp?: string;
  brandColor?: string;
}

class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private currentUid: string | null = null;

  constructor() {
    // Listen for auth changes to switch subscriptions
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.projects = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;

    // Unsubscribe previous listener if exists
    if (this.unsubscribe) this.unsubscribe();

    if (!db) return;

    const q = query(
      collection(db, 'users', uid, 'projects'), 
      orderBy('createdAt', 'desc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.projects = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now(),
          updatedAt: data.updatedAt?.toMillis?.() || Date.now(),
          status: data.status || 'pricing'
        } as UserProject;
      });
      this.notify();
    }, (error) => {
      console.error("Firestore userProjects error:", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects];
  }

  // Deprecated: No longer filters by ownerId argument, uses Auth UID
  getUserProjects(ownerId?: string) {
    return this.projects;
  }

  async addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    if (!db || !this.currentUid) {
        console.error("Cannot add project: No DB or not logged in");
        return;
    }
    try {
      await addDoc(collection(db, 'users', this.currentUid, 'projects'), {
        ...project,
        ownerId: this.currentUid, // Enforce ownerId match
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        version: 'v1.0.0',
        iconBg: project.brandColor ? undefined : 'bg-primary'
      });
    } catch (e) {
      console.error("Error adding project:", e);
      throw e;
    }
  }

  async updateProject(id: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    if (!db || !this.currentUid) return;
    try {
      const docRef = doc(db, 'users', this.currentUid, 'projects', id);
      await updateDoc(docRef, {
        ...updates,
        updatedAt: serverTimestamp()
      });
    } catch (e) {
      console.error("Error updating project:", e);
    }
  }

  async deleteProject(id: string) {
    if (!db || !this.currentUid) return;
    try {
      await deleteDoc(doc(db, 'users', this.currentUid, 'projects', id));
    } catch (e) {
      console.error("Error deleting project:", e);
    }
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

import { useEffect, useState } from 'react';
import { collection, addDoc, query, orderBy, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { getGeminiReply, ChatMessage } from './gemini';

export interface Message {
  id: string;
  roomId: string;
  senderId: string;
  senderName: string;
  senderRole: 'customer' | 'staff';
  text: string;
  createdAt: number;
}

const ROOM_ID = 'support-room';
const DEFAULT_SYSTEM_PROMPT = `You are Raiyansoft Support, the official support assistant for Raiyansoft®. Your job is to help customers.`;

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private isThinking: boolean = false;
  private currentUid: string | null = null;
  private unsubscribe: (() => void) | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.messages = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    const q = query(
      collection(db, 'users', uid, 'chats'),
      orderBy('createdAt', 'asc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.messages = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now()
        } as Message;
      });
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  getThinkingState() {
    return this.isThinking;
  }

  setThinking(state: boolean) {
    this.isThinking = state;
    this.notify();
  }

  async sendMessage(text: string) {
    if (!this.currentUid || !db) return;

    // 1. Add User Message to Firestore
    try {
       await addDoc(collection(db, 'users', this.currentUid, 'chats'), {
        roomId: ROOM_ID,
        senderId: this.currentUid,
        senderName: auth.currentUser?.displayName || 'User',
        senderRole: 'customer',
        text,
        createdAt: serverTimestamp()
      });
    } catch (e) {
      console.error("Error sending message", e);
      return;
    }

    // 2. Trigger AI Response
    this.setThinking(true);

    try {
      // Create context from last 10 messages
      const recentMessages = this.messages.slice(-10).map(m => ({
        role: m.senderRole === 'customer' ? 'user' : 'assistant',
        content: m.text
      } as ChatMessage));

      // Add the new message we just sent (in case snapshot hasn't updated yet)
      if (recentMessages.length === 0 || recentMessages[recentMessages.length-1].content !== text) {
          recentMessages.push({ role: 'user', content: text });
      }

      const replyText = await getGeminiReply(recentMessages, DEFAULT_SYSTEM_PROMPT);

      if (replyText) {
        await this.addStaffMessage(replyText);
      } else {
        await this.addStaffMessage("I'm having trouble connecting to the support server. Please try again later.");
      }
    } catch (error) {
      console.error("AI Generation Error", error);
      await this.addStaffMessage("Sorry, something went wrong.");
    } finally {
      this.setThinking(false);
    }
  }

  async addStaffMessage(text: string, senderName = 'Raiyansoft Support') {
    if (!this.currentUid || !db) return;
    await addDoc(collection(db, 'users', this.currentUid, 'chats'), {
      roomId: ROOM_ID,
      senderId: 'staff_ai',
      senderName,
      senderRole: 'staff',
      text,
      createdAt: serverTimestamp()
    });
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());
  const [isThinking, setIsThinking] = useState(chatStore.getThinkingState());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
      setIsThinking(chatStore.getThinkingState());
    };

    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages, isThinking };
};

import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, updateDoc, doc, where, writeBatch } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export type NotificationType = 'system' | 'success' | 'warning' | 'message' | 'payment';

export interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  timestamp: number;
  read: boolean;
  dismissed: boolean;
}

class NotificationStore {
  private notifications: Notification[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private currentUid: string | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.notifications = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Only fetch non-dismissed or recently dismissed if you prefer
    const q = query(
      collection(db, 'users', uid, 'notifications'), 
      orderBy('timestamp', 'desc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.notifications = snapshot.docs.map(doc => {
         const data = doc.data();
         return {
           ...data,
           id: doc.id,
           timestamp: data.timestamp || Date.now()
         } as Notification;
      }).filter(n => !n.dismissed); // Client-side filter for now
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getNotifications() {
    return this.notifications;
  }

  getUnreadCount() {
    return this.notifications.filter(n => !n.read).length;
  }

  async markAsRead(id: string) {
    if (!this.currentUid || !db) return;
    const notifRef = doc(db, 'users', this.currentUid, 'notifications', id);
    try {
      await updateDoc(notifRef, { read: true });
    } catch (e) {
      console.error("Error marking read", e);
    }
  }

  async markAllAsRead() {
    if (!this.currentUid || !db) return;
    const batch = writeBatch(db);
    const unread = this.notifications.filter(n => !n.read);

    unread.forEach(n => {
       const ref = doc(db, 'users', this.currentUid!, 'notifications', n.id);
       batch.update(ref, { read: true });
    });

    if (unread.length > 0) {
      await batch.commit();
    }
  }

  async dismiss(id: string) {
    if (!this.currentUid || !db) return;
    const notifRef = doc(db, 'users', this.currentUid, 'notifications', id);
    try {
      await updateDoc(notifRef, { dismissed: true });
    } catch (e) {
      console.error("Error dismissing", e);
    }
  }
}

export const notificationStore = new NotificationStore();

export const useNotifications = () => {
  const [data, setData] = useState({
    notifications: notificationStore.getNotifications(),
    unreadCount: notificationStore.getUnreadCount()
  });

  useEffect(() => {
    const update = () => {
      setData({
        notifications: notificationStore.getNotifications(),
        unreadCount: notificationStore.getUnreadCount()
      });
    };

    // Initial sync
    update();
    return notificationStore.subscribe(update);
  }, []);

  return data;
};

