import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from './firebase';

export type UserRole = 'Customer' | 'Guest' | 'Admin';
export type UserStatus = 'Active' | 'Disabled';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  role: UserRole;
  status: UserStatus;
  registeredAt: number;
  lastLoginAt: number;
  projectsCount: number;
}

class UserStore {
  private users: User[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  constructor() {
    this.subscribeToFirestore();
  }

  private subscribeToFirestore() {
    if (!db) return;

    try {
      const q = query(collection(db, 'users'), orderBy('createdAt', 'desc'));

      this.unsubscribe = onSnapshot(q, (snapshot) => {
        this.users = snapshot.docs.map(doc => {
          const data = doc.data();
          return {
            ...data,
            id: doc.id,
            // Safe convert Firestore Timestamp to millis
            registeredAt: data.createdAt?.toMillis?.() || Date.now(),
            lastLoginAt: data.lastLoginAt?.toMillis?.() || Date.now(),
            // Ensure defaults
            role: data.role || 'Customer',
            status: data.status || 'Active',
            projectsCount: data.projectsCount || 0
          } as User;
        });
        this.notify();
      }, (error) => {
        console.error("Firestore Users Listen Error:", error);
      });
    } catch (e) {
      console.error("UserStore init error:", e);
    }
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getUsers() {
    return [...this.users];
  }

  async toggleStatus(id: string) {
    if (!db) return;
    const user = this.users.find(u => u.id === id);
    if (user) {
      const newStatus = user.status === 'Active' ? 'Disabled' : 'Active';
      try {
        await updateDoc(doc(db, 'users', id), { status: newStatus });
      } catch (e) {
        console.error("Error toggling status:", e);
      }
    }
  }

  async deleteUser(id: string) {
    if (!db) return;
    try {
      await deleteDoc(doc(db, 'users', id));
    } catch (e) {
      console.error("Error deleting user:", e);
    }
  }
}

export const userStore = new UserStore();

export const useUsers = () => {
  const [users, setUsers] = useState<User[]>(userStore.getUsers());

  useEffect(() => {
    const update = () => setUsers(userStore.getUsers());
    update();
    return userStore.subscribe(update);
  }, []);

  return { users };
};

import { doc, getDoc, writeBatch, collection, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';
import { User } from 'firebase/auth';

/**
 * Migrates LocalStorage data to Firestore for the authenticated user.
 * It checks a flag in Firestore to ensure this only runs once.
 */
export async function migrateLocalStorageToFirestore(user: User) {
  if (!user || !db) return;

  const uid = user.uid;
  const migrationRef = doc(db, 'users', uid, 'settings', 'migration');

  try {
    const migrationSnap = await getDoc(migrationRef);
    if (migrationSnap.exists() && migrationSnap.data().migratedFromLocalStorage) {
      return; // Already migrated
    }

    console.log("Starting data migration from LocalStorage to Firestore...");
    const batch = writeBatch(db);
    let operationCount = 0;

    // 1. Migrate Projects
    // Potential keys based on common usage or previous versions
    const potentialProjectKeys = ['raiyansoft_user_projects', 'user_projects', 'projects'];

    for (const key of potentialProjectKeys) {
      const stored = localStorage.getItem(key);
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed)) {
             parsed.forEach((proj: any) => {
               const newDocRef = doc(collection(db, 'users', uid, 'projects'));
               batch.set(newDocRef, {
                 ...proj,
                 ownerId: uid, // Claim ownership
                 ownerName: user.displayName || 'User',
                 ownerEmail: user.email || '',
                 migrated: true,
                 createdAt: proj.createdAt ? new Date(proj.createdAt) : serverTimestamp(),
                 updatedAt: serverTimestamp()
               });
               operationCount++;
             });
          }
        } catch (e) {
          console.warn(`Failed to parse projects from key ${key}`, e);
        }
      }
    }

    // 2. Migrate Chat Messages
    const chatKey = 'raiyansoft_chat_messages';
    const storedChats = localStorage.getItem(chatKey);
    if (storedChats) {
      try {
        const chats = JSON.parse(storedChats);
        if (Array.isArray(chats)) {
          chats.forEach((msg: any) => {
             const newDocRef = doc(collection(db, 'users', uid, 'chats'));
             batch.set(newDocRef, {
               ...msg,
               migrated: true,
               createdAt: msg.createdAt ? new Date(msg.createdAt) : serverTimestamp()
             });
             operationCount++;
          });
        }
      } catch (e) { console.warn("Failed to parse chats", e); }
    }

    // 3. Migrate Notifications
    const notifKey = 'raiyansoft_notifications';
    const storedNotifs = localStorage.getItem(notifKey);
    if (storedNotifs) {
      try {
        const notifs = JSON.parse(storedNotifs);
        if (Array.isArray(notifs)) {
          notifs.forEach((n: any) => {
            const newDocRef = doc(collection(db, 'users', uid, 'notifications'));
            batch.set(newDocRef, {
              ...n,
              migrated: true,
              timestamp: n.timestamp || Date.now()
            });
            operationCount++;
          });
        }
      } catch (e) { console.warn("Failed to parse notifs", e); }
    }

    // 4. Mark Migration Complete
    batch.set(migrationRef, {
      migratedFromLocalStorage: true,
      migratedAt: serverTimestamp(),
      appVersion: '1.0.0'
    });
    operationCount++; // Count the migration flag write

    if (operationCount > 0) {
      await batch.commit();
      console.log(`Migration complete. moved ${operationCount} items.`);

      // Clear LocalStorage items that were migrated
      localStorage.removeItem(chatKey);
      localStorage.removeItem(notifKey);
      potentialProjectKeys.forEach(k => localStorage.removeItem(k));
    } else {
       // Mark as migrated even if nothing to move, so we don't check again
       await batch.commit();
    }

  } catch (error) {
    console.error("Migration failed:", error);
  }
}

