Here is the comprehensive implementation.

This solution introduces a **Multi-Tenant Architecture** using a constant Tenant ID (`raiyansoft`). It refactors all data stores to communicate with Firestore using real-time listeners and includes a robust migration script.

### 1. Security Rules (firestore.rules)
*Use these rules in your Firebase Console → Firestore Database → Rules.*

```text
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // Helper function to check if user is an employee/admin
    // (In a real app, use Custom Claims. Here we check the employees collection)
    function isEmployee(tenantId) {
      return exists(/databases/$(database)/documents/tenants/$(tenantId)/employees/$(request.auth.uid));
    }

    match /tenants/{tenantId} {

      // Users (Customers) - Can read/write their own profile
      match /users/{userId} {
        allow read, write: if request.auth != null && (request.auth.uid == userId || isEmployee(tenantId));
      }

      // Employees - Only readable by authenticated employees
      match /employees/{employeeId} {
        allow read: if request.auth != null; // Allow login checks
        allow write: if isEmployee(tenantId);
      }

      // Roles - Read by all authed, write by employees
      match /roles/{roleId} {
        allow read: if request.auth != null;
        allow write: if isEmployee(tenantId);
      }

      // Projects (Portfolio) - Public read, Employee write
      match /projects/{projectId} {
        allow read: if true;
        allow write: if isEmployee(tenantId);
      }

      // Apps (User Projects) - Owner read/write, Employee read/write
      match /apps/{appId} {
        allow read: if request.auth != null && (resource.data.ownerId == request.auth.uid || isEmployee(tenantId));
        allow create: if request.auth != null;
        allow update, delete: if request.auth != null && (resource.data.ownerId == request.auth.uid || isEmployee(tenantId));
      }

      // Notifications - Owner read, System/Employee write
      match /notifications/{notifId} {
        allow read: if request.auth != null; // Logic usually filtered by query
        allow write: if request.auth != null;
      }

      // Support Tickets / Chats
      match /chats/{chatId} {
        allow read, write: if request.auth != null;
      }

      // Settings
      match /settings/{docId} {
        allow read, write: if request.auth != null;
      }
    }
  }
}
```

