import { useState, useEffect } from 'react';
import { 
  collection, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  serverTimestamp, 
  query, 
  orderBy 
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { TENANT_ID } from './constants';

export type ProjectStatus = "pricing" | "design" | "development" | "publishing" | "support" | "cancelled";

export interface UserProject {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  name: string;
  description: string;
  estimatedPrice: number | null;
  estimatedDuration: number | null; // in days
  status: ProjectStatus;
  projectUrl?: string | null;
  createdAt: number;
  updatedAt: number;
  version?: string; 
  iconBg?: string; 

  // Wizard Fields
  platforms?: string[];
  languages?: string[];
  markets?: string[];
  industry?: string;
  industryOther?: string | null;
  hasPayments?: boolean;
  hasExistingBusiness?: boolean;
  serviceModel?: string;
  closestApp?: string;
  brandColor?: string;
}

class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private currentUid: string | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.projects = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;

    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // "Apps" collection stores user projects under the tenant
    const q = query(
      collection(db, 'tenants', TENANT_ID, 'apps'), 
      orderBy('createdAt', 'desc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      const allApps = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now(),
          updatedAt: data.updatedAt?.toMillis?.() || Date.now(),
          status: data.status || 'pricing'
        } as UserProject;
      });

      // Filter: Show apps owned by current user OR all apps if user is an admin (optional logic)
      // For now, in client view, we just filter by ownerId if we pulled everything, 
      // but security rules should prevent reading others unless admin.
      // Ideally, the query should filter `where('ownerId', '==', uid)` but rules handle that for now.

      this.projects = allApps.filter(p => p.ownerId === uid);
      this.notify();
    }, (error) => {
      console.error("Firestore userProjects error:", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects];
  }

  async addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    if (!db || !this.currentUid) return;
    try {
      await addDoc(collection(db, 'tenants', TENANT_ID, 'apps'), {
        ...project,
        ownerId: this.currentUid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        version: 'v1.0.0',
        iconBg: project.brandColor ? undefined : 'bg-primary'
      });
    } catch (e) {
      console.error("Error adding project:", e);
      throw e;
    }
  }

  async updateProject(id: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    if (!db || !this.currentUid) return;
    try {
      const docRef = doc(db, 'tenants', TENANT_ID, 'apps', id);
      await updateDoc(docRef, {
        ...updates,
        updatedAt: serverTimestamp()
      });
    } catch (e) {
      console.error("Error updating project:", e);
    }
  }

  async deleteProject(id: string) {
    if (!db || !this.currentUid) return;
    try {
      await deleteDoc(doc(db, 'tenants', TENANT_ID, 'apps', id));
    } catch (e) {
      console.error("Error deleting project:", e);
    }
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from './firebase';
import { TENANT_ID } from './constants';

export type UserRole = 'Customer' | 'Guest' | 'Admin';
export type UserStatus = 'Active' | 'Disabled';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  role: UserRole;
  status: UserStatus;
  registeredAt: number;
  lastLoginAt: number;
  projectsCount: number;
}

class UserStore {
  private users: User[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  constructor() {
    this.subscribeToFirestore();
  }

  private subscribeToFirestore() {
    if (!db) return;

    try {
      const q = query(collection(db, 'tenants', TENANT_ID, 'users'), orderBy('createdAt', 'desc'));

      this.unsubscribe = onSnapshot(q, (snapshot) => {
        this.users = snapshot.docs.map(doc => {
          const data = doc.data();
          return {
            ...data,
            id: doc.id,
            registeredAt: data.createdAt?.toMillis?.() || Date.now(),
            lastLoginAt: data.lastLoginAt?.toMillis?.() || Date.now(),
            role: data.role || 'Customer',
            status: data.status || 'Active',
            projectsCount: data.projectsCount || 0
          } as User;
        });
        this.notify();
      }, (error) => {
        // In a real app, strict security rules might block this if not an admin.
        console.error("Firestore Users Listen Error (Admin Only):", error);
      });
    } catch (e) {
      console.error("UserStore init error:", e);
    }
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getUsers() {
    return [...this.users];
  }

  async toggleStatus(id: string) {
    if (!db) return;
    const user = this.users.find(u => u.id === id);
    if (user) {
      const newStatus = user.status === 'Active' ? 'Disabled' : 'Active';
      try {
        await updateDoc(doc(db, 'tenants', TENANT_ID, 'users', id), { status: newStatus });
      } catch (e) {
        console.error("Error toggling status:", e);
      }
    }
  }

  async deleteUser(id: string) {
    if (!db) return;
    try {
      await deleteDoc(doc(db, 'tenants', TENANT_ID, 'users', id));
    } catch (e) {
      console.error("Error deleting user:", e);
    }
  }
}

