import { useEffect, useState } from 'react';
import { collection, addDoc, query, orderBy, onSnapshot, serverTimestamp, where } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { getGeminiReply, ChatMessage } from './gemini';
import { TENANT_ID } from './constants';

export interface Message {
  id: string;
  roomId: string;
  senderId: string;
  senderName: string;
  senderRole: 'customer' | 'staff';
  text: string;
  createdAt: number;
}

const ROOM_ID = 'support-room';
const DEFAULT_SYSTEM_PROMPT = `You are Raiyansoft Support, the official support assistant for Raiyansoft®. Your job is to help customers.`;

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private isThinking: boolean = false;
  private currentUid: string | null = null;
  private unsubscribe: (() => void) | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.messages = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    const q = query(
      collection(db, 'tenants', TENANT_ID, 'chats'),
      where('ownerId', '==', uid), // Filter by user ownership
      orderBy('createdAt', 'asc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.messages = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now()
        } as Message;
      });
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  getThinkingState() {
    return this.isThinking;
  }

  setThinking(state: boolean) {
    this.isThinking = state;
    this.notify();
  }

  async sendMessage(text: string) {
    if (!this.currentUid || !db) return;

    try {
       await addDoc(collection(db, 'tenants', TENANT_ID, 'chats'), {
        roomId: ROOM_ID,
        ownerId: this.currentUid, // Associate with user
        senderId: this.currentUid,
        senderName: auth.currentUser?.displayName || 'User',
        senderRole: 'customer',
        text,
        createdAt: serverTimestamp()
      });
    } catch (e) {
      console.error("Error sending message", e);
      return;
    }

    this.setThinking(true);

    try {
      const recentMessages = this.messages.slice(-10).map(m => ({
        role: m.senderRole === 'customer' ? 'user' : 'assistant',
        content: m.text
      } as ChatMessage));

      if (recentMessages.length === 0 || recentMessages[recentMessages.length-1].content !== text) {
          recentMessages.push({ role: 'user', content: text });
      }

      const replyText = await getGeminiReply(recentMessages, DEFAULT_SYSTEM_PROMPT);

      if (replyText) {
        await this.addStaffMessage(replyText);
      } else {
        await this.addStaffMessage("I'm having trouble connecting to the support server. Please try again later.");
      }
    } catch (error) {
      console.error("AI Generation Error", error);
      await this.addStaffMessage("Sorry, something went wrong.");
    } finally {
      this.setThinking(false);
    }
  }

  async addStaffMessage(text: string, senderName = 'Raiyansoft Support') {
    if (!this.currentUid || !db) return;
    await addDoc(collection(db, 'tenants', TENANT_ID, 'chats'), {
      roomId: ROOM_ID,
      ownerId: this.currentUid,
      senderId: 'staff_ai',
      senderName,
      senderRole: 'staff',
      text,
      createdAt: serverTimestamp()
    });
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());
  const [isThinking, setIsThinking] = useState(chatStore.getThinkingState());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
      setIsThinking(chatStore.getThinkingState());
    };

    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages, isThinking };
};

import { useState, useEffect } from 'react';
import { 
  collection, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  serverTimestamp, 
  query, 
  orderBy 
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export type ProjectStatus = "pricing" | "design" | "development" | "publishing" | "support" | "cancelled";

export interface UserProject {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  name: string;
  description: string;
  estimatedPrice: number | null;
  estimatedDuration: number | null; // in days
  status: ProjectStatus;
  projectUrl?: string | null;
  createdAt: number;
  updatedAt: number;
  version?: string; 
  iconBg?: string; 

  // Wizard Fields
  platforms?: string[];
  languages?: string[];
  markets?: string[];
  industry?: string;
  industryOther?: string | null;
  hasPayments?: boolean;
  hasExistingBusiness?: boolean;
  serviceModel?: string;
  closestApp?: string;
  brandColor?: string;
}

class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private currentUid: string | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.projects = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;

    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Path: users/{uid}/projects
    const q = query(
      collection(db, 'users', uid, 'projects'), 
      orderBy('createdAt', 'desc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.projects = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now(),
          updatedAt: data.updatedAt?.toMillis?.() || Date.now(),
          status: data.status || 'pricing'
        } as UserProject;
      });
      this.notify();
    }, (error) => {
      console.error("Firestore userProjects error:", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects];
  }

  async addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    const user = auth.currentUser;
    if (!db || !user) throw new Error("You must be signed in to create a project.");

    try {
      // Path: users/{uid}/projects
      await addDoc(collection(db, 'users', user.uid, 'projects'), {
        ...project,
        ownerId: user.uid,
        ownerName: user.displayName || 'User',
        ownerEmail: user.email || '',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        version: 'v1.0.0',
        iconBg: project.brandColor ? undefined : 'bg-primary'
      });
    } catch (e) {
      console.error("Error adding project:", e);
      throw e;
    }
  }

  async updateProject(projectId: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    const user = auth.currentUser;
    if (!db || !user) return;

    try {
      const docRef = doc(db, 'users', user.uid, 'projects', projectId);
      await updateDoc(docRef, {
        ...updates,
        updatedAt: serverTimestamp()
      });
    } catch (e) {
      console.error("Error updating project:", e);
      throw e;
    }
  }

  async deleteProject(projectId: string) {
    const user = auth.currentUser;
    if (!db || !user) return;

    try {
      await deleteDoc(doc(db, 'users', user.uid, 'projects', projectId));
    } catch (e) {
      console.error("Error deleting project:", e);
      throw e;
    }
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight, Check, X, Smartphone, Globe, CreditCard, Store, ShoppingBag, Zap, Palette, User, Mail, Phone, Lock, Briefcase, Loader2 } from 'lucide-react';
import { userProjectsStore } from '../lib/userProjectsStore';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { auth } from '../lib/firebase';

interface ProjectWizardProps {
  onClose: () => void;
  onComplete: () => void;
}

// Wizard Steps Data
const PLATFORMS = ['Website', 'iOS', 'Android'];
const LANGUAGES = ['Arabic', 'English'];
const MARKETS = ['Kuwait', 'GCC', 'Arab World', 'Global'];
const SERVICE_MODELS = ['Direct to customer', 'Marketplace'];
const CLOSEST_APPS = ['Talabat', '4Sale', 'Sheeel', 'Careem', 'None'];

const INDUSTRIES = [
  'Food & Delivery',
  'Fashion & Clothing',
  'Pharmacy & Healthcare',
  'Pets & Animals',
  'Services',
  'Education',
  'Real Estate',
  'Travel & Tourism',
  'Finance',
  'Logistics & Shipping',
  'Other'
];

const PRESET_COLORS = [
  { hex: '#1DB7F0', name: 'Raiyansoft' },
  { hex: '#10B981', name: 'Teal' },
  { hex: '#FACC15', name: 'Gold' },
  { hex: '#8B5CF6', name: 'Purple' },
  { hex: '#EF4444', name: 'Red' },
  { hex: '#FFFFFF', name: 'White' }
];

const ProjectWizard: React.FC<ProjectWizardProps> = ({ onClose, onComplete }) => {
  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const isAuthenticated = !!auth.currentUser;

  // Form State
  const [formData, setFormData] = useState({
    platforms: [] as string[],
    languages: [] as string[],
    markets: [] as string[],
    industry: '',
    industryOther: '',
    hasPayments: null as boolean | null,
    hasExistingBusiness: null as boolean | null,
    serviceModel: '',
    closestApp: '',
    name: '',
    brandColor: '#1DB7F0',
    description: '', // Generated later

    // Guest Signup Data
    guestFirstName: '',
    guestLastName: '',
    guestPhone: '',
    guestEmail: '',
    guestPassword: '',
    guestConfirmPassword: ''
  });

  const [showCustomColor, setShowCustomColor] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Navigation Logic
  // 0: Intro, 1: Platforms, 2: Languages, 3: Markets, 4: Industry
  // 5: Payments, 6: Existing Biz, 7: Service Model, 8: Closest App
  // 9: Name, 10: Color, 11: Guest, 12: Review

  const nextStep = () => {
    if (validateStep(step)) {
      setDirection(1);
      // Skip Guest Step (11) if already authenticated
      if (step === 10 && isAuthenticated) {
        generateAndSetDescription();
        setStep(12);
      } else {
        if (step === 11) {
            // Finishing guest signup, generate description for review
            generateAndSetDescription();
        }
        setStep(step + 1);
      }
    }
  };

  const prevStep = () => {
    setDirection(-1);
    if (step === 12 && isAuthenticated) {
      setStep(10);
    } else {
      setStep(step - 1);
    }
  };

  const validateStep = (currentStep: number): boolean => {
    setErrors([]);
    const newErrors: string[] = [];

    switch (currentStep) {
      case 1: if (formData.platforms.length === 0) newErrors.push("Select at least one platform"); break;
      case 2: if (formData.languages.length === 0) newErrors.push("Select at least one language"); break;
      case 3: if (formData.markets.length === 0) newErrors.push("Select at least one market"); break;
      case 4: 
        if (!formData.industry) newErrors.push("Select an industry"); 
        if (formData.industry === 'Other' && !formData.industryOther?.trim()) newErrors.push("Please specify the industry");
        break;
      case 5: if (formData.hasPayments === null) newErrors.push("Please select an option"); break;
      case 6: if (formData.hasExistingBusiness === null) newErrors.push("Please select an option"); break;
      case 7: if (!formData.serviceModel) newErrors.push("Please select a service model"); break;
      case 8: if (!formData.closestApp) newErrors.push("Please select a reference"); break;
      case 9: if (!formData.name.trim()) newErrors.push("Please enter an app name"); break;
      case 10: if (!formData.brandColor) newErrors.push("Please select a color"); break;
      case 11: // Guest Signup Validation
        if (!isAuthenticated) {
          if (!formData.guestFirstName) newErrors.push("First Name is required");
          if (!formData.guestLastName) newErrors.push("Last Name is required");
          if (!formData.guestEmail.includes('@')) newErrors.push("Valid email is required");
          if (!formData.guestPhone) newErrors.push("Phone is required");
          if (formData.guestPassword.length < 6) newErrors.push("Password too short");
          if (formData.guestPassword !== formData.guestConfirmPassword) newErrors.push("Passwords do not match");
        }
        break;
      case 12: 
        if (!formData.name.trim()) newErrors.push("Project name is required");
        if (!formData.description.trim()) newErrors.push("Description is required");
        break;
    }

    if (newErrors.length > 0) {
      setErrors(newErrors);
      return false;
    }

    return true;
  };

  const generateAndSetDescription = () => {
    const parts = [];
    const industryText = formData.industry === 'Other' ? (formData.industryOther || 'custom') : formData.industry;

    parts.push(`A ${formData.serviceModel.toLowerCase()} ${industryText} platform`);

    if (formData.closestApp !== 'None') parts.push(`similar to ${formData.closestApp}`);
    parts.push(`targeting ${formData.markets.join(', ')}.`);

    parts.push(`Available on ${formData.platforms.join(' & ')}`);
    parts.push(`in ${formData.languages.join(' & ')}.`);

    if (formData.hasPayments) parts.push("Includes in-app payments.");
    if (formData.hasExistingBusiness) parts.push("Supports an existing business.");
    else parts.push("New business venture.");

    setFormData(prev => ({ ...prev, description: parts.join(' ') }));
  };

  const handleCreate = async () => {
    if (!validateStep(12)) return;
    setIsLoading(true);
    setErrors([]);

    try {
      // 1. Handle Auth if Guest
      let user = auth.currentUser;

      if (!user) {
        // Create new account
        const userCredential = await createUserWithEmailAndPassword(auth, formData.guestEmail, formData.guestPassword);
        user = userCredential.user;

        // Update profile
        await updateProfile(user, {
          displayName: `${formData.guestFirstName} ${formData.guestLastName}`
        });
      }

      // 2. Create Project
      // Note: addProject now uses auth.currentUser internally, but strictly relies on it being set.
      // Since we just created/confirmed user, it should be available.

      await userProjectsStore.addProject({
        name: formData.name,
        description: formData.description,
        ownerName: user.displayName || 'User',
        ownerEmail: user.email || '',
        ownerId: user.uid,
        estimatedPrice: null,
        estimatedDuration: null,
        status: 'pricing',
        projectUrl: null,
        platforms: formData.platforms,
        languages: formData.languages,
        markets: formData.markets,
        industry: formData.industry,
        industryOther: formData.industryOther,
        hasPayments: formData.hasPayments || false,
        hasExistingBusiness: formData.hasExistingBusiness || false,
        serviceModel: formData.serviceModel,
        closestApp: formData.closestApp,
        brandColor: formData.brandColor
      });

      onComplete();
    } catch (e: any) {
      console.error(e);
      let msg = "Failed to create project.";
      if (e.code === 'auth/email-already-in-use') msg = "Email already in use. Please sign in.";
      else if (e.message) msg = e.message;
      setErrors([msg]);
    } finally {
      setIsLoading(false);
    }
  };

  // Helper Inputs
  const toggleArray = (arr: string[], val: string, key: 'platforms' | 'languages' | 'markets') => {
    const newArr = arr.includes(val) ? arr.filter(i => i !== val) : [...arr, val];
    setFormData({ ...formData, [key]: newArr });
  };

  // --- RENDERERS ---

  const renderIntro = () => (
    <div className="flex flex-col h-full justify-center items-center text-center p-6 space-y-6">
       <div className="w-20 h-20 bg-primary/20 rounded-full flex items-center justify-center mb-4 border border-primary/20 animate-pulse">
         <Zap size={40} className="text-primary" />
       </div>
       <h2 className="text-2xl font-bold text-white">Let's Build Your Vision</h2>
       <div className="bg-slate-800/50 border border-white/5 p-5 rounded-2xl max-w-xs mx-auto">
         <p className="text-slate-300 text-sm leading-relaxed">
           <span className="text-amber-400 font-bold block mb-2">Important Note</span>
           The questions in this wizard are for Version 1 only. This first release is designed to be scalable, so you can expand features comfortably in the future.
         </p>
       </div>
       <button onClick={nextStep} className="w-full max-w-xs bg-primary text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all">
         Start
       </button>
    </div>
  );

  const renderMultiSelect = (title: string, options: string[], selected: string[], key: 'platforms' | 'languages' | 'markets') => (
    <div className="flex flex-col h-full p-6 pt-10">
      <h2 className="text-2xl font-bold text-white mb-6">{title}</h2>
      <div className="flex flex-wrap gap-3">
        {options.map(opt => (
          <button
            key={opt}
            onClick={() => toggleArray(selected, opt, key)}
            className={`px-5 py-3 rounded-xl border font-medium transition-all duration-200 ${
              selected.includes(opt) 
                ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20 scale-105' 
                : 'bg-slate-800 border-white/10 text-slate-400 hover:bg-slate-700'
            }`}
          >
            {opt}
          </button>
        ))}
      </div>
    </div>
  );

  const renderIndustryStep = () => (
    <div className="flex flex-col h-full p-6 pt-10 overflow-y-auto no-scrollbar pb-24">
      <h2 className="text-2xl font-bold text-white mb-6">Which industry does your app target?</h2>
      <div className="grid grid-cols-2 gap-3">
        {INDUSTRIES.map(ind => {
           const isSelected = formData.industry === ind;
           return (
             <button
                key={ind}
                onClick={() => setFormData({ ...formData, industry: ind })}
                className={`p-4 rounded-xl border font-medium transition-all duration-200 text-left flex flex-col justify-between h-24 ${
                  isSelected 
                    ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' 
                    : 'bg-slate-800 border-white/10 text-slate-400 hover:bg-slate-700'
                }`}
             >
                <span className="text-sm font-semibold leading-tight">{ind}</span>
                {isSelected && <div className="self-end bg-white/20 rounded-full p-1"><Check size={12} /></div>}
             </button>
           );
        })}
      </div>

      {formData.industry === 'Other' && (
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="mt-6"
        >
          <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">Please specify</label>
          <input
            autoFocus
            type="text"
            value={formData.industryOther || ''}
            onChange={e => setFormData({ ...formData, industryOther: e.target.value })}
            className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none"
            placeholder="e.g. Automotive, Agriculture..."
          />
        </motion.div>
      )}
    </div>
  );

  const renderSingleChoice = (title: string, options: any[], selected: any, key: string, isBool = false) => (
    <div className="flex flex-col h-full p-6 pt-10">
      <h2 className="text-2xl font-bold text-white mb-6">{title}</h2>
      <div className="space-y-3">
        {options.map((opt) => {
