import { doc, getDoc, writeBatch, collection, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';
import { User } from 'firebase/auth';

export async function migrateLocalStorageToFirestore(user: User) {
  if (!user || !db) return;

  const uid = user.uid;
  // Migration flag is stored on the user's profile
  const userRef = doc(db, 'users', uid);

  try {
    const userSnap = await getDoc(userRef);

    // Check if migration already happened
    if (userSnap.exists() && userSnap.data().migrationDone) {
      return;
    }

    console.log("Starting migration to User Firestore...");
    const batch = writeBatch(db);
    let operationCount = 0;

    // 1. Migrate User Apps (Previously 'user_projects' in localStorage)
    const localUserProjects = localStorage.getItem('user_projects');

    if (localUserProjects) {
      try {
        const parsed = JSON.parse(localUserProjects);
        if (Array.isArray(parsed)) {
          parsed.forEach((app: any) => {
            const newDocRef = doc(collection(db, 'users', uid, 'projects'));
            batch.set(newDocRef, {
              ...app,
              ownerId: uid,
              ownerName: user.displayName || 'User',
              ownerEmail: user.email || '',
              createdAt: app.createdAt ? new Date(app.createdAt) : serverTimestamp(),
              migratedAt: serverTimestamp()
            });
            operationCount++;
          });
        }
      } catch(e) { console.warn("Error parsing local user projects", e); }
    }

    // 2. Mark Migration Complete
    // Ensure user doc exists
    batch.set(userRef, {
      migrationDone: true,
      migratedAt: serverTimestamp(),
      email: user.email,
      displayName: user.displayName
    }, { merge: true });

    operationCount++;

    await batch.commit();

    if (operationCount > 1) {
      console.log(`Migration successful. Moved ${operationCount - 1} projects.`);
      localStorage.removeItem('user_projects');
    }

  } catch (error) {
    console.error("Migration failed:", error);
  }
}

