/**
 * Recursively removes keys with `undefined` values from an object.
 * Firestore throws an error if `undefined` is passed as a field value.
 * null is allowed and preserved.
 */
export function sanitizeForFirestore<T>(obj: T): T {
  if (obj === undefined) return undefined as any;
  if (obj === null) return null as any;

  if (Array.isArray(obj)) {
    return obj
      .map(sanitizeForFirestore)
      .filter(v => v !== undefined) as any;
  }

  if (typeof obj === "object") {
    const out: any = {};
    for (const [k, v] of Object.entries(obj as any)) {
      const sv = sanitizeForFirestore(v);
      if (sv !== undefined) {
        out[k] = sv;
      }
    }
    return out;
  }

  return obj;
}

import { useState, useEffect } from 'react';
import { 
  collection, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  serverTimestamp, 
  query, 
  orderBy 
} from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { sanitizeForFirestore } from './firestoreSanitize';

export type ProjectStatus = "pricing" | "design" | "development" | "publishing" | "support" | "cancelled";

export interface UserProject {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  name: string;
  description: string;
  estimatedPrice: number | null;
  estimatedDuration: number | null; // in days
  status: ProjectStatus;
  projectUrl?: string | null;
  createdAt: number;
  updatedAt: number;
  version?: string; 
  iconBg?: string; 
  brandColor?: string;

  // Wizard Fields
  platforms?: string[];
  languages?: string[];
  markets?: string[];
  industry?: string;
  industryOther?: string | null;
  hasPayments?: boolean;
  hasExistingBusiness?: boolean;
  serviceModel?: string;
  closestApp?: string;
}

class UserProjectsStore {
  private projects: UserProject[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private currentUid: string | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.projects = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;

    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Path: users/{uid}/projects
    const q = query(
      collection(db, 'users', uid, 'projects'), 
      orderBy('createdAt', 'desc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.projects = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now(),
          updatedAt: data.updatedAt?.toMillis?.() || Date.now(),
          status: data.status || 'pricing'
        } as UserProject;
      });
      this.notify();
    }, (error) => {
      console.error("Firestore userProjects error:", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getAllProjects() {
    return [...this.projects];
  }

  async addProject(project: Omit<UserProject, 'id' | 'createdAt' | 'updatedAt'>) {
    const user = auth.currentUser;
    if (!db || !user) throw new Error("You must be signed in to create a project.");

    try {
      // Prepare raw data
      const projectData = {
        ...project,
        ownerId: user.uid,
        ownerName: user.displayName || 'User',
        ownerEmail: user.email || '',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        version: 'v1.0.0',
        // Fallback for iconBg if missing, though sanitization handles undefined removal
        iconBg: project.iconBg || project.brandColor || '#1DB7F0',
        brandColor: project.brandColor || '#1DB7F0'
      };

      // Sanitize to remove any undefined fields before Firestore write
      const cleanData = sanitizeForFirestore(projectData);

      // Path: users/{uid}/projects
      await addDoc(collection(db, 'users', user.uid, 'projects'), cleanData);
    } catch (e) {
      console.error("Error adding project:", e);
      throw e;
    }
  }

  async updateProject(projectId: string, updates: Partial<Omit<UserProject, 'id' | 'createdAt'>>) {
    const user = auth.currentUser;
    if (!db || !user) return;

    try {
      const docRef = doc(db, 'users', user.uid, 'projects', projectId);

      const updateData = {
        ...updates,
        updatedAt: serverTimestamp()
      };

      const cleanUpdates = sanitizeForFirestore(updateData);

      await updateDoc(docRef, cleanUpdates);
    } catch (e) {
      console.error("Error updating project:", e);
      throw e;
    }
  }

  async deleteProject(projectId: string) {
    const user = auth.currentUser;
    if (!db || !user) return;

    try {
      await deleteDoc(doc(db, 'users', user.uid, 'projects', projectId));
    } catch (e) {
      console.error("Error deleting project:", e);
      throw e;
    }
  }
}

export const userProjectsStore = new UserProjectsStore();

export const useUserProjects = () => {
  const [projects, setProjects] = useState<UserProject[]>(userProjectsStore.getAllProjects());

  useEffect(() => {
    const update = () => setProjects(userProjectsStore.getAllProjects());
    update();
    return userProjectsStore.subscribe(update);
  }, []);

  return { projects, store: userProjectsStore };
};

import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, doc, updateDoc, deleteDoc, getDocs } from 'firebase/firestore';
import { db } from './firebase';

export type UserRole = 'Customer' | 'Guest' | 'Admin';
export type UserStatus = 'Active' | 'Disabled';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  role: UserRole;
  status: UserStatus;
  registeredAt: number;
  lastLoginAt: number;
  projectsCount: number;
}

class UserStore {
  private users: User[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;
  private error: string | null = null;

  constructor() {
    this.subscribeToFirestore();
  }

  private subscribeToFirestore() {
    if (!db) return;

    // Use root 'users' collection as requested.
    // Starting with NO filters to ensure data loads (filters often require indices).
    const usersCollection = collection(db, 'users');

    // We can sort client-side if needed, or re-introduce orderBy if composite index exists.
    // For now, let's try a simple query.

    this.unsubscribe = onSnapshot(usersCollection, (snapshot) => {
      this.error = null; // Clear previous errors
      this.users = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          // Handle potential missing fields gracefully
          firstName: data.firstName || 'Unknown',
          lastName: data.lastName || '',
          email: data.email || 'No Email',
          phone: data.phone || '',
          registeredAt: data.createdAt?.toMillis?.() || data.registeredAt || Date.now(),
          lastLoginAt: data.lastLoginAt?.toMillis?.() || Date.now(),
          role: data.role || 'Customer',
          status: data.status || 'Active',
          projectsCount: data.projectsCount || 0
        } as User;
      })
      // Client-side sort by registeredAt desc since we removed orderBy from query
      .sort((a, b) => b.registeredAt - a.registeredAt);

      this.notify();
    }, (err) => {
      console.error("Failed to load users:", err.code, err.message, err);

      if (err.code === 'permission-denied') {
        this.error = "Firestore permission denied. Dashboard needs Admin access (Admin SDK or rules).";
      } else {
        this.error = `Error loading users: ${err.message}`;
      }
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getUsers() {
    return [...this.users];
  }

  getError() {
    return this.error;
  }

  async toggleStatus(id: string) {
    if (!db) return;
    const user = this.users.find(u => u.id === id);
    if (user) {
      const newStatus = user.status === 'Active' ? 'Disabled' : 'Active';
      try {
        await updateDoc(doc(db, 'users', id), { status: newStatus });
      } catch (e) {
        console.error("Error toggling status:", e);
      }
    }
  }

  async deleteUser(id: string) {
    if (!db) return;
    try {
      await deleteDoc(doc(db, 'users', id));
    } catch (e) {
      console.error("Error deleting user:", e);
    }
  }
}

export const userStore = new UserStore();

export const useUsers = () => {
  const [users, setUsers] = useState<User[]>(userStore.getUsers());
  const [error, setError] = useState<string | null>(userStore.getError());

  useEffect(() => {
    const update = () => {
      setUsers(userStore.getUsers());
      setError(userStore.getError());
    };
    update();
    return userStore.subscribe(update);
  }, []);

  return { users, error };
};

