                        </div>
                      </td>
                      <td className="p-5 text-slate-300">
                         <div className="flex flex-col gap-1">
                           <span className="flex items-center gap-1.5"><Mail size={12} className="text-slate-500"/> {emp.email}</span>
                           {emp.phone && <span className="flex items-center gap-1.5"><Phone size={12} className="text-slate-500"/> {emp.phone}</span>}
                         </div>
                      </td>
                      <td className="p-5">
