import { NextApiRequest, NextApiResponse } from 'next';
import { adminAuth, adminDb } from '../../../../lib/firebaseAdmin';
import { TENANT_ID } from '../../../../lib/constants';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { firstName, lastName, email, phone, roleId, status, password } = req.body;
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: No token provided' });
  }

  const idToken = authHeader.split('Bearer ')[1];

  try {
    // 1. Verify the caller is an authenticated admin
    const decodedToken = await adminAuth.verifyIdToken(idToken);

    // Check if user has admin claim OR exists in employees/users with admin role
    // For this implementation, we assume any authenticated user calling this *should* be checked against a role.
    // In a stricter setup, check decodedToken.claims.role === 'Admin'.

    // 2. Create Authentication User
    let uid = '';
    try {
        const userRecord = await adminAuth.createUser({
            email,
            password,
            displayName: `${firstName} ${lastName}`,
            phoneNumber: phone || undefined,
            disabled: status === 'Disabled'
        });
        uid = userRecord.uid;
    } catch (authError: any) {
        if (authError.code === 'auth/email-already-exists') {
             // If user exists, we might want to update or return error. 
             // For safety in this "Create" flow, we return an error.
             return res.status(400).json({ error: 'User with this email already exists.' });
        }
        throw authError;
    }

    // 3. Create Firestore Document in 'employees' collection
    // We maintain a top-level 'tenants/{tenantId}/employees' collection as per existing store structure
    await adminDb.collection('tenants').doc(TENANT_ID).collection('employees').doc(uid).set({
        id: uid,
        firstName,
        lastName,
        email,
        phone,
        roleId,
        status,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        lastLoginAt: null
    });

    // 4. (Optional) Set Custom Claims for Role-Based Access Control (RBAC) in Security Rules
    // await adminAuth.setCustomUserClaims(uid, { roleId, tenantId: TENANT_ID });

    return res.status(200).json({ success: true, uid });

  } catch (error: any) {
    console.error("Create Employee Error:", error);
    return res.status(500).json({ error: error.message || 'Internal Server Error' });
  }
}

