import { NextApiRequest, NextApiResponse } from 'next';
import * as admin from 'firebase-admin';
import { adminAuth, adminDb } from '../../../../lib/firebaseAdmin';
import { TENANT_ID } from '../../../../lib/constants';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { firstName, lastName, email, phone, roleId, status, password } = req.body;
  const authHeader = req.headers.authorization;
  let isBootstrap = false;

  try {
    // 1. Authentication Check
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const idToken = authHeader.split('Bearer ')[1];
      try {
        await adminAuth.verifyIdToken(idToken);
        // Token valid, proceed as normal admin
      } catch (e) {
        return res.status(401).json({ error: 'Invalid authentication token' });
      }
    } else {
      // No token provided. Check if system is empty (Bootstrap Mode)
      const employeesRef = adminDb.collection('tenants').doc(TENANT_ID).collection('employees');
      const snapshot = await employeesRef.limit(1).get();

      if (snapshot.empty) {
        console.log("System empty. Allowing Bootstrap creation.");
        isBootstrap = true;
      } else {
        return res.status(401).json({ error: 'Unauthorized: System already initialized' });
      }
    }

    // 2. Role Management for Bootstrap
    let finalRoleId = roleId;

    if (isBootstrap) {
      // Ensure 'Super Admin' role exists
      const rolesRef = adminDb.collection('tenants').doc(TENANT_ID).collection('roles');
      const roleQuery = await rolesRef.where('name', '==', 'Super Admin').limit(1).get();

      if (roleQuery.empty) {
        const newRole = await rolesRef.add({
          name: 'Super Admin',
          description: 'System Administrator with full access (Auto-generated)',
          permissions: ['*'], // Wildcard for full access
          createdAt: admin.firestore.FieldValue.serverTimestamp()
        });
        finalRoleId = newRole.id;
        console.log("Created Super Admin role:", finalRoleId);
      } else {
        finalRoleId = roleQuery.docs[0].id;
      }
    }

    // 3. Create/Update Authentication User
    let uid = '';
    try {
        // Check if user exists first to decide update vs create
        try {
          const existingUser = await adminAuth.getUserByEmail(email);
          uid = existingUser.uid;
          // Update password if provided
          if (password) {
            await adminAuth.updateUser(uid, {
               password: password,
               displayName: `${firstName} ${lastName}`,
               disabled: status === 'Disabled'
            });
          }
        } catch (e: any) {
          if (e.code === 'auth/user-not-found') {
             const userRecord = await adminAuth.createUser({
                email,
                password,
                displayName: `${firstName} ${lastName}`,
                phoneNumber: phone || undefined,
                disabled: status === 'Disabled'
            });
            uid = userRecord.uid;
          } else {
            throw e;
          }
        }
    } catch (authError: any) {
        console.error("Auth Error:", authError);
        return res.status(400).json({ error: `Auth Error: ${authError.message}` });
    }

    // 4. Create/Update Firestore Document
    await adminDb.collection('tenants').doc(TENANT_ID).collection('employees').doc(uid).set({
        id: uid,
        firstName,
        lastName,
        email,
        phone: phone || '',
        roleId: finalRoleId,
        status: status || 'Active',
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        lastLoginAt: null
    }, { merge: true }); // Merge to avoid overwriting existing fields if updating

    // Set Custom Claims (Optional but recommended for client-side routing)
    if (isBootstrap || finalRoleId) {
       await adminAuth.setCustomUserClaims(uid, { role: 'super_admin', tenantId: TENANT_ID });
    }

    return res.status(200).json({ success: true, uid, message: isBootstrap ? 'Bootstrap successful' : 'Employee created' });

  } catch (error: any) {
    console.error("Create Employee Error:", error);
    return res.status(500).json({ error: error.message || 'Internal Server Error' });
  }
}

