import { NextApiRequest, NextApiResponse } from 'next';
import * as admin from 'firebase-admin';
import { adminAuth, adminDb } from '../../../../lib/firebaseAdmin';
import { TENANT_ID } from '../../../../lib/constants';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ ok: false, code: "methodNotAllowed" });
  }

  const { firstName, lastName, email, password, phone, role, status, permissions } = req.body;
  const authHeader = req.headers.authorization;

  // Reference to the employees collection
  const employeesRef = adminDb.collection('tenants').doc(TENANT_ID).collection('employees');

  try {
    // 1. Check if system is empty (Bootstrap Check)
    const snapshot = await employeesRef.limit(1).get();
    const isSystemEmpty = snapshot.empty;

    let creatorUid = 'system_bootstrap';
    let mode = 'normal';

    // 2. Authentication Logic
    if (isSystemEmpty) {
      console.log("System is empty. Starting Bootstrap Mode.");
      mode = 'bootstrap';
      // In bootstrap mode, we skip token verification
    } else {
      // Normal Mode: Require Authentication
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Missing Authorization header" });
      }

      const idToken = authHeader.split('Bearer ')[1];
      try {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        creatorUid = decodedToken.uid;

        // Optional: Check if requester is super_admin (implementation depends on your claims strategy)
        // const requester = await adminAuth.getUser(creatorUid);
        // if (requester.customClaims?.role !== 'super_admin') return res.status(403).json({ ok: false, code: "forbidden" });

      } catch (e) {
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Invalid token" });
      }
    }

    // 3. User Creation / Retrieval (Idempotent)
    let targetUid = '';

    try {
      // Try to get existing user by email
      const existingUser = await adminAuth.getUserByEmail(email);
      targetUid = existingUser.uid;

      // Update existing user credentials if provided
      const updateData: any = {};
      if (password) updateData.password = password;
      if (firstName || lastName) updateData.displayName = `${firstName} ${lastName}`;
      if (Object.keys(updateData).length > 0) {
        await adminAuth.updateUser(targetUid, updateData);
      }

    } catch (e: any) {
      if (e.code === 'auth/user-not-found') {
        // Create new user
        const newUser = await adminAuth.createUser({
          email,
          password,
          displayName: `${firstName} ${lastName}`,
          phoneNumber: phone || undefined,
          disabled: status === 'Disabled'
        });
        targetUid = newUser.uid;
      } else {
        throw e;
      }
    }

    // 4. Set Custom Claims (Critical for Security Rules)
    // For bootstrap, we enforce super_admin. For normal, we use provided role.
    const finalRole = isSystemEmpty ? 'super_admin' : (role || 'employee');
    const finalPermissions = isSystemEmpty ? ['*'] : (permissions || []);

    await adminAuth.setCustomUserClaims(targetUid, { 
      role: finalRole, 
      permissions: finalPermissions,
      tenantId: TENANT_ID
    });

    // 5. Create/Update Firestore Record
    await employeesRef.doc(targetUid).set({
      id: targetUid,
      firstName,
      lastName,
      email,
      phone: phone || '',
      role: finalRole,
      status: status || 'Active',
      permissions: finalPermissions,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      createdBy: creatorUid,
      updatedAt: admin.firestore.FieldValue.serverTimestamp()
    }, { merge: true });

    return res.status(200).json({ 
      ok: true, 
      mode, 
      uid: targetUid, 
      message: isSystemEmpty ? "Bootstrap successful" : "Employee created" 
    });

  } catch (error: any) {
    console.error("Create Employee Error:", error);
    return res.status(500).json({ ok: false, code: "error", message: error.message });
  }
}

