import { auth } from '../../lib/firebase';

const AdminLogin: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isBootstrapping, setIsBootstrapping] = useState(false);
  const [bootstrapMessage, setBootstrapMessage] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      // Get the ID token for API usage
      const token = await userCredential.user.getIdToken();

      // Store session info
      localStorage.setItem('adminAuth', 'true');
      localStorage.setItem('adminToken', token); // Persist token if needed for direct calls
      localStorage.setItem('adminEmail', email);

      navigate('/admin/projects');
    } catch (err: any) {
      console.error("Admin Login Error:", err);
      if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password') {
        setError('Invalid email or password.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Too many failed attempts. Try again later.');
      } else {
        setError('Login failed. Please check your credentials.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleBootstrap = async () => {
    if (!window.confirm("Initialize System? This will create the Super Admin account (Nader) if no employees exist.")) return;

    setIsBootstrapping(true);
    setError('');
    setBootstrapMessage(null);

    try {
      // Credentials defined in requirements
      const payload = {
        firstName: 'nader',
        lastName: 'admin',
        email: 'nader.alizddin@gmail.com',
        password: 'Nader@321',
        role: 'super_admin',
        status: 'Active',
        permissions: ['*'],
        bootstrap: true
      };

      const response = await fetch('/api/admin/employees/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      const data = await response.json();

      if (data.ok) {
        setBootstrapMessage("System Initialized! The Super Admin account has been created.");
        setEmail('nader.alizddin@gmail.com');
        setPassword('Nader@321');
      } else if (data.code === 'employeesAlreadyInitialized') {
         setError("System is already initialized. Cannot run bootstrap.");
      } else if (data.code === 'notAuthenticated') {
         setError("Authentication required for this operation.");
      } else {
        throw new Error(data.message || 'Failed to initialize system');
      }
    } catch (err: any) {
      setError(err.message || 'Network error occurred');
    } finally {
      setIsBootstrapping(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#020617] relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
