import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Mail, Lock, Check, AlertCircle } from 'lucide-react';
import SafeImage from '../components/SafeImage';
import { signInWithEmailAndPassword, signInAnonymously } from 'firebase/auth';
import { auth } from '../lib/firebase';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState<{ code?: string; message: string } | null>(null);
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agreed) {
      setError({ message: 'Please agree to the Terms & Conditions.' });
      return;
    }
    setError(null);
    setLoading(true);

    try {
      await signInWithEmailAndPassword(auth, email, password);
      navigate('/home');
    } catch (err: any) {
      console.error("Login Error", err);
      let message = "Login failed. Please try again.";
      if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password') {
        message = 'Invalid email or password.';
      } else if (err.code === 'auth/too-many-requests') {
        message = 'Too many failed attempts. Please reset your password or try again later.';
      }
      setError({ code: err.code, message });
    } finally {
      setLoading(false);
    }
  };

  const handleGuest = async () => {
    setError(null);
    setLoading(true);
    try {
      await signInAnonymously(auth);
      navigate('/home');
    } catch (err: any) {
      console.error(err);
      setError({ code: err.code, message: 'Guest login failed.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="flex flex-col h-full p-6 pt-12 relative"
    >
      <div className="flex justify-center mb-8">
        <SafeImage
          src="https://raiyansoft.com/wp-content/uploads/2024/05/cropped-App-Icon-1.png"
          alt="Logo"
          className="w-16 h-16 object-contain"
        />
      </div>

      <div className="mb-8">
        <h1 className="text-3xl font-bold text-white mb-2">Welcome Back</h1>
        <p className="text-slate-400 text-sm">Sign in to access your projects</p>
      </div>

      <form onSubmit={handleLogin} className="space-y-5">
        <div className="space-y-1">
          <label className="text-xs text-slate-300 font-medium ml-1">Email</label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-800/50 border border-slate-700/50 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary transition-all duration-300"
              placeholder="Enter your email"
              required
            />
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs text-slate-300 font-medium ml-1">Password</label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-800/50 border border-slate-700/50 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary transition-all duration-300"
              placeholder="Enter your password"
              required
            />
          </div>
        </div>

        {error && (
          <motion.div 
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-start gap-2"
          >
            <AlertCircle size={16} className="text-red-400 shrink-0 mt-0.5" />
            <div className="flex flex-col">
               <span className="text-red-400 text-xs font-bold">{error.message}</span>
               {error.code && <span className="text-red-500/70 text-[10px] font-mono">{error.code}</span>}
            </div>
          </motion.div>
        )}

        <motion.button
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          type="submit"
          disabled={loading}
          className="w-full bg-primary text-white font-semibold py-3.5 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all duration-300 mt-2 disabled:opacity-70 disabled:cursor-not-allowed"
        >
          {loading ? 'Signing in...' : 'Sign in'}
        </motion.button>
      </form>

      <div className="mt-6 flex flex-col items-center space-y-6">
        <button
          onClick={() => navigate('/signup')}
          className="text-sm text-slate-400 hover:text-white transition-colors"
        >
          Don't have an account? <span className="text-primary">Sign up</span>
        </button>

        <label className="flex items-center space-x-3 cursor-pointer group">
          <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${agreed ? 'bg-primary border-primary' : 'border-slate-600 bg-slate-800/50 group-hover:border-slate-500'}`}>
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => {
                setAgreed(e.target.checked);
                setError(null);
              }}
              className="hidden"
            />
            {agreed && <Check size={14} className="text-white" />}
          </div>
          <span className="text-xs text-slate-400 group-hover:text-slate-300 transition-colors">
            I agree to the Terms & Conditions
          </span>
        </label>

        <button
          onClick={handleGuest}
          className="text-xs text-slate-500 hover:text-white transition-colors uppercase tracking-wider font-medium"
        >
          Continue as Guest
        </button>
      </div>
    </motion.div>
  );
};

export default Login;

