      </header>

      <div className="p-6 space-y-8">
        {/* Debug Info (Requested) */}
        {currentUser && (
           <div className="bg-slate-900/50 p-2 rounded border border-white/5 text-[10px] text-slate-500 font-mono break-all">
             UID: {currentUser.uid} <br/>
             Cloud Sync: Active
           </div>
        )}

        {/* My Apps Section */}
        <section>
          <h2 className="text-lg font-bold text-white mb-4 flex items-center">
            <span className="w-1 h-5 bg-primary rounded-full mr-2"></span>
            My Apps
          </h2>
          <div className="flex flex-col">
            {userCreatedProjects.length > 0 ? (
              userCreatedProjects.map(app => (
                <AppCard 
                  key={app.id}
                  id={app.id}
                  name={app.name} 
                  version={app.version || 'v1.0.0'} 
                  description={app.description}
                  iconBg={app.iconBg}
                  brandColor={app.brandColor}
                  onOpen={() => navigate(`/projects/${app.id}`)}
                />
              ))
            ) : (
              // Empty State
              <div className="text-center py-8 bg-slate-800/20 rounded-2xl border border-white/5">
                <p className="text-sm text-slate-400">No projects found in cloud.</p>
                <p className="text-xs text-slate-500 mt-1">Create your first project to enable details view.</p>
              </div>
            )}
          </div>
        </section>

        {/* CTA Button */}
        <motion.button
          onClick={() => setIsWizardOpen(true)}
          whileHover={{ scale: 1.02, shadow: "0 0 25px rgba(29,183,240,0.4)" }}
          whileTap={{ scale: 0.98 }}
          className="w-full bg-gradient-to-r from-primary to-blue-500 rounded-2xl p-4 flex items-center justify-between shadow-[0_0_15px_rgba(29,183,240,0.2)] group"
        >
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
              <Plus size={24} className="text-white" />
            </div>
            <span className="text-white font-semibold">
              {userCreatedProjects.length > 0 ? "Create another awesome project 🚀" : "Add your first project 🚀"}
            </span>
          </div>
          <ChevronRight className="text-white/70 group-hover:translate-x-1 transition-transform" />
        </motion.button>
      </div>

      {/* Project Wizard Modal */}
      <AnimatePresence>
        {isWizardOpen && (
          <ProjectWizard 
            onClose={() => setIsWizardOpen(false)}
            onComplete={() => setIsWizardOpen(false)}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

