  const { messages, isThinking } = useMessages();
  const [inputText, setInputText] = useState('');

  // We use this ref to identify the scroll container's child, but we don't attach the scroll listener to it.
  const scrollRef = useRef<HTMLDivElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    // CRITICAL FIX FOR IOS:
    // Do not use `bottomRef.current.scrollIntoView()` directly.
    // On iOS Safari, `scrollIntoView` can cause the entire viewport (html/body) to shift,
    // creating a black bar at the bottom and breaking layout.
    // Instead, we find the scrollable container (in MobileShell) and set its scrollTop manually.

    // The scrollable container in MobileShell has the class 'overflow-y-auto'
    const scrollContainer = bottomRef.current?.closest('.overflow-y-auto');

    if (scrollContainer) {
      scrollContainer.scrollTo({
        top: scrollContainer.scrollHeight,
        behavior
      });
    } else {
      // Fallback if container not found (unlikely in this structure)
      bottomRef.current?.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    scrollToBottom('auto'); // Instant scroll on mount
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages.length, isThinking]);

  const handleSend = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim()) return;

    chatStore.sendMessage(inputText.trim());
    setInputText('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
