                   results.push({ ...p, id: pseudoId } as UserProject);
                   seenIds.add(pseudoId);
                 }
               });
             }
           }
        } catch (e) {
          console.warn("Legacy doc fetch failed", e);
        }
      }

      // Sort combined results by date
      results.sort((a, b) => {
        const dateA = a.createdAt || 0;
        const dateB = b.createdAt || 0;
        return dateB - dateA;
      });

