import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, addDoc, updateDoc, deleteDoc, doc, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';
import { TENANT_ID } from './constants';

export interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  roleId: string;
  status: 'Active' | 'Disabled';
  createdAt: number;
  lastLoginAt: number;
}

class EmployeeStore {
  private employees: Employee[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  constructor() {
    this.subscribeToFirestore();
  }

  private subscribeToFirestore() {
    if (!db) return;

    const q = query(collection(db, 'tenants', TENANT_ID, 'employees'), orderBy('createdAt', 'desc'));

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.employees = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now(),
          lastLoginAt: data.lastLoginAt?.toMillis?.() || 0
        } as Employee;
      });
      this.notify();
    }, (error) => {
      console.error("Employee fetch error (Admin Only):", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getEmployees() {
    return [...this.employees];
  }

  async addEmployee(employee: Omit<Employee, 'id' | 'createdAt' | 'lastLoginAt'>) {
    if (!db) return;
    await addDoc(collection(db, 'tenants', TENANT_ID, 'employees'), {
      ...employee,
      createdAt: serverTimestamp(),
      lastLoginAt: null
    });
  }

  async updateEmployee(id: string, updates: Partial<Omit<Employee, 'id' | 'createdAt'>>) {
    if (!db) return;
    await updateDoc(doc(db, 'tenants', TENANT_ID, 'employees', id), updates);
  }

  async toggleStatus(id: string) {
    if (!db) return;
    const emp = this.employees.find(e => e.id === id);
    if (emp) {
      const newStatus = emp.status === 'Active' ? 'Disabled' : 'Active';
      await updateDoc(doc(db, 'tenants', TENANT_ID, 'employees', id), { status: newStatus });
    }
  }

  async deleteEmployee(id: string) {
    if (!db) return;
    await deleteDoc(doc(db, 'tenants', TENANT_ID, 'employees', id));
  }
}

export const employeeStore = new EmployeeStore();

export const useEmployees = () => {
  const [employees, setEmployees] = useState<Employee[]>(employeeStore.getEmployees());

  useEffect(() => {
    const update = () => setEmployees(employeeStore.getEmployees());
    update();
    return employeeStore.subscribe(update);
  }, []);

  return { employees };
};

