const AdminEmployees: React.FC = () => {
  const { employees } = useEmployees();
  const { roles } = useRoles();

  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [createdPassword, setCreatedPassword] = useState<string | null>(null); // To show after creation

  // Form State
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    roleId: '',
    status: 'Active' as 'Active' | 'Disabled',
    password: ''
  });

  // Helpers
  const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Unknown Role';
  const formatDate = (ts: number) => new Date(ts).toLocaleDateString('en-UK', { day: 'numeric', month: 'short', year: 'numeric' });

  // Filtering
  const filteredEmployees = employees.filter(emp => 
    emp.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleOpenModal = (emp?: Employee) => {
    setCreatedPassword(null); // Reset success message
    if (emp) {
      setEditingEmployee(emp);
      setFormData({
        firstName: emp.firstName,
        lastName: emp.lastName,
        email: emp.email,
        phone: emp.phone,
        roleId: emp.roleId,
        status: emp.status,
        password: '' // Don't fill password on edit
      });
    } else {
      setEditingEmployee(null);
      setFormData({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        roleId: roles[0]?.id || '',
        status: 'Active',
        password: ''
      });
    }
    setIsModalOpen(true);
  };

  const generatePassword = () => {
    const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%";
    let pass = "";
    for (let i = 0; i < 12; i++) {
      pass += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setFormData({ ...formData, password: pass });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      if (editingEmployee) {
        // Direct Firestore update for existing employees (Password update not handled here for security, usually separate flow)
        const { password, ...updateData } = formData; // Exclude password from direct firestore update
        await employeeStore.updateEmployee(editingEmployee.id, updateData);
        setIsModalOpen(false);
      } else {
        // Create new employee via API
        if (formData.password.length < 8) {
          alert("Password must be at least 8 characters");
          setIsSubmitting(false);
          return;
        }

        console.log("Initiating employee creation...");

        // Get ID Token
        const currentUser = auth.currentUser;
        let token = '';
        if (currentUser) {
           console.log("Fetching ID Token...");
           token = await currentUser.getIdToken(true);
        } else {
           console.log("No current user found. Attempting bootstrap request (if allowed)...");
        }

        // --- FETCH REQUEST ---
        // 1) Use Absolute Path /api/...
        // 2) Explicitly send Content-Type
        const response = await fetch('/api/admin/employees/create', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': token ? `Bearer ${token}` : ''
          },
          body: JSON.stringify(formData)
        });

        // --- RESPONSE HANDLING ---
        const contentType = response.headers.get("content-type");

        // Check if content type is JSON before parsing
        if (contentType && contentType.includes("application/json")) {
          const result = await response.json();

          if (!response.ok) {
            console.error("API Error Result:", result);
            throw new Error(result.message || result.error || 'Failed to create employee');
          }

          console.log("Employee created successfully:", result);
          // Show success state
          setCreatedPassword(formData.password);
        } else {
          // If NOT JSON, log the raw text (HTML) to console and throw error
          const text = await response.text();
          console.error("Non-JSON response from API (First 300 chars):", text.slice(0, 300));
          throw new Error("Server returned HTML instead of JSON. Check the network tab or middleware configuration.");
        }
      }
    } catch (error: any) {
      console.error("Employee operation failed:", error);
      alert(`Error: ${error.message}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleToggleStatus = (emp: Employee) => {
    employeeStore.toggleStatus(emp.id);
    if (selectedEmployee?.id === emp.id) {
       setSelectedEmployee(prev => prev ? ({...prev, status: prev.status === 'Active' ? 'Disabled' : 'Active'}) : null);
    }
  };

  const handleDelete = () => {
    if (deleteId) {
      employeeStore.deleteEmployee(deleteId);
      if (selectedEmployee?.id === deleteId) setSelectedEmployee(null);
      setDeleteId(null);
    }
  };

  return (
    <div className="space-y-8 pb-20">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Employees</h1>
