          </>
        )}
      </AnimatePresence>

      <ConfirmModal isOpen={!!deleteId} title="Delete Employee?" message="This action is permanent." confirmText="Delete" isDestructive={true} onConfirm={handleDelete} onCancel={() => setDeleteId(null)} />
    </div>
  );
};

export default AdminEmployees;

import { NextApiRequest, NextApiResponse } from 'next';
import * as admin from 'firebase-admin';
import { adminAuth, adminDb } from '../../../../lib/firebaseAdmin';
import { TENANT_ID } from '../../../../lib/constants';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  // Always enforce JSON content type for this API endpoint
  res.setHeader('Content-Type', 'application/json');

  try {
    if (req.method !== 'POST') {
      return res.status(405).json({ ok: false, code: "methodNotAllowed", message: "Method not allowed" });
    }

    const { 
      firstName, 
      lastName, 
      email, 
      password, 
      phone, 
      role, 
      status, 
      permissions,
      bootstrap // Optional flag from UI to indicate intent
    } = req.body;

    const authHeader = req.headers.authorization;

    // Reference to the employees collection within the tenant
    const employeesRef = adminDb.collection('tenants').doc(TENANT_ID).collection('employees');

    // 1. Check if system is empty (Bootstrap Check)
    const snapshot = await employeesRef.limit(1).get();
    const isSystemEmpty = snapshot.empty;

    let creatorUid = 'system_bootstrap';
    let mode = 'normal';

    // 2. Access Control Logic
    if (isSystemEmpty) {
      // System is empty. We allow creation without a token (Bootstrap Mode).
      console.log("System is empty. Allowing Bootstrap creation.");
      mode = 'bootstrap';
    } else {
      // System is NOT empty.

      // If the client specifically requested a bootstrap but the system isn't empty, fail immediately.
      if (bootstrap) {
        return res.status(400).json({ ok: false, code: "employeesAlreadyInitialized", message: "System already initialized" });
      }

      // Normal Mode: Require valid Authentication
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Authentication required" });
      }

      const idToken = authHeader.split('Bearer ')[1];
      try {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        creatorUid = decodedToken.uid;

        // Optional: Check if the requester is a super_admin here if needed
      } catch (e) {
        console.error("Token verification failed:", e);
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Invalid authentication token" });
      }
    }

    // 3. Prepare User Data
    // For bootstrap, force super_admin/*
    const finalRole = isSystemEmpty ? 'super_admin' : (role || 'employee');
    const finalPermissions = isSystemEmpty ? ['*'] : (permissions || []);

    // 4. Create or Update Auth User (Idempotent)
    let targetUid = '';

    try {
      // Check if user already exists by email
      const existingUser = await adminAuth.getUserByEmail(email);
      targetUid = existingUser.uid;

      // Update existing user if password or name provided
      const updatePayload: any = {};
      if (password) updatePayload.password = password;
      if (firstName || lastName) updatePayload.displayName = `${firstName} ${lastName}`;
      if (Object.keys(updatePayload).length > 0) {
        await adminAuth.updateUser(targetUid, updatePayload);
      }

    } catch (e: any) {
      if (e.code === 'auth/user-not-found') {
        // Create new user
        const newUser = await adminAuth.createUser({
          email,
          password,
          displayName: `${firstName} ${lastName}`,
          phoneNumber: phone || undefined,
          disabled: status === 'Disabled'
        });
        targetUid = newUser.uid;
      } else {
        throw e; // Rethrow other errors to outer catch
      }
    }

    // 5. Set Custom Claims (Critical for RLS/Security Rules)
    await adminAuth.setCustomUserClaims(targetUid, { 
      role: finalRole, 
      permissions: finalPermissions,
      tenantId: TENANT_ID
    });

    // 6. Create/Update Firestore Document
    // Using set with merge: true to be idempotent
    await employeesRef.doc(targetUid).set({
      id: targetUid,
      firstName,
      lastName,
      email,
      phone: phone || '',
      role: finalRole,
      status: status || 'Active',
      permissions: finalPermissions,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      createdBy: creatorUid,
      updatedAt: admin.firestore.FieldValue.serverTimestamp()
    }, { merge: true });

    // 7. Success Response
    return res.status(200).json({ 
      ok: true, 
      mode, 
      uid: targetUid 
    });

  } catch (error: any) {
    console.error("Create Employee API Error:", error);
    // Ensure we return JSON even on 500
    return res.status(500).json({ ok: false, code: "serverError", message: error.message || "Internal Server Error" });
  }
}

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  // Check if the request is for an API route
  if (request.nextUrl.pathname.startsWith('/api')) {
    // Return next() to skip any potential redirects or auth guards that might be applied globally
    return NextResponse.next();
  }

  return NextResponse.next();
}

