           token = await currentUser.getIdToken(true);
        } else {
           console.log("No current user found. Attempting bootstrap request (if allowed)...");
        }

        // --- FETCH REQUEST ---
        // 1) Use Absolute Path /api/...
        // 2) Explicitly send Content-Type
        // 3) Disable cache to prevent SW returning stale HTML
        const response = await fetch('/api/admin/employees/create', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': token ? `Bearer ${token}` : ''
