import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Plus, MoreHorizontal, Eye, Ban, CheckCircle, Trash2, X, Mail, Phone, Calendar, Briefcase, Save, Edit2, Lock, RefreshCw, Loader2, Copy, Check } from 'lucide-react';
import { useEmployees, employeeStore, Employee } from '../../lib/employeeStore';
import { useRoles } from '../../lib/roleStore';
import AvatarInitial from '../../components/AvatarInitial';
import ConfirmModal from '../../components/ConfirmModal';

// Firebase Client SDKs
import { initializeApp, deleteApp } from 'firebase/app';
import { getAuth, createUserWithEmailAndPassword, updateProfile, signOut } from 'firebase/auth';
import { doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { firebaseConfig, db, auth } from '../../lib/firebase'; // Import main db and config
import { TENANT_ID } from '../../lib/constants';

const AdminEmployees: React.FC = () => {
  const { employees } = useEmployees();
  const { roles } = useRoles();

  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [createdPassword, setCreatedPassword] = useState<string | null>(null); // To show after creation

  // Form State
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    roleId: '',
    status: 'Active' as 'Active' | 'Disabled',
    password: ''
  });

  // Helpers
  const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Unknown Role';
  const formatDate = (ts: number) => new Date(ts).toLocaleDateString('en-UK', { day: 'numeric', month: 'short', year: 'numeric' });

  // Filtering
  const filteredEmployees = employees.filter(emp => 
    emp.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleOpenModal = (emp?: Employee) => {
    setCreatedPassword(null); // Reset success message
    if (emp) {
      setEditingEmployee(emp);
      setFormData({
        firstName: emp.firstName,
        lastName: emp.lastName,
        email: emp.email,
        phone: emp.phone,
        roleId: emp.roleId,
        status: emp.status,
        password: '' // Don't fill password on edit
      });
    } else {
      setEditingEmployee(null);
      setFormData({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        roleId: roles[0]?.id || '',
        status: 'Active',
        password: ''
      });
    }
    setIsModalOpen(true);
  };

  const generatePassword = () => {
    const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%";
    let pass = "";
    for (let i = 0; i < 12; i++) {
      pass += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setFormData({ ...formData, password: pass });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      if (editingEmployee) {
        // Direct Firestore update for existing employees
        const { password, ...updateData } = formData; 
        await employeeStore.updateEmployee(editingEmployee.id, updateData);
        setIsModalOpen(false);
      } else {
        // Create new employee via Client-Side Logic using a Secondary App
        // This prevents the current admin from being logged out

        if (formData.password.length < 8) {
          alert("Password must be at least 8 characters");
          setIsSubmitting(false);
          return;
        }

        console.log("Initializing secondary app for user creation...");

        // 1. Initialize Secondary App
        const secondaryAppName = `secondaryApp-${Date.now()}`;
        const secondaryApp = initializeApp(firebaseConfig, secondaryAppName);
        const secondaryAuth = getAuth(secondaryApp);

        try {
          // 2. Create User in Auth (on secondary app)
          const userCredential = await createUserWithEmailAndPassword(secondaryAuth, formData.email, formData.password);
          const newUser = userCredential.user;

          // 3. Update Profile
          await updateProfile(newUser, {
            displayName: `${formData.firstName} ${formData.lastName}`
          });

          // 4. Create Firestore Document (using MAIN app DB to ensure admin permissions)
          // Path: tenants/{tenantId}/employees/{uid}
          const employeeRef = doc(db, 'tenants', TENANT_ID, 'employees', newUser.uid);

          await setDoc(employeeRef, {
            id: newUser.uid,
            firstName: formData.firstName,
            lastName: formData.lastName,
            email: formData.email,
            phone: formData.phone || '',
            roleId: formData.roleId,
            status: formData.status,
            createdAt: serverTimestamp(),
            lastLoginAt: null,
            createdBy: auth.currentUser?.uid || 'system'
          });

          // 5. Cleanup
          await signOut(secondaryAuth);
          await deleteApp(secondaryApp);

          console.log("Employee created successfully:", newUser.uid);
          setCreatedPassword(formData.password);

        } catch (innerError: any) {
          // Ensure we cleanup the secondary app even if creation fails
          await deleteApp(secondaryApp);
          throw innerError;
        }
      }
    } catch (error: any) {
      console.error("Employee operation failed:", error);
      let msg = error.message;

      // Map common Firebase Auth errors to user-friendly messages
      if (error.code === 'auth/email-already-in-use') {
        msg = "The email address is already in use by another account.";
      } else if (error.code === 'permission-denied') {
        msg = "You do not have permission to create employees.";
      } else if (error.code === 'auth/weak-password') {
        msg = "The password is too weak.";
      } else if (error.code === 'auth/invalid-email') {
        msg = "The email address is invalid.";
      }

      alert(`Error: ${msg}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleToggleStatus = (emp: Employee) => {
    employeeStore.toggleStatus(emp.id);
    if (selectedEmployee?.id === emp.id) {
       setSelectedEmployee(prev => prev ? ({...prev, status: prev.status === 'Active' ? 'Disabled' : 'Active'}) : null);
    }
  };

  const handleDelete = () => {
    if (deleteId) {
      employeeStore.deleteEmployee(deleteId);
      if (selectedEmployee?.id === deleteId) setSelectedEmployee(null);
      setDeleteId(null);
    }
  };

  return (
    <div className="space-y-8 pb-20">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Employees</h1>
          <p className="text-slate-400 text-sm">Manage staff accounts and access.</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="bg-primary hover:bg-sky-400 text-white px-4 py-2.5 rounded-xl font-medium flex items-center justify-center gap-2 transition-colors shadow-lg shadow-primary/20"
        >
          <Plus size={20} />
          <span>Add Employee</span>
        </button>
      </div>

      {/* Search Bar */}
      <div className="bg-[#0f172a] p-4 rounded-2xl border border-white/5 shadow-lg">
        <div className="relative w-full md:max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search by name or email..."
            className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl py-2.5 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:border-primary transition-colors"
          />
        </div>
      </div>

      {/* Employees Table/List */}
      <div className="bg-[#0f172a] border border-white/5 rounded-2xl shadow-xl overflow-hidden">
        {filteredEmployees.length === 0 ? (
          <div className="py-20 text-center text-slate-500">
             <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 border border-white/5">
               <Briefcase size={24} />
             </div>
             <p>No employees found.</p>
          </div>
        ) : (
          <>
            {/* Desktop Table */}
            <div className="hidden md:block overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b border-white/5 text-xs text-slate-500 uppercase tracking-wider">
                    <th className="p-5 font-medium">Employee</th>
                    <th className="p-5 font-medium">Contact</th>
                    <th className="p-5 font-medium">Role</th>
                    <th className="p-5 font-medium">Status</th>
                    <th className="p-5 font-medium">Joined</th>
                    <th className="p-5 font-medium text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5 text-sm">
                  {filteredEmployees.map((emp) => (
                    <tr key={emp.id} className="hover:bg-white/[0.02] transition-colors group">
                      <td className="p-5">
                        <div className="flex items-center gap-3">
                          <AvatarInitial name={`${emp.firstName} ${emp.lastName}`} className="w-10 h-10 border border-white/10 text-sm" />
                          <div>
                            <div className="font-medium text-white">{emp.firstName} {emp.lastName}</div>
                            <div className="text-slate-500 text-xs">ID: {emp.id.slice(-6)}</div>
                          </div>
                        </div>
                      </td>
                      <td className="p-5 text-slate-300">
                         <div className="flex flex-col gap-1">
                           <span className="flex items-center gap-1.5"><Mail size={12} className="text-slate-500"/> {emp.email}</span>
                           {emp.phone && <span className="flex items-center gap-1.5"><Phone size={12} className="text-slate-500"/> {emp.phone}</span>}
                         </div>
                      </td>
                      <td className="p-5">
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-800 text-slate-300 border border-white/5">
                          {getRoleName(emp.roleId)}
                        </span>
                      </td>
                      <td className="p-5">
                        <div className="flex items-center gap-2">
                          <div className={`w-1.5 h-1.5 rounded-full ${emp.status === 'Active' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 'bg-red-500'}`} />
                          <span className={emp.status === 'Active' ? 'text-slate-200' : 'text-slate-500'}>{emp.status}</span>
                        </div>
                      </td>
                      <td className="p-5 text-slate-400">
                        {formatDate(emp.createdAt)}
                      </td>
                      <td className="p-5 text-right">
                        <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => setSelectedEmployee(emp)} className="p-2 hover:bg-white/5 rounded-lg text-slate-400 hover:text-white" title="View">
                             <Eye size={16} />
                          </button>
                          <button onClick={() => handleOpenModal(emp)} className="p-2 hover:bg-white/5 rounded-lg text-slate-400 hover:text-white" title="Edit">
                             <Edit2 size={16} />
                          </button>
                          <button onClick={() => setDeleteId(emp.id)} className="p-2 hover:bg-red-500/10 rounded-lg text-slate-400 hover:text-red-400" title="Delete">
                             <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Mobile Cards */}
            <div className="md:hidden divide-y divide-white/5">
              {filteredEmployees.map((emp) => (
                <div key={emp.id} className="p-4 flex items-center justify-between" onClick={() => setSelectedEmployee(emp)}>
                   <div className="flex items-center gap-3">
                     <AvatarInitial name={`${emp.firstName} ${emp.lastName}`} className="w-10 h-10 border border-white/10 text-sm" />
                     <div>
                       <h3 className="text-sm font-medium text-white">{emp.firstName} {emp.lastName}</h3>
                       <p className="text-xs text-slate-500">{getRoleName(emp.roleId)}</p>
                     </div>
                   </div>
                   <MoreHorizontal size={20} className="text-slate-600" />
                </div>
              ))}
            </div>
          </>
        )}
      </div>

      {/* Add/Edit Modal */}
      <AnimatePresence>
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
            <motion.div
               initial={{ scale: 0.95, opacity: 0 }}
               animate={{ scale: 1, opacity: 1 }}
               exit={{ scale: 0.95, opacity: 0 }}
               className="bg-[#0f172a] w-full max-w-lg rounded-2xl border border-white/10 shadow-2xl flex flex-col max-h-[90vh]"
            >
               <div className="p-5 border-b border-white/10 flex justify-between items-center">
                 <h2 className="text-xl font-bold text-white">{editingEmployee ? 'Edit Employee' : 'Add Employee'}</h2>
                 <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white"><X size={20}/></button>
               </div>

               {createdPassword ? (
                 <div className="p-8 flex flex-col items-center text-center">
                    <div className="w-16 h-16 bg-emerald-500/10 rounded-full flex items-center justify-center text-emerald-500 mb-4 border border-emerald-500/20">
                       <CheckCircle size={32} />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Employee Created!</h3>
                    <p className="text-slate-400 text-sm mb-6">The account is ready. Please copy the password below.</p>

                    <div className="w-full bg-slate-900 border border-white/10 rounded-xl p-4 flex items-center justify-between mb-6">
                      <span className="font-mono text-white text-lg">{createdPassword}</span>
                      <button 
                        onClick={() => { navigator.clipboard.writeText(createdPassword); alert('Copied!'); }}
                        className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"
                      >
                        <Copy size={20} />
                      </button>
                    </div>

                    <button 
                      onClick={() => setIsModalOpen(false)}
                      className="px-6 py-2.5 bg-primary text-white rounded-xl font-medium"
                    >
                      Done
                    </button>
                 </div>
               ) : (
                 <>
                   <div className="p-6 overflow-y-auto custom-scrollbar">
                     <form id="empForm" onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-300 ml-1">First Name <span className="text-red-400">*</span></label>
                            <input type="text" required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" />
                          </div>
                          <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-300 ml-1">Last Name <span className="text-red-400">*</span></label>
                            <input type="text" required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" />
                          </div>
                        </div>

                        <div className="space-y-1">
                          <label className="text-xs font-medium text-slate-300 ml-1">Email <span className="text-red-400">*</span></label>
                          <input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" />
                        </div>

                        <div className="space-y-1">
                          <label className="text-xs font-medium text-slate-300 ml-1">Phone</label>
                          <input type="text" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none" />
                        </div>

                        {/* Password Section - Only for new employees */}
                        {!editingEmployee && (
                          <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-300 ml-1">Password <span className="text-red-400">*</span></label>
                            <div className="flex gap-2">
                              <div className="relative flex-1">
                                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
                                <input 
                                  type="text" 
                                  required 
                                  minLength={8}
                                  value={formData.password} 
                                  onChange={e => setFormData({...formData, password: e.target.value})} 
                                  className="w-full bg-slate-900 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-white focus:border-primary focus:outline-none font-mono"
                                  placeholder="Min 8 characters" 
                                />
                              </div>
                              <button 
                                type="button"
                                onClick={generatePassword}
                                className="bg-slate-800 border border-white/10 hover:bg-slate-700 text-white px-3 rounded-xl flex items-center gap-2 transition-colors"
                                title="Generate Password"
                              >
                                <RefreshCw size={16} />
                                <span className="text-xs hidden sm:inline">Generate</span>
                              </button>
                            </div>
                          </div>
                        )}

                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-300 ml-1">Role <span className="text-red-400">*</span></label>
                            <select 
                              required 
                              value={formData.roleId} 
                              onChange={e => setFormData({...formData, roleId: e.target.value})} 
                              className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none appearance-none"
                            >
                              <option value="" disabled>Select Role</option>
                              {roles.map(role => <option key={role.id} value={role.id}>{role.name}</option>)}
                            </select>
                          </div>
                          <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-300 ml-1">Status</label>
                            <select 
                              value={formData.status} 
                              onChange={e => setFormData({...formData, status: e.target.value as any})} 
                              className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none appearance-none"
                            >
                              <option value="Active">Active</option>
                              <option value="Disabled">Disabled</option>
                            </select>
                          </div>
                        </div>
                     </form>
                   </div>

                   <div className="p-5 border-t border-white/10 flex justify-end gap-3">
                     <button type="button" onClick={() => setIsModalOpen(false)} className="px-5 py-2.5 rounded-xl text-slate-400 hover:text-white font-medium text-sm">Cancel</button>
                     <button 
                       form="empForm" 
                       type="submit" 
                       disabled={isSubmitting}
                       className="px-5 py-2.5 rounded-xl bg-primary hover:bg-sky-400 text-white font-medium text-sm shadow-lg shadow-primary/20 flex items-center gap-2 disabled:opacity-70"
                     >
                       {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                       <span>{editingEmployee ? 'Update' : 'Create'} Employee</span>
                     </button>
                   </div>
                 </>
               )}
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Details Drawer */}
      <AnimatePresence>
        {selectedEmployee && (
          <>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setSelectedEmployee(null)} className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm" />
            <motion.div 
               initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }} transition={{ type: "spring", damping: 30, stiffness: 300 }}
               className="fixed inset-y-0 right-0 z-50 w-full max-w-md bg-[#0f172a] border-l border-white/10 shadow-2xl flex flex-col"
            >
               <div className="flex items-center justify-between p-6 border-b border-white/5">
                 <h2 className="text-xl font-bold text-white">Employee Details</h2>
                 <button onClick={() => setSelectedEmployee(null)} className="p-2 text-slate-400 hover:text-white"><X size={20}/></button>
               </div>

               <div className="flex-1 overflow-y-auto p-6">
                  <div className="flex flex-col items-center mb-8">
                     <div className="w-24 h-24 mb-4">
                       <AvatarInitial name={`${selectedEmployee.firstName} ${selectedEmployee.lastName}`} className="w-full h-full text-3xl border-4 border-slate-800 shadow-xl" />
                     </div>
                     <h3 className="text-2xl font-bold text-white">{selectedEmployee.firstName} {selectedEmployee.lastName}</h3>
                     <p className="text-slate-400">{getRoleName(selectedEmployee.roleId)}</p>
                  </div>

                  <div className="space-y-4">
                     <div className="bg-slate-800/40 p-4 rounded-xl border border-white/5">
                        <div className="text-xs text-slate-500 mb-1 flex items-center gap-2"><Mail size={12}/> Email</div>
                        <div className="text-white">{selectedEmployee.email}</div>
                     </div>
                     <div className="bg-slate-800/40 p-4 rounded-xl border border-white/5">
                        <div className="text-xs text-slate-500 mb-1 flex items-center gap-2"><Phone size={12}/> Phone</div>
                        <div className="text-white">{selectedEmployee.phone || 'N/A'}</div>
                     </div>
                     <div className="grid grid-cols-2 gap-4">
                        <div className="bg-slate-800/40 p-4 rounded-xl border border-white/5">
                           <div className="text-xs text-slate-500 mb-1">Status</div>
                           <div className={selectedEmployee.status === 'Active' ? 'text-emerald-400' : 'text-red-400'}>{selectedEmployee.status}</div>
                        </div>
                        <div className="bg-slate-800/40 p-4 rounded-xl border border-white/5">
                           <div className="text-xs text-slate-500 mb-1">Joined</div>
                           <div className="text-white text-sm">{formatDate(selectedEmployee.createdAt)}</div>
                        </div>
                     </div>
                  </div>
               </div>

               <div className="p-6 border-t border-white/5 bg-[#0f172a] flex gap-3">
                 <button onClick={() => handleToggleStatus(selectedEmployee)} className={`flex-1 py-3 rounded-xl font-medium text-sm flex items-center justify-center gap-2 ${selectedEmployee.status === 'Active' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                    {selectedEmployee.status === 'Active' ? <Ban size={18} /> : <CheckCircle size={18} />}
                    {selectedEmployee.status === 'Active' ? 'Disable' : 'Enable'}
                 </button>
                 <button onClick={() => setDeleteId(selectedEmployee.id)} className="flex-1 py-3 rounded-xl bg-red-500/10 text-red-400 font-medium text-sm flex items-center justify-center gap-2">
                    <Trash2 size={18} /> Delete
                 </button>
               </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <ConfirmModal isOpen={!!deleteId} title="Delete Employee?" message="This action is permanent." confirmText="Delete" isDestructive={true} onConfirm={handleDelete} onCancel={() => setDeleteId(null)} />
    </div>
  );
};

export default AdminEmployees;

// @ts-nocheck
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Lock, Mail, ShieldCheck, ArrowRight, Loader2, Zap } from 'lucide-react';
import SafeImage from '../../components/SafeImage';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { collection, getDocs, query, limit, doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../../lib/firebase';
import { TENANT_ID } from '../../lib/constants';

const AdminLogin: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isBootstrapping, setIsBootstrapping] = useState(false);
  const [bootstrapMessage, setBootstrapMessage] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      // PREFIX STRATEGY: 
      // We prepend 'admin_' to the email for Auth to separate App Users from Dashboard Users.
      // This allows 'john@example.com' to exist as a customer AND an employee independently.
      const authEmail = `admin_${email}`;

      const userCredential = await signInWithEmailAndPassword(auth, authEmail, password);
      // Get the ID token for API usage if needed
      const token = await userCredential.user.getIdToken();

      // Store session info
      localStorage.setItem('adminAuth', 'true');
      localStorage.setItem('adminToken', token); 
      localStorage.setItem('adminEmail', email); // Store real email for display

      navigate('/admin/projects');
    } catch (err: any) {
      console.error("Admin Login Error:", err);
      if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password') {
        setError('Invalid email or password.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Too many failed attempts. Try again later.');
      } else if (err.code === 'auth/invalid-email') {
        setError('Invalid email format.');
      } else {
        setError('Login failed. Please check your credentials.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleBootstrap = async () => {
    if (!window.confirm("Initialize System? This will create the Super Admin account (Nader) if no employees exist.")) return;

    setIsBootstrapping(true);
    setError('');
    setBootstrapMessage(null);

    try {
      if (!db) throw new Error("Database not connected");

      // 1. Check if system is already initialized (Client-side check)
      const employeesRef = collection(db, 'tenants', TENANT_ID, 'employees');
      const snapshot = await getDocs(query(employeesRef, limit(1)));

      if (!snapshot.empty) {
        setError("System is already initialized. Cannot run bootstrap.");
        setIsBootstrapping(false);
        return;
      }

      // Credentials defined in requirements
      const realEmail = 'nader.alizddin@gmail.com';
      const authEmail = `admin_${realEmail}`; // Prefix for Auth
      const password = 'Nader@321';
      const firstName = 'Nader';
      const lastName = 'Admin';

      // 2. Create User in Firebase Auth (Client-Side)
      const userCredential = await createUserWithEmailAndPassword(auth, authEmail, password);
      const user = userCredential.user;

      // 3. Update Auth Profile
      await updateProfile(user, {
        displayName: `${firstName} ${lastName}`
      });

      // 4. Create Employee Record in Firestore (using real email)
      await setDoc(doc(db, 'tenants', TENANT_ID, 'employees', user.uid), {
        id: user.uid,
        firstName,
        lastName,
        email: realEmail, // Store REAL email here
        role: 'super_admin',
        status: 'Active',
        permissions: ['*'],
        createdAt: serverTimestamp(),
        createdBy: 'system_bootstrap',
        lastLoginAt: null
      });

      setBootstrapMessage("System Initialized! The Super Admin account has been created.");
      setEmail(realEmail);
      setPassword(password);

    } catch (err: any) {
      console.error("Bootstrap Error:", err);
      let msg = err.message || 'Failed to initialize system';
      if (err.code === 'auth/email-already-in-use') msg = 'Admin account already exists in Auth, but not in DB? Check console.';
      setError(msg);
    } finally {
      setIsBootstrapping(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#020617] relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-1/2 -left-1/2 w-[200%] h-[200%] bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-primary/5 via-transparent to-transparent opacity-50" />
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md p-6 relative z-10"
      >
        <div className="bg-[#0f172a]/80 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl">
          <div className="flex flex-col items-center mb-8">
            <div className="w-16 h-16 bg-slate-900 rounded-2xl flex items-center justify-center border border-white/5 mb-4 shadow-lg">
               <SafeImage 
                 src="https://raiyansoft.com/wp-content/uploads/2024/05/cropped-App-Icon-1.png"
                 className="w-10 h-10 object-contain"
               />
            </div>
            <h1 className="text-2xl font-bold text-white">Employee Access</h1>
            <p className="text-slate-400 text-sm mt-1">Sign in to manage projects</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1">
              <label className="text-xs text-slate-300 font-medium ml-1">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary transition-all"
                  placeholder="name@raiyansoft.com"
                  required
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-xs text-slate-300 font-medium ml-1">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl py-3 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary transition-all"
                  placeholder="••••••"
                  required
                />
              </div>
            </div>

            {error && (
              <motion.div 
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-center gap-2 text-red-400 text-xs"
              >
                <ShieldCheck size={14} />
                {error}
              </motion.div>
            )}

            {bootstrapMessage && (
              <motion.div 
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                className="bg-emerald-500/10 border border-emerald-500/20 rounded-lg p-3 text-emerald-400 text-xs text-center"
              >
                {bootstrapMessage}
              </motion.div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-primary text-white font-semibold py-3.5 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all duration-300 mt-2 flex items-center justify-center space-x-2 disabled:opacity-70 disabled:cursor-not-allowed group"
            >
              {isLoading ? (
                <Loader2 size={20} className="animate-spin" />
              ) : (
                <>
                  <span>Sign In</span>
                  <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center space-y-4">
            <p className="text-[10px] text-slate-600 uppercase tracking-widest">Secured Area • Raiyansoft® Admin</p>

            <button 
              onClick={handleBootstrap}
              disabled={isBootstrapping}
              className="text-[10px] text-slate-700 hover:text-slate-500 transition-colors flex items-center justify-center gap-1 mx-auto"
            >
              {isBootstrapping ? <Loader2 size={10} className="animate-spin" /> : <Zap size={10} />}
              Initialize System (First Run)
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

export default AdminLogin;

// @ts-nocheck
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Plus, MoreHorizontal, Eye, Ban, CheckCircle, Trash2, X, Mail, Phone, Calendar, Briefcase, Save, Edit2, Lock, RefreshCw, Loader2, Copy, Check } from 'lucide-react';
import { useEmployees, employeeStore, Employee } from '../../lib/employeeStore';
import { useRoles } from '../../lib/roleStore';
import AvatarInitial from '../../components/AvatarInitial';
import ConfirmModal from '../../components/ConfirmModal';

// Firebase Client SDKs
import { initializeApp, deleteApp } from 'firebase/app';
import { getAuth, createUserWithEmailAndPassword, updateProfile, signOut } from 'firebase/auth';
import { doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { firebaseConfig, db, auth } from '../../lib/firebase'; // Import main db and config
import { TENANT_ID } from '../../lib/constants';

const AdminEmployees: React.FC = () => {
  const { employees } = useEmployees();
  const { roles } = useRoles();

  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [createdPassword, setCreatedPassword] = useState<string | null>(null); // To show after creation

  // Form State
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    roleId: '',
    status: 'Active' as 'Active' | 'Disabled',
    password: ''
  });

  // Helpers
  const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Unknown Role';
  const formatDate = (ts: number) => new Date(ts).toLocaleDateString('en-UK', { day: 'numeric', month: 'short', year: 'numeric' });

  // Filtering
  const filteredEmployees = employees.filter(emp => 
    emp.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleOpenModal = (emp?: Employee) => {
    setCreatedPassword(null); // Reset success message
    if (emp) {
      setEditingEmployee(emp);
      setFormData({
        firstName: emp.firstName,
        lastName: emp.lastName,
        email: emp.email,
        phone: emp.phone,
        roleId: emp.roleId,
        status: emp.status,
        password: '' // Don't fill password on edit
      });
    } else {
      setEditingEmployee(null);
      setFormData({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        roleId: roles[0]?.id || '',
        status: 'Active',
        password: ''
      });
    }
    setIsModalOpen(true);
  };

  const generatePassword = () => {
    const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%";
    let pass = "";
    for (let i = 0; i < 12; i++) {
      pass += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setFormData({ ...formData, password: pass });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      if (editingEmployee) {
        // Direct Firestore update for existing employees
        const { password, ...updateData } = formData; 
        await employeeStore.updateEmployee(editingEmployee.id, updateData);
        setIsModalOpen(false);
      } else {
        // Create new employee via Client-Side Logic using a Secondary App
        // This prevents the current admin from being logged out

        if (formData.password.length < 8) {
          alert("Password must be at least 8 characters");
          setIsSubmitting(false);
          return;
        }

        console.log("Initializing secondary app for user creation...");

        // 1. Initialize Secondary App
        const secondaryAppName = `secondaryApp-${Date.now()}`;
        const secondaryApp = initializeApp(firebaseConfig, secondaryAppName);
        const secondaryAuth = getAuth(secondaryApp);

        try {
          // 2. Create User in Auth (on secondary app)
          // PREFIX STRATEGY: Prepend 'admin_' to ensure this user is distinct from app users
          const authEmail = `admin_${formData.email}`;

          const userCredential = await createUserWithEmailAndPassword(secondaryAuth, authEmail, formData.password);
          const newUser = userCredential.user;

          // 3. Update Profile
          await updateProfile(newUser, {
            displayName: `${formData.firstName} ${formData.lastName}`
          });

          // 4. Create Firestore Document (using MAIN app DB to ensure admin permissions)
          // Path: tenants/{tenantId}/employees/{uid}
          const employeeRef = doc(db, 'tenants', TENANT_ID, 'employees', newUser.uid);

          await setDoc(employeeRef, {
            id: newUser.uid,
            firstName: formData.firstName,
            lastName: formData.lastName,
            email: formData.email, // Store the REAL (unprefixed) email in Firestore
            phone: formData.phone || '',
            roleId: formData.roleId,
            status: formData.status,
            createdAt: serverTimestamp(),
            lastLoginAt: null,
            createdBy: auth.currentUser?.uid || 'system'
          });

          // 5. Cleanup
          await signOut(secondaryAuth);
          await deleteApp(secondaryApp);

          console.log("Employee created successfully:", newUser.uid);
          setCreatedPassword(formData.password);

        } catch (innerError: any) {
          // Ensure we cleanup the secondary app even if creation fails
          await deleteApp(secondaryApp);
          throw innerError;
        }
      }
    } catch (error: any) {
      console.error("Employee operation failed:", error);
      let msg = error.message;

      // Map common Firebase Auth errors to user-friendly messages
      if (error.code === 'auth/email-already-in-use') {
        msg = "An employee account with this email already exists.";
      } else if (error.code === 'permission-denied') {
        msg = "You do not have permission to create employees.";
      } else if (error.code === 'auth/weak-password') {
        msg = "The password is too weak.";
      } else if (error.code === 'auth/invalid-email') {
        msg = "The email address is invalid.";
      }

      alert(`Error: ${msg}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleToggleStatus = (emp: Employee) => {
    employeeStore.toggleStatus(emp.id);
    if (selectedEmployee?.id === emp.id) {
       setSelectedEmployee(prev => prev ? ({...prev, status: prev.status === 'Active' ? 'Disabled' : 'Active'}) : null);
    }
  };

  const handleDelete = () => {
    if (deleteId) {
      employeeStore.deleteEmployee(deleteId);
      if (selectedEmployee?.id === deleteId) setSelectedEmployee(null);
      setDeleteId(null);
    }
  };

  return (
    <div className="space-y-8 pb-20">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Employees</h1>
          <p className="text-slate-400 text-sm">Manage staff accounts and access.</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="bg-primary hover:bg-sky-400 text-white px-4 py-2.5 rounded-xl font-medium flex items-center justify-center gap-2 transition-colors shadow-lg shadow-primary/20"
        >
          <Plus size={20} />
          <span>Add Employee</span>
        </button>
      </div>

      {/* Search Bar */}
      <div className="bg-[#0f172a] p-4 rounded-2xl border border-white/5 shadow-lg">
        <div className="relative w-full md:max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search by name or email..."
            className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl py-2.5 pl-10 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:border-primary transition-colors"
          />
        </div>
      </div>

      {/* Employees Table/List */}
      <div className="bg-[#0f172a] border border-white/5 rounded-2xl shadow-xl overflow-hidden">
        {filteredEmployees.length === 0 ? (
          <div className="py-20 text-center text-slate-500">
             <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 border border-white/5">
               <Briefcase size={24} />
             </div>
             <p>No employees found.</p>
          </div>
        ) : (
          <>
            {/* Desktop Table */}
            <div className="hidden md:block overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="border-b border-white/5 text-xs text-slate-500 uppercase tracking-wider">
                    <th className="p-5 font-medium">Employee</th>
                    <th className="p-5 font-medium">Contact</th>
                    <th className="p-5 font-medium">Role</th>
                    <th className="p-5 font-medium">Status</th>
                    <th className="p-5 font-medium">Joined</th>
                    <th className="p-5 font-medium text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5 text-sm">
                  {filteredEmployees.map((emp) => (
                    <tr key={emp.id} className="hover:bg-white/[0.02] transition-colors group">
