                           <div className={selectedEmployee.status === 'Active' ? 'text-emerald-400' : 'text-red-400'}>{selectedEmployee.status}</div>
                        </div>
                        <div className="bg-slate-800/40 p-4 rounded-xl border border-white/5">
                           <div className="text-xs text-slate-500 mb-1">Joined</div>
                           <div className="text-white text-sm">{formatDate(selectedEmployee.createdAt)}</div>
                        </div>
                     </div>
                  </div>
               </div>

               <div className="p-6 border-t border-white/5 bg-[#0f172a] flex gap-3">
