                 <button onClick={() => setDeleteId(selectedEmployee.id)} className="flex-1 py-3 rounded-xl bg-red-500/10 text-red-400 font-medium text-sm flex items-center justify-center gap-2">
                    <Trash2 size={18} /> Delete
