// Scrolls the container to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    const scrollContainer = document.querySelector('.overflow-y-auto');
    if (scrollContainer) {
      scrollContainer.scrollTop = 0;
    }
  }, [pathname]);
  return null;
}

// Layout for the Mobile App
const MobileAppLayout = () => {
  const location = useLocation();

  const mainTabs = ['/home', '/support', '/news', '/notifications', '/more'];
  const showBottomNav = mainTabs.includes(location.pathname);

  return (
    <MobileShell>
      <ScrollToTop />
      {/* Route Content with Error Boundary */}
      <ErrorBoundary>
        <AnimatePresence mode="wait">
          <Routes location={location} key={location.pathname}>
            <Route path="/" element={<Splash />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/home" element={<Home />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/projects/:id" element={<ProjectDetails />} />
            <Route path="/support" element={<SupportChat />} />
            <Route path="/news" element={<Placeholder title="News" />} />
            <Route path="/notifications" element={<Notifications />} />

            {/* More Section */}
            <Route path="/more" element={<More />} />
            <Route path="/more/files" element={<FileManager />} />
            <Route path="/more/settings" element={<MoreSettings />} />
            <Route path="/more/about" element={<MoreAbout />} />
            <Route path="/more/terms" element={<MoreTerms />} />
            <Route path="/more/privacy" element={<MorePrivacy />} />

            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </AnimatePresence>
      </ErrorBoundary>

      {/* Persistent Bottom Navigation */}
      {showBottomNav && <BottomNav />}
    </MobileShell>
  );
};

// --- Secure Admin Route Protection ---
const ProtectedAdminRoute = ({ children }: { children: React.ReactNode }) => {
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        // Check admins/{uid}
        try {
          const snap = await getDoc(doc(db, 'admins', user.uid));
          if (snap.exists() && snap.data().status === 'Active') {
            setIsAdmin(true);
          } else {
            setIsAdmin(false);
          }
        } catch (e) {
          console.error("Admin check failed", e);
          setIsAdmin(false);
        }
      } else {
        setIsAdmin(false);
      }
    });
    return () => unsubscribe();
  }, []);

  if (isAdmin === null) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#020617] text-white">
        Loading...
      </div>
    );
  }

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return <>{children}</>;
};

const App: React.FC = () => {

  // Migration & Auth Listener
  useEffect(() => {
    if (auth) {
      const unsubscribe = onAuthStateChanged(auth, (user) => {
        if (user) {
          // Attempt migration whenever a user is logged in
          migrateLocalStorageToFirestore(user);
        }
      });
      return () => unsubscribe();
    }
  }, []);

  return (
    <HashRouter>
      <Routes>
        {/* Admin Routes - Full Screen, No MobileShell */}
        <Route path="/admin/login" element={<AdminLogin />} />

        <Route path="/admin/*" element={
          <ProtectedAdminRoute>
            <AdminLayout>
              <Routes>
                <Route path="projects" element={<AdminProjects />} />
                <Route path="user-projects" element={<AdminUserProjects />} />
                <Route path="users" element={<AdminUsers />} />
                <Route path="employees" element={<AdminEmployees />} />
                <Route path="roles" element={<AdminRoles />} />
                <Route path="ai" element={<AdminAI />} />
                {/* Default admin route */}
                <Route path="*" element={<Navigate to="/admin/projects" replace />} />
              </Routes>
            </AdminLayout>
          </ProtectedAdminRoute>
        } />

        {/* Main App Routes - Wrapped in MobileShell */}
        <Route path="/*" element={<MobileAppLayout />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import { NextApiRequest, NextApiResponse } from 'next';
import * as admin from 'firebase-admin';
import { adminAuth, adminDb } from '../../../../lib/firebaseAdmin';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  res.setHeader('Content-Type', 'application/json');

  try {
    if (req.method !== 'POST') {
      return res.status(405).json({ ok: false, code: "methodNotAllowed", message: "Method not allowed" });
    }

    const { 
      firstName, 
      lastName, 
      email, 
      password, 
      phone, 
      role, 
      status, 
      permissions,
      bootstrap 
    } = req.body;

    const authHeader = req.headers.authorization;

    // Reference to the ROOT admins collection
    const adminsRef = adminDb.collection('admins');

    // 1. Check if system is empty
    const snapshot = await adminsRef.limit(1).get();
    const isSystemEmpty = snapshot.empty;

    let creatorUid = 'system_bootstrap';
    let mode = 'normal';

    // 2. Access Control Logic
    if (isSystemEmpty) {
      console.log("System is empty. Allowing Bootstrap creation.");
      mode = 'bootstrap';
    } else {
      if (bootstrap) {
        return res.status(400).json({ ok: false, code: "alreadyInitialized", message: "System already initialized" });
      }

      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Authentication required" });
      }

      const idToken = authHeader.split('Bearer ')[1];
      try {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        creatorUid = decodedToken.uid;
      } catch (e) {
        return res.status(401).json({ ok: false, code: "notAuthenticated", message: "Invalid authentication token" });
      }
    }

    const finalRole = isSystemEmpty ? 'super_admin' : (role || 'admin');
    // Ensure permissions is an object map
    const finalPermissions = permissions || {}; 

    // 4. Create or Update Auth User
    let targetUid = '';

    try {
      const existingUser = await adminAuth.getUserByEmail(email);
      targetUid = existingUser.uid;

      const updatePayload: any = {};
      if (password) updatePayload.password = password;
      if (firstName || lastName) updatePayload.displayName = `${firstName} ${lastName}`;
      if (Object.keys(updatePayload).length > 0) {
        await adminAuth.updateUser(targetUid, updatePayload);
      }

    } catch (e: any) {
      if (e.code === 'auth/user-not-found') {
        const newUser = await adminAuth.createUser({
          email,
          password,
          displayName: `${firstName} ${lastName}`,
          phoneNumber: phone || undefined,
          disabled: status === 'Disabled'
        });
        targetUid = newUser.uid;
      } else {
        throw e;
      }
    }

    await adminAuth.setCustomUserClaims(targetUid, { 
      role: finalRole 
    });

    await adminsRef.doc(targetUid).set({
      id: targetUid,
      name: `${firstName} ${lastName}`,
      email,
      phone: phone || '',
      role: finalRole,
      status: status || 'Active',
      permissions: finalPermissions,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      createdBy: creatorUid,
      updatedAt: admin.firestore.FieldValue.serverTimestamp()
    }, { merge: true });

    return res.status(200).json({ 
      ok: true, 
      mode, 
      uid: targetUid 
    });

  } catch (error: any) {
    console.error("Create Admin API Error:", error);
    return res.status(500).json({ ok: false, code: "serverError", message: error.message || "Internal Server Error" });
  }
}

import { useEffect, useState } from 'react';
import { collection, addDoc, query, orderBy, onSnapshot, serverTimestamp, where } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export interface Message {
  id: string;
  roomId: string;
  senderId: string;
  senderName: string;
  senderRole: 'customer' | 'staff';
  text: string;
  createdAt: number;
}

const ROOM_ID = 'support-room';
const AUTO_REPLY_TEXT = "وصلتنا رسالتكم، سيتم الرد عليكم بأقرب وقت ممكن. شكرا لتواصلكم معنا.";

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;
  private unsubscribe: (() => void) | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.messages = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Root 'chats' collection
    const q = query(
      collection(db, 'chats'),
      where('ownerId', '==', uid),
      orderBy('createdAt', 'asc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.messages = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now()
        } as Message;
      });
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  async sendMessage(text: string) {
    if (!this.currentUid || !db) return;

    try {
       // 1. Add User Message
       await addDoc(collection(db, 'chats'), {
        roomId: ROOM_ID,
        ownerId: this.currentUid,
        senderId: this.currentUid,
        senderName: auth.currentUser?.displayName || 'User',
        senderRole: 'customer',
        text,
        createdAt: serverTimestamp()
      });

      // 2. Add Fixed Auto-Reply
      // We create a separate message document for the auto-reply immediately.
      // This ensures 1-to-1 response for this action.
      await addDoc(collection(db, 'chats'), {
        roomId: ROOM_ID,
        ownerId: this.currentUid,
        senderId: 'system_auto_reply',
        senderName: 'Raiyansoft Support',
        senderRole: 'staff',
        text: AUTO_REPLY_TEXT,
        createdAt: serverTimestamp()
      });

    } catch (e) {
      console.error("Error sending message", e);
    }
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
    };

    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages, isThinking: false };
};

import { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy, addDoc, updateDoc, deleteDoc, doc, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';

export interface Role {
  id: string;
  name: string;
  description: string;
  permissions: string[]; // Kept as array for UI convenience, mapped to object for AdminUser
  createdAt: number;
}

export const PERMISSIONS_LIST = [
  'Manage Projects',
  'Manage Users',
  'Manage Admins',
  'Manage Roles',
  'View Analytics'
];

class RoleStore {
  private roles: Role[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  constructor() {
    this.subscribeToFirestore();
  }

  private subscribeToFirestore() {
    if (!db) return;

    // Root 'roles' collection
    const q = query(collection(db, 'roles'), orderBy('createdAt', 'desc'));

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.roles = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          ...data,
          id: doc.id,
          createdAt: data.createdAt?.toMillis?.() || Date.now()
        } as Role;
      });
      this.notify();
    }, (error) => {
      console.error("Role fetch error:", error);
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getRoles() {
    return [...this.roles];
  }

  getRole(id: string) {
    return this.roles.find(r => r.id === id);
  }

  async addRole(role: Omit<Role, 'id' | 'createdAt'>) {
    if (!db) return;
    await addDoc(collection(db, 'roles'), {
      ...role,
      createdAt: serverTimestamp()
    });
  }

  async updateRole(id: string, updates: Partial<Omit<Role, 'id' | 'createdAt'>>) {
    if (!db) return;
    await updateDoc(doc(db, 'roles', id), updates);
  }

  async deleteRole(id: string) {
    if (!db) return;
    await deleteDoc(doc(db, 'roles', id));
  }
}

export const roleStore = new RoleStore();

export const useRoles = () => {
  const [roles, setRoles] = useState<Role[]>(roleStore.getRoles());

  useEffect(() => {
    const update = () => setRoles(roleStore.getRoles());
    update();
    return roleStore.subscribe(update);
  }, []);

  return { roles };
};

