const SupportChat: React.FC = () => {
  const { messages } = useMessages();
  const [inputText, setInputText] = useState('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    // Helper to find scrollable parent if needed, or just scroll current view
    const scrollContainer = bottomRef.current?.closest('.overflow-y-auto');
    if (scrollContainer) {
      scrollContainer.scrollTo({
        top: scrollContainer.scrollHeight,
        behavior
      });
    } else {
      bottomRef.current?.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    scrollToBottom('auto'); 
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages.length]);

  const handleSend = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim()) return;

    chatStore.sendMessage(inputText.trim());
    setInputText('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Group messages by day
  const groupedMessages: { date: number; msgs: Message[] }[] = [];
  messages.forEach(msg => {
    const d = new Date(msg.createdAt);
    if (isNaN(d.getTime())) return;

    const date = d.setHours(0,0,0,0);
    const lastGroup = groupedMessages[groupedMessages.length - 1];
    if (lastGroup && lastGroup.date === date) {
      lastGroup.msgs.push(msg);
    } else {
      groupedMessages.push({ date, msgs: [msg] });
    }
  });

  return (
    <div className="flex flex-col min-h-full relative"> 

      <ChatHeader />

      <div className="flex-1 px-4 pt-4" ref={scrollRef}>
        {groupedMessages.map((group) => (
          <React.Fragment key={group.date}>
            <DayDivider date={group.date} />
            {group.msgs.map((msg, index) => {
              const prevMsg = group.msgs[index - 1];
              // Show name if first msg or different sender
              const showName = !prevMsg || prevMsg.sender !== msg.sender;
              return <MessageBubble key={msg.id} msg={msg} showName={showName} />;
            })}
          </React.Fragment>
        ))}

        <div className="h-[100px] w-full" />
        <div ref={bottomRef} />
      </div>

      <div className="fixed bottom-[85px] left-0 right-0 max-w-[430px] mx-auto px-4 z-40">
        <motion.div 
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="bg-slate-900/90 backdrop-blur-xl p-2 rounded-2xl border border-white/10 shadow-[0_-5px_20px_rgba(0,0,0,0.4)] flex items-end gap-2"
        >
          <button className="p-3 text-slate-400 hover:text-white transition-colors">
            <Paperclip size={20} />
          </button>

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type a message..."
            rows={1}
            className="flex-1 bg-transparent text-white placeholder:text-slate-500 text-sm py-3 focus:outline-none resize-none max-h-24 no-scrollbar"
            style={{ minHeight: '44px' }}
          />

          <motion.button 
            whileTap={{ scale: 0.9 }}
            onClick={() => handleSend()}
            disabled={!inputText.trim()}
            className={`p-3 rounded-xl transition-all duration-300 ${
              inputText.trim()
                ? 'bg-primary text-white shadow-[0_0_15px_rgba(29,183,240,0.4)]' 
                : 'bg-slate-800 text-slate-500'
            }`}
          >
            <Send size={20} />
          </motion.button>
        </motion.div>
      </div>
    </div>
  );
};

