import { useEffect, useState } from 'react';
import { collection, addDoc, query, onSnapshot, serverTimestamp, orderBy, setDoc, doc, increment } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export interface Message {
  id: string;
  text: string;
  sender: 'customer' | 'staff';
  createdAt: number;
  senderName?: string;
}

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;
  private unsubscribe: (() => void) | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.messages = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Listen to subcollection: conversations/{uid}/messages
    const q = query(
      collection(db, 'conversations', uid, 'messages'),
      orderBy('createdAt', 'asc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      this.messages = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          text: data.text,
          sender: data.sender,
          senderName: data.senderName,
          // Handle Timestamp or millis
          createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : Date.now()
        } as Message;
      });
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  async sendMessage(text: string) {
    if (!this.currentUid || !db) return;

    const user = auth.currentUser;
    const conversationId = this.currentUid;

    try {
      const timestamp = serverTimestamp();

      // 1. Add Message to Subcollection
      await addDoc(collection(db, 'conversations', conversationId, 'messages'), {
        text,
        sender: 'customer',
        senderName: user?.displayName || 'Customer',
        createdAt: timestamp
      });

      // 2. Update Parent Conversation Document
      // Uses atomic increment for unread count to prevent race conditions
      await setDoc(doc(db, 'conversations', conversationId), {
        customerId: conversationId,
        customerName: user?.displayName || 'Anonymous',
        status: 'open',
        lastMessageText: text,
        lastMessageAt: timestamp,
        lastMessageSender: 'customer',
        unreadForAdmin: increment(1)
      }, { merge: true });

    } catch (e) {
      console.error("Error sending message", e);
    }
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
    };

    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages };
};

import { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, updateDoc, getDoc } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

// Standard "Ping" sound (Base64 to avoid external asset dependency)
const NOTIFICATION_SOUND = "data:audio/wav;base64,UklGRl9vT1BXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YU"; // Placeholder, simplified. 
// In a real app, use a proper mp3/wav url. Using a silent fallback for compilation safety if base64 is invalid.
// Let's use a real public URL for a pleasant "pop" sound.
const SOUND_URL = "https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3";

class AdminChatStore {
  private totalUnread: number = 0;
  private unreadMap: Record<string, number> = {}; // conversationId -> count
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  // State for logic
  private currentOpenChatId: string | null = null;
  private isSoundEnabled: boolean = false; // Default off until loaded
  private lastSoundPlayedAt: number = 0;
  private currentAdminId: string | null = null;

  constructor() {
    // Initialize Auth Listener to load preferences
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.currentAdminId = user.uid;
          this.loadPreferences(user.uid);
          this.subscribeToUnread();
        } else {
          this.currentAdminId = null;
          this.cleanup();
        }
      });
    }
  }

  private async loadPreferences(uid: string) {
    if (!db) return;
    try {
      const snap = await getDoc(doc(db, 'admins', uid));
      if (snap.exists()) {
        const data = snap.data();
        // Load preference, default to true if not set
        this.isSoundEnabled = data.preferences?.soundEnabled ?? true; 
        this.notify();
      }
    } catch (e) {
      console.error("Failed to load admin preferences", e);
    }
  }

  private cleanup() {
    if (this.unsubscribe) {
      this.unsubscribe();
      this.unsubscribe = null;
    }
    this.totalUnread = 0;
    this.unreadMap = {};
    this.notify();
  }

  // Subscribe ONLY to open conversations with unread messages
  // This ensures the sidebar badge works globally
  private subscribeToUnread() {
    if (!db) return;
    if (this.unsubscribe) this.unsubscribe();

    const q = query(
      collection(db, 'conversations'),
      where('status', '==', 'open'),
      where('unreadForAdmin', '>', 0)
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      let newTotal = 0;
      const newMap: Record<string, number> = {};
      let shouldPlaySound = false;

      snapshot.docs.forEach(doc => {
        const data = doc.data();
        const count = data.unreadForAdmin || 0;
        const lastSender = data.lastMessageSender;

        newMap[doc.id] = count;
        newTotal += count;

        // Sound Logic:
        // 1. Is it a customer message?
        // 2. Did the count increase for this chat?
        // 3. Is the admin NOT currently looking at this specific chat?
        if (lastSender === 'customer') {
          const prevCount = this.unreadMap[doc.id] || 0;
          if (count > prevCount && this.currentOpenChatId !== doc.id) {
            shouldPlaySound = true;
          }
        }
      });

      this.unreadMap = newMap;
      this.totalUnread = newTotal;

      if (shouldPlaySound) {
        this.triggerAlert();
      }

      this.notify();
    });
  }

  private triggerAlert() {
    const now = Date.now();
    // Debounce: 2 seconds
    if (now - this.lastSoundPlayedAt < 2000) return;

    // 1. Play Sound
    if (this.isSoundEnabled) {
      try {
        const audio = new Audio(SOUND_URL);
        audio.volume = 0.5;
        audio.play().catch(e => console.warn("Audio play blocked", e));
        this.lastSoundPlayedAt = now;
      } catch (e) {
        console.error("Sound error", e);
      }
    }

    // 2. Browser Notification (Optional)
    if (Notification.permission === "granted") {
       new Notification("New Support Message", {
         body: "A customer has sent a new message.",
         icon: "https://raiyansoft.com/wp-content/uploads/2024/05/cropped-App-Icon-1.png"
       });
    }
  }

  // --- Public API ---

  // Called by AdminLiveChat when user opens a chat
  public setCurrentChat(chatId: string | null) {
    this.currentOpenChatId = chatId;
  }

  // Toggle Sound Preference
  public async toggleSound(enabled: boolean) {
    this.isSoundEnabled = enabled;
    this.notify();

    // Persist
    if (this.currentAdminId && db) {
      try {
        await updateDoc(doc(db, 'admins', this.currentAdminId), {
          'preferences.soundEnabled': enabled
        });
      } catch (e) {
        console.error("Failed to save preference", e);
      }
    }

    // Request browser permission if enabling
    if (enabled && "Notification" in window && Notification.permission !== "granted") {
      Notification.requestPermission();
    }
  }

  public getSoundStatus() {
    return this.isSoundEnabled;
  }

  public getUnreadCount() {
    return this.totalUnread;
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }
}

export const adminChatStore = new AdminChatStore();

// React Hook
export const useAdminChatNotifications = () => {
  const [totalUnread, setTotalUnread] = useState(adminChatStore.getUnreadCount());
  const [isSoundEnabled, setIsSoundEnabled] = useState(adminChatStore.getSoundStatus());

  useEffect(() => {
    const update = () => {
      setTotalUnread(adminChatStore.getUnreadCount());
      setIsSoundEnabled(adminChatStore.getSoundStatus());
    };
    update();
    return adminChatStore.subscribe(update);
  }, []);

  return { totalUnread, isSoundEnabled };
};

