    { id: 'users', label: 'Users', icon: Users, path: '/admin/users' },
    { id: 'employees', label: 'Employees', icon: Briefcase, path: '/admin/employees' },
    { id: 'roles', label: 'Roles', icon: Shield, path: '/admin/roles' },
