      <div className="p-6 flex items-center space-x-3 border-b border-white/5">
        <div className="w-8 h-8 relative">
          <SafeImage 
            src="https://raiyansoft.com/wp-content/uploads/2024/05/cropped-App-Icon-1.png"
            alt="Raiyansoft"
            className="w-full h-full object-contain"
          />
        </div>
        <div>
          <h1 className="text-white font-bold text-lg leading-none">Raiyansoft</h1>
          <span className="text-xs text-primary font-medium">Admin Panel</span>
        </div>
      </div>

      {/* Nav Items */}
      <div className="flex-1 py-6 px-3 space-y-1 overflow-y-auto no-scrollbar">
        {navItems.map((item) => {
          const isActive = location.pathname.includes(item.path);
          return (
            <button
              key={item.id}
              onClick={() => {
                navigate(item.path);
                setIsMobileMenuOpen(false);
              }}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 relative ${
                isActive 
                  ? 'bg-primary/10 text-primary border border-primary/20' 
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <div className="relative">
                <item.icon size={20} />
                {/* Global Sidebar Badge */}
                {item.id === 'live-chat' && item.badge > 0 && (
                  <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-bold px-1.5 min-w-[18px] h-[18px] flex items-center justify-center rounded-full border-2 border-[#0f172a] shadow-sm z-10">
                    {item.badge > 99 ? '99+' : item.badge}
                  </span>
                )}
              </div>
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          );
        })}
      </div>

      {/* Footer / Logout */}
      <div className="p-4 border-t border-white/5">
        <button
          onClick={handleLogout}
          className="w-full flex items-center justify-center space-x-2 p-3 rounded-xl bg-slate-800/50 hover:bg-red-500/10 text-slate-400 hover:text-red-400 transition-colors border border-white/5 hover:border-red-500/20"
        >
          <LogOut size={18} />
          <span className="text-sm font-medium">Sign out</span>
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen w-full bg-[#020617] text-white flex overflow-hidden font-sans">
      {/* Desktop Sidebar */}
      <aside className="hidden md:block w-64 bg-[#0f172a] border-r border-white/5 shadow-2xl z-20">
        <SidebarContent />
      </aside>

      {/* Main Content Wrapper */}
      <div className="flex-1 flex flex-col relative w-full h-screen overflow-hidden">

        {/* Mobile Header */}
        <header className="md:hidden h-16 bg-[#0f172a]/80 backdrop-blur-md border-b border-white/5 flex items-center justify-between px-4 z-30 sticky top-0">
