const bottomRef = useRef<HTMLDivElement>(null);
const composerRef = useRef<HTMLDivElement>(null);

// 1. Measure height
useLayoutEffect(() => {
  if (!composerRef.current) return;
  const observer = new ResizeObserver((entries) => {
    for (const entry of entries) {
      setComposerHeight(entry.contentRect.height);
    }
  });
  observer.observe(composerRef.current);
  return () => observer.disconnect();
}, []);

// 2. Calculate dynamic spacing
const bottomSpacing = 85 + composerHeight + 20;

return (
  <div className="flex flex-col min-h-full relative"> 
    <ChatHeader />

    <div className="flex-1 px-4 pt-4" ref={scrollRef}>
      {/* ... messages loop ... */}

      {/* 3. Dynamic Spacer */}
      <div style={{ height: `${bottomSpacing}px` }} className="w-full transition-[height] duration-100 ease-out" />

      {/* 4. Sentinel */}
      <div ref={bottomRef} />
    </div>

    {/* 5. Fixed Composer */}
    <div 
      ref={composerRef}
      className="fixed bottom-[85px] left-0 right-0 max-w-[430px] mx-auto px-4 z-40"
    >
       {/* ... input ... */}
    </div>
  </div>
);
```

