// Scrolls the container to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    const scrollContainer = document.querySelector('.overflow-y-auto');
    if (scrollContainer) {
      scrollContainer.scrollTop = 0;
    }
  }, [pathname]);
  return null;
}

// Layout for the Mobile App
const MobileAppLayout = () => {
  const location = useLocation();

  const mainTabs = ['/home', '/support', '/news', '/notifications', '/more'];
  const showBottomNav = mainTabs.includes(location.pathname);

  return (
    <MobileShell>
      <ScrollToTop />
      {/* Route Content with Error Boundary */}
      <ErrorBoundary>
        <AnimatePresence mode="wait">
          <Routes location={location} key={location.pathname}>
            <Route path="/" element={<Splash />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/home" element={<Home />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/projects/:id" element={<ProjectDetails />} />
            <Route path="/support" element={<SupportChat />} />
            <Route path="/news" element={<Placeholder title="News" />} />
            <Route path="/notifications" element={<Notifications />} />

            {/* More Section */}
            <Route path="/more" element={<More />} />
            <Route path="/more/files" element={<FileManager />} />
            <Route path="/more/settings" element={<MoreSettings />} />
            <Route path="/more/about" element={<MoreAbout />} />
            <Route path="/more/terms" element={<MoreTerms />} />
            <Route path="/more/privacy" element={<MorePrivacy />} />

            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </AnimatePresence>
      </ErrorBoundary>

      {/* Persistent Bottom Navigation */}
      {showBottomNav && <BottomNav />}
    </MobileShell>
  );
};

// --- Secure Admin Route Protection ---
const ProtectedAdminRoute = ({ children }: { children: React.ReactNode }) => {
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        // Check admins/{uid}
        try {
          const snap = await getDoc(doc(db, 'admins', user.uid));
          if (snap.exists() && snap.data().status === 'Active') {
            setIsAdmin(true);
          } else {
            setIsAdmin(false);
          }
        } catch (e) {
          console.error("Admin check failed", e);
          setIsAdmin(false);
        }
      } else {
        setIsAdmin(false);
      }
    });
    return () => unsubscribe();
  }, []);

  if (isAdmin === null) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#020617] text-white">
        Loading...
      </div>
    );
  }

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return <>{children}</>;
};

const App: React.FC = () => {
  // Global auth listener only (removed migration)
  useEffect(() => {
    if (auth) {
      const unsubscribe = onAuthStateChanged(auth, (user) => {
        // User state handled by individual components/stores
      });
      return () => unsubscribe();
    }
  }, []);

  return (
    <HashRouter>
      <Routes>
        {/* Admin Routes - Full Screen, No MobileShell */}
        <Route path="/admin/login" element={<AdminLogin />} />

        <Route path="/admin/*" element={
          <ProtectedAdminRoute>
            <AdminLayout>
              <Routes>
                <Route path="projects" element={<AdminProjects />} />
                <Route path="user-projects" element={<AdminUserProjects />} />
                <Route path="live-chat" element={<AdminLiveChat />} />
                <Route path="users" element={<AdminUsers />} />
                <Route path="employees" element={<AdminEmployees />} />
                <Route path="roles" element={<AdminRoles />} />
                <Route path="account" element={<AdminAccount />} />
                {/* Default admin route */}
                <Route path="*" element={<Navigate to="/admin/projects" replace />} />
              </Routes>
            </AdminLayout>
          </ProtectedAdminRoute>
        } />

        {/* Main App Routes - Wrapped in MobileShell */}
        <Route path="/*" element={<MobileAppLayout />} />
      </Routes>
    </HashRouter>
  );
};

