                <input type="email" value={formData.signupEmail} onChange={e => setFormData({...formData, signupEmail: e.target.value})} className="w-full bg-slate-800 rounded-xl pl-10 pr-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
             </div>
          </div>
          <div className="space-y-1">
             <label className="text-xs text-slate-400 ml-1">Phone</label>
             <div className="relative">
                <Phone size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/>
                <input type="tel" value={formData.signupPhone} onChange={e => setFormData({...formData, signupPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl pl-10 pr-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
             </div>
          </div>
          <div className="space-y-1">
             <label className="text-xs text-slate-400 ml-1">Password</label>
             <div className="relative">
                <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/>
                <input type="password" value={formData.signupPassword} onChange={e => setFormData({...formData, signupPassword: e.target.value})} className="w-full bg-slate-800 rounded-xl pl-10 pr-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
             </div>
          </div>
          <div className="space-y-1">
             <label className="text-xs text-slate-400 ml-1">Confirm Password</label>
             <div className="relative">
                <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/>
                <input type="password" value={formData.signupConfirmPassword} onChange={e => setFormData({...formData, signupConfirmPassword: e.target.value})} className="w-full bg-slate-800 rounded-xl pl-10 pr-4 py-3 text-white border border-white/10 focus:border-primary focus:outline-none" />
             </div>
          </div>
       </div>
    </div>
  );

  const renderReview = () => (
    <div className="flex flex-col h-full p-4 overflow-y-auto no-scrollbar pb-32">
      <h2 className="text-2xl font-bold text-white mb-1">Review & Edit</h2>
      <p className="text-slate-400 text-sm mb-6">Finalize your project details before creation.</p>

      <div className="space-y-6">

        {/* Block 1: Essentials */}
        <div className="bg-slate-800/30 p-4 rounded-2xl border border-white/5 space-y-4">
          <h3 className="text-sm font-bold text-white border-b border-white/5 pb-2">Project Essentials</h3>

          {/* Name */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase">Project Name</label>
            <input 
              type="text" 
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})} 
              className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none transition-colors"
            />
          </div>

          {/* Description */}
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Description</label>
             <textarea 
               value={formData.description} 
               onChange={e => setFormData({...formData, description: e.target.value})} 
               className="w-full h-24 bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none resize-none text-sm leading-relaxed transition-colors" 
             />
          </div>

          {/* Industry */}
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase">Industry</label>
            <div className="grid grid-cols-1 gap-2">
              <select 
                value={formData.industry} 
                onChange={e => setFormData({...formData, industry: e.target.value})}
                className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none appearance-none"
              >
                <option value="" disabled>Select Industry</option>
                {INDUSTRIES.map(ind => <option key={ind} value={ind}>{ind}</option>)}
              </select>

              {formData.industry === 'Other' && (
                <input 
                  type="text" 
                  value={formData.industryOther} 
                  onChange={e => setFormData({...formData, industryOther: e.target.value})} 
                  placeholder="Specify Industry"
                  className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none transition-colors"
                />
              )}
            </div>
          </div>
        </div>

        {/* Block 2: Technical Configuration */}
        <div className="bg-slate-800/30 p-4 rounded-2xl border border-white/5 space-y-4">
          <h3 className="text-sm font-bold text-white border-b border-white/5 pb-2">Configuration</h3>

          {/* Platforms */}
          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Platforms</label>
            <div className="flex flex-wrap gap-2">
              {PLATFORMS.map(p => (
                <button 
                  key={p} 
                  onClick={() => toggleArray(formData.platforms, p, 'platforms')} 
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${formData.platforms.includes(p) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10 hover:border-white/20'}`}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>

          {/* Languages */}
          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Languages</label>
            <div className="flex flex-wrap gap-2">
              {LANGUAGES.map(l => (
                <button 
                  key={l} 
                  onClick={() => toggleArray(formData.languages, l, 'languages')} 
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${formData.languages.includes(l) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10 hover:border-white/20'}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>

          {/* Markets */}
          <div>
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Target Markets</label>
            <div className="flex flex-wrap gap-2">
              {MARKETS.map(m => (
                <button 
                  key={m} 
                  onClick={() => toggleArray(formData.markets, m, 'markets')} 
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${formData.markets.includes(m) ? 'bg-primary/20 text-primary border-primary/30' : 'bg-slate-900 text-slate-400 border-white/10 hover:border-white/20'}`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Block 3: Business Details */}
        <div className="bg-slate-800/30 p-4 rounded-2xl border border-white/5 space-y-4">
          <h3 className="text-sm font-bold text-white border-b border-white/5 pb-2">Business Logic</h3>

          {/* Service Model */}
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Service Model</label>
             <select 
                value={formData.serviceModel} 
                onChange={e => setFormData({...formData, serviceModel: e.target.value})}
                className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none appearance-none"
             >
                <option value="" disabled>Select Model</option>
                {SERVICE_MODELS.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>

          {/* Closest App */}
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Reference App</label>
             <select 
                value={formData.closestApp} 
                onChange={e => setFormData({...formData, closestApp: e.target.value})}
                className="w-full bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none appearance-none"
             >
                <option value="" disabled>Select Reference</option>
                {CLOSEST_APPS.map(app => <option key={app} value={app}>{app}</option>)}
             </select>
          </div>

          {/* Payments & Existing Biz (Row) */}
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-2">In-App Payments</label>
                <div className="flex rounded-lg overflow-hidden border border-white/10">
                   <button 
                     onClick={() => setFormData({...formData, hasPayments: true})}
                     className={`flex-1 py-2 text-xs font-medium transition-colors ${formData.hasPayments ? 'bg-primary text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}
                   >
                     Yes
                   </button>
                   <div className="w-px bg-white/10"></div>
                   <button 
                     onClick={() => setFormData({...formData, hasPayments: false})}
                     className={`flex-1 py-2 text-xs font-medium transition-colors ${!formData.hasPayments ? 'bg-slate-700 text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}
                   >
                     No
                   </button>
                </div>
             </div>

             <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Existing Biz</label>
                <div className="flex rounded-lg overflow-hidden border border-white/10">
                   <button 
                     onClick={() => setFormData({...formData, hasExistingBusiness: true})}
                     className={`flex-1 py-2 text-xs font-medium transition-colors ${formData.hasExistingBusiness ? 'bg-primary text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}
                   >
                     Yes
                   </button>
                   <div className="w-px bg-white/10"></div>
                   <button 
                     onClick={() => setFormData({...formData, hasExistingBusiness: false})}
                     className={`flex-1 py-2 text-xs font-medium transition-colors ${!formData.hasExistingBusiness ? 'bg-slate-700 text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}
                   >
                     No
                   </button>
                </div>
             </div>
          </div>
        </div>

        {/* Block 4: Branding */}
        <div className="bg-slate-800/30 p-4 rounded-2xl border border-white/5 space-y-4">
          <h3 className="text-sm font-bold text-white border-b border-white/5 pb-2">Branding</h3>

          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">Primary Color</label>
             <div className="flex gap-3 items-center">
                <input 
                  type="color" 
                  value={formData.brandColor} 
                  onChange={e => setFormData({...formData, brandColor: e.target.value})} 
                  className="h-10 w-14 rounded-lg cursor-pointer bg-transparent border border-white/10 p-0.5" 
                />
                <input 
                  type="text" 
                  value={formData.brandColor} 
                  onChange={e => setFormData({...formData, brandColor: e.target.value})} 
                  className="flex-1 bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none uppercase font-mono transition-colors" 
                />
             </div>

             {/* Mini Presets */}
             <div className="flex gap-2 mt-2 overflow-x-auto no-scrollbar pt-1">
               {PRESET_COLORS.map(c => (
                 <button 
                   key={c.hex} 
                   onClick={() => setFormData({...formData, brandColor: c.hex})}
                   className={`w-6 h-6 rounded-full border border-white/10 shrink-0 ${formData.brandColor.toLowerCase() === c.hex.toLowerCase() ? 'ring-2 ring-primary ring-offset-1 ring-offset-slate-900' : ''}`}
                   style={{ backgroundColor: c.hex }}
                 />
               ))}
             </div>
          </div>
        </div>

      </div>
    </div>
  );

  // Main Render Switch
  const renderStep = () => {
    switch (step) {
      case 0: return renderIntro();
      case 1: return renderMultiSelect("Which platforms do you need?", PLATFORMS, formData.platforms, 'platforms');
      case 2: return renderMultiSelect("Which languages do you need?", LANGUAGES, formData.languages, 'languages');
      case 3: return renderMultiSelect("Which markets are you targeting?", MARKETS, formData.markets, 'markets');
      case 4: return renderIndustryStep();
      case 5: return renderSingleChoice("Will your app include in-app payments?", [{label:'Yes', value: true}, {label: 'No', value: false}], formData.hasPayments, 'hasPayments', true);
      case 6: return renderSingleChoice("Do you already have an active business?", [{label:'Yes', value: true}, {label: 'No', value: false}], formData.hasExistingBusiness, 'hasExistingBusiness', true);
      case 7: return renderSingleChoice("How will the service be delivered?", SERVICE_MODELS, formData.serviceModel, 'serviceModel');
      case 8: return renderSingleChoice("Which app is closest to your idea?", CLOSEST_APPS, formData.closestApp, 'closestApp');
      case 9: return renderTextInput("What is the initial name for your app?", formData.name, 'name', "e.g. Super Delivery");
      case 10: return renderColorPicker();
      case 11: return renderSignup();
      case 12: return renderReview();
      default: return null;
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-center items-start md:items-center bg-[#020617] md:bg-black/60 md:backdrop-blur-sm">
      {/* Mobile-width Container */}
      <div className="w-full max-w-[430px] h-full bg-[#020617] flex flex-col relative shadow-2xl overflow-hidden md:border md:border-white/5">

        {/* Header */}
        <div className="px-6 py-4 flex items-center justify-between border-b border-white/5 bg-[#0f172a]">
          <button onClick={step === 0 ? onClose : prevStep} className="p-2 -ml-2 text-slate-400 hover:text-white transition-colors">
            {step === 0 ? <X size={24} /> : <ChevronLeft size={24} />}
          </button>
          <div className="flex space-x-1.5">
            {Array.from({ length: isAuthenticated ? 12 : 13 }).map((_, i) => (
               <div 
                 key={i} 
                 className={`h-1.5 rounded-full transition-all duration-300 ${i === step ? 'w-6 bg-primary' : i < step ? 'w-1.5 bg-primary/50' : 'w-1.5 bg-slate-800'}`}
               />
            ))}
          </div>
          <div className="w-10" /> {/* Spacer for centering */}
        </div>

        {/* Content Area */}
        <div className="flex-1 relative overflow-hidden">
          <AnimatePresence initial={false} custom={direction}>
            <motion.div
              key={step}
              custom={direction}
              initial={{ x: direction > 0 ? 300 : -300, opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: direction > 0 ? -300 : 300, opacity: 0 }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="absolute inset-0 w-full h-full"
            >
              {renderStep()}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Footer / Controls */}
        <div className="p-6 pb-28 border-t border-white/5 bg-[#0f172a] z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.2)]">

          {/* Error Message */}
          {errors.length > 0 && (
            <motion.div 
              initial={{ opacity: 0, y: 10 }} 
              animate={{ opacity: 1, y: 0 }}
              className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-medium text-center"
            >
              {errors[0]}
            </motion.div>
          )}

          {step === 0 ? null : (
            <button 
              onClick={step === 12 ? handleCreate : nextStep}
              disabled={isLoading}
              className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center space-x-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                 <Loader2 size={24} className="animate-spin" />
              ) : (
                <>
                   <span>{step === 12 ? (isAuthenticated ? 'Create Project' : 'Create Account & Project') : step === 11 ? 'Create Account' : 'Next'}</span>
                   {step !== 12 && <ChevronRight size={20} />}
                </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProjectWizard;

// @ts-nocheck
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight, Check, X, Smartphone, Globe, CreditCard, Store, ShoppingBag, Zap, Palette, User, Mail, Phone, Lock, Briefcase, Loader2 } from 'lucide-react';
import { userProjectsStore } from '../lib/userProjectsStore';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { auth } from '../lib/firebase';

interface ProjectWizardProps {
  onClose: () => void;
  onComplete: () => void;
}

// Wizard Steps Data
const PLATFORMS = ['Website', 'iOS', 'Android'];
const LANGUAGES = ['Arabic', 'English'];
const MARKETS = ['Kuwait', 'GCC', 'Arab World', 'Global'];
const SERVICE_MODELS = ['Direct to customer', 'Marketplace'];
const CLOSEST_APPS = ['Talabat', '4Sale', 'Sheeel', 'Careem', 'None'];

const INDUSTRIES = [
  'Food & Delivery',
  'Fashion & Clothing',
  'Pharmacy & Healthcare',
  'Pets & Animals',
  'Services',
  'Education',
  'Real Estate',
  'Travel & Tourism',
  'Finance',
  'Logistics & Shipping',
  'Other'
];

const PRESET_COLORS = [
  { hex: '#1DB7F0', name: 'Raiyansoft' },
  { hex: '#10B981', name: 'Teal' },
  { hex: '#FACC15', name: 'Gold' },
  { hex: '#8B5CF6', name: 'Purple' },
  { hex: '#EF4444', name: 'Red' },
  { hex: '#FFFFFF', name: 'White' }
];

const ProjectWizard: React.FC<ProjectWizardProps> = ({ onClose, onComplete }) => {
  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const isAuthenticated = !!auth.currentUser;

  // Form State
  const [formData, setFormData] = useState({
    platforms: [] as string[],
    languages: [] as string[],
    markets: [] as string[],
    industry: '',
    industryOther: '',
    hasPayments: null as boolean | null,
    hasExistingBusiness: null as boolean | null,
    serviceModel: '',
    closestApp: '',
    name: '',
    brandColor: '#1DB7F0',
    description: '', // Generated later

    // Signup Data
    signupFirstName: '',
    signupLastName: '',
    signupPhone: '',
    signupEmail: '',
    signupPassword: '',
    signupConfirmPassword: ''
  });

  const [showCustomColor, setShowCustomColor] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Navigation Logic
  // 0: Intro, 1: Platforms, 2: Languages, 3: Markets, 4: Industry
  // 5: Payments, 6: Existing Biz, 7: Service Model, 8: Closest App
  // 9: Name, 10: Color, 11: Signup, 12: Review

  const nextStep = () => {
    if (validateStep(step)) {
      setDirection(1);
      // Skip Signup Step (11) if already authenticated
      if (step === 10 && isAuthenticated) {
        generateAndSetDescription();
        setStep(12);
      } else {
        if (step === 11) {
            // Finishing signup step, generate description for review
            generateAndSetDescription();
        }
        setStep(step + 1);
      }
    }
  };

  const prevStep = () => {
    setDirection(-1);
    if (step === 12 && isAuthenticated) {
      setStep(10);
    } else {
      setStep(step - 1);
    }
  };

  const validateStep = (currentStep: number): boolean => {
    setErrors([]);
    const newErrors: string[] = [];

    switch (currentStep) {
      case 1: if (formData.platforms.length === 0) newErrors.push("Select a platform"); break;
      case 2: if (formData.languages.length === 0) newErrors.push("Select a language"); break;
      case 3: if (formData.markets.length === 0) newErrors.push("Select a market"); break;
      case 4: 
        if (!formData.industry) newErrors.push("Select an industry"); 
        if (formData.industry === 'Other' && !formData.industryOther?.trim()) newErrors.push("Please specify the industry");
        break;
      case 5: if (formData.hasPayments === null) newErrors.push("Please select an option"); break;
      case 6: if (formData.hasExistingBusiness === null) newErrors.push("Please select an option"); break;
      case 7: if (!formData.serviceModel) newErrors.push("Please select a service model"); break;
      case 8: if (!formData.closestApp) newErrors.push("Please select a reference"); break;
      case 9: if (!formData.name.trim()) newErrors.push("Please enter an app name"); break;
      case 10: if (!formData.brandColor) newErrors.push("Please select a color"); break;
      case 11: // Signup Validation
        if (!isAuthenticated) {
          if (!formData.signupFirstName) newErrors.push("First Name is required");
          if (!formData.signupLastName) newErrors.push("Last Name is required");
          if (!formData.signupEmail.includes('@')) newErrors.push("Valid email is required");
          if (!formData.signupPhone) newErrors.push("Phone is required");
          if (formData.signupPassword.length < 6) newErrors.push("Password too short");
          if (formData.signupPassword !== formData.signupConfirmPassword) newErrors.push("Passwords do not match");
        }
        break;
      case 12: 
        if (!formData.name.trim()) newErrors.push("Project name is required");
        if (!formData.description.trim()) newErrors.push("Description is required");
        break;
    }

    if (newErrors.length > 0) {
      setErrors(newErrors);
      return false;
    }

    return true;
  };

  const generateAndSetDescription = () => {
    const parts = [];
    const industryText = formData.industry === 'Other' ? (formData.industryOther || 'custom') : formData.industry;

    parts.push(`A ${formData.serviceModel.toLowerCase()} ${industryText} platform`);

    if (formData.closestApp !== 'None') parts.push(`similar to ${formData.closestApp}`);
    parts.push(`targeting ${formData.markets.join(', ')}.`);

    parts.push(`Available on ${formData.platforms.join(' & ')}`);
    parts.push(`in ${formData.languages.join(' & ')}.`);

    if (formData.hasPayments) parts.push("Includes in-app payments.");
    if (formData.hasExistingBusiness) parts.push("Supports an existing business.");
    else parts.push("New business venture.");

    setFormData(prev => ({ ...prev, description: parts.join(' ') }));
  };

  const handleCreate = async () => {
    if (!validateStep(12)) return;
    setIsLoading(true);
    setErrors([]);

    try {
      let user = auth.currentUser;

      if (!user) {
        const userCredential = await createUserWithEmailAndPassword(auth, formData.signupEmail, formData.signupPassword);
        user = userCredential.user;
        await updateProfile(user, {
          displayName: `${formData.signupFirstName} ${formData.signupLastName}`
        });
      }

      await userProjectsStore.addProject({
        name: formData.name,
        description: formData.description,
        ownerName: user.displayName || 'User',
        ownerEmail: user.email || '',
        ownerId: user.uid,
        estimatedPrice: null,
        estimatedDuration: null,
        status: 'pricing',
        projectUrl: null,
        platforms: formData.platforms,
        languages: formData.languages,
        markets: formData.markets,
        industry: formData.industry,
        industryOther: formData.industryOther,
        hasPayments: formData.hasPayments || false,
        hasExistingBusiness: formData.hasExistingBusiness || false,
        serviceModel: formData.serviceModel,
        closestApp: formData.closestApp,
        brandColor: formData.brandColor
      });

      onComplete();
    } catch (e: any) {
      console.error(e);
      let msg = "Failed to create project.";
      if (e.code === 'auth/email-already-in-use') msg = "Email already in use. Please sign in.";
      else if (e.message) msg = e.message;
      setErrors([msg]);
    } finally {
      setIsLoading(false);
    }
  };

  // Helper Inputs
  const toggleArray = (arr: string[], val: string, key: 'platforms' | 'languages' | 'markets') => {
    const newArr = arr.includes(val) ? arr.filter(i => i !== val) : [...arr, val];
    setFormData({ ...formData, [key]: newArr });
  };

  const handleAutoSelection = (key: string, value: any, isArray = false) => {
    if (isArray) {
        setFormData(prev => ({ ...prev, [key]: [value] }));
    } else {
        setFormData(prev => ({ ...prev, [key]: value }));
