              <AlertCircle size={16} className="text-red-400 shrink-0 mt-0.5" />
              <div className="flex flex-col">
                 <span className="text-red-400 text-xs font-bold">{error.message}</span>
              </div>
            </div>
          )}

          <motion.button
            whileHover={{ scale: 1.02 }}
