const SupportChat: React.FC = () => {
  const { messages } = useMessages();
  const [inputText, setInputText] = useState('');
  const { t, dir } = useTranslation();

  // Refs
  const pageRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const composerRef = useRef<HTMLDivElement>(null);

  // 1. Dynamic Height Measurement
  useLayoutEffect(() => {
    if (!composerRef.current || !pageRef.current) return;

    const updateHeights = () => {
      const composerH = composerRef.current?.offsetHeight || 60;
      pageRef.current?.style.setProperty('--composer-h', `${composerH}px`);
      pageRef.current?.style.setProperty('--tabbar-h', `${TAB_BAR_HEIGHT}px`);
    };

    // Initial measure
    updateHeights();

    // Observe changes (e.g. textarea expansion)
    const observer = new ResizeObserver(updateHeights);
    observer.observe(composerRef.current);

    return () => observer.disconnect();
  }, []);

  const scrollToBottom = (behavior: ScrollBehavior = 'auto') => {
    messagesEndRef.current?.scrollIntoView({ behavior, block: 'end' });
  };

  // 2. Scroll Logic
  // Initial load
  useEffect(() => {
    // Small timeout to allow layout to settle
    const timer = setTimeout(() => scrollToBottom('auto'), 100);
    return () => clearTimeout(timer);
  }, []);

  // On new messages
  useEffect(() => {
    scrollToBottom('smooth');
  }, [messages.length]);

  const handleSend = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim()) return;

    chatStore.sendMessage(inputText.trim());
    setInputText('');
    // Force scroll after sending
    setTimeout(() => scrollToBottom('auto'), 50);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Group messages
  const groupedMessages: { date: number; msgs: Message[] }[] = [];
  messages.forEach(msg => {
    const d = new Date(msg.createdAt);
    if (isNaN(d.getTime())) return;

    const date = d.setHours(0,0,0,0);
    const lastGroup = groupedMessages[groupedMessages.length - 1];
    if (lastGroup && lastGroup.date === date) {
      lastGroup.msgs.push(msg);
    } else {
      groupedMessages.push({ date, msgs: [msg] });
    }
  });

  return (
    // 3. Root Container
    // Fixed height (100dvh) to prevent body scroll interaction
    // Flex column to stack Header, Messages, and (Absolute) Composer
    <div 
      ref={pageRef}
      className="flex flex-col w-full h-full relative overflow-hidden bg-[#020617]"
      style={{ height: '100dvh' }}
    >
      <ChatHeader />

      {/* 
         4. Messages Scroller 
         - Takes remaining space (flex-1)
         - Handles its own scrolling (overflow-y-auto)
         - Dynamic padding-bottom reserves space for Composer + TabBar + Safe Area
      */}
      <div 
        className="flex-1 overflow-y-auto w-full px-4 pt-4 no-scrollbar"
        style={{
          paddingBottom: `calc(var(--composer-h, 60px) + var(--tabbar-h, 80px) + ${BOTTOM_SAFE_AREA}px)`,
          scrollPaddingBottom: `calc(var(--composer-h, 60px) + var(--tabbar-h, 80px) + ${BOTTOM_SAFE_AREA}px)`
        }}
      >
        {groupedMessages.map((group) => (
          <React.Fragment key={group.date}>
            <DayDivider date={group.date} />
            {group.msgs.map((msg, index) => {
              const prevMsg = group.msgs[index - 1];
              const showName = !prevMsg || prevMsg.sender !== msg.sender;
              return <MessageBubble key={msg.id} msg={msg} showName={showName} />;
            })}
          </React.Fragment>
        ))}

        {/* Bottom Sentinel for Auto-scroll */}
        <div ref={messagesEndRef} className="h-px w-full" />
      </div>

      {/* 
         5. Fixed Composer 
         - Positioned absolutely at the bottom (above tab bar)
         - Uses Z-index to float above potential content
      */}
      <div 
        ref={composerRef}
        className="absolute left-0 right-0 z-40 px-4"
        style={{
          bottom: `calc(var(--tabbar-h, 80px) + 5px)` 
        }}
      >
        <motion.div 
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="bg-slate-900/90 backdrop-blur-xl p-2 rounded-2xl border border-white/10 shadow-[0_-5px_20px_rgba(0,0,0,0.4)] flex items-end gap-2 max-w-[430px] mx-auto"
        >
          <button className="p-3 text-slate-400 hover:text-white transition-colors shrink-0">
            <Paperclip size={20} />
          </button>

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={t('chat.type_message')}
            rows={1}
            dir={dir}
            className="flex-1 bg-transparent text-white placeholder:text-slate-500 text-sm py-3 focus:outline-none resize-none max-h-24 no-scrollbar"
            style={{ minHeight: '44px' }}
          />

          <motion.button 
            whileTap={{ scale: 0.9 }}
            onClick={() => handleSend()}
            disabled={!inputText.trim()}
            className={`p-3 rounded-xl transition-all duration-300 shrink-0 ${
              inputText.trim()
                ? 'bg-primary text-white shadow-[0_0_15px_rgba(29,183,240,0.4)]' 
                : 'bg-slate-800 text-slate-500'
            }`}
          >
            {dir === 'rtl' ? <Send size={20} className="scale-x-[-1]" /> : <Send size={20} />}
          </motion.button>
        </motion.div>
      </div>
    </div>
  );
};

export default SupportChat;

import { useState, useEffect } from 'react';
import { collection, doc, getDoc, setDoc, updateDoc, query, where, getDocs, onSnapshot, serverTimestamp, addDoc, orderBy, limit } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export interface AppointmentSettings {
  durationMin: number;
  dailyLimit: number;
  bufferMin: number;
  minNoticeHours: number;
  maxWindowDays: number;
  weeklyAvailability: Record<number, { enabled: boolean; ranges: { start: string; end: string }[] }>;
  formFields: any[]; // Simplified for V1
}

export interface Appointment {
  id: string;
  userId?: string;
  guestName?: string;
  guestEmail?: string;
  guestPhone?: string;
  startAt: number; // ms timestamp
  endAt: number;
  status: 'scheduled' | 'cancelled' | 'completed';
  meetingType: 'online' | 'in_person';
  topic: string;
  notes?: string;
  createdAt: number;
}

const DEFAULT_SETTINGS: AppointmentSettings = {
  durationMin: 30,
  dailyLimit: 10,
  bufferMin: 15,
  minNoticeHours: 2,
  maxWindowDays: 14,
  weeklyAvailability: {
    0: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Sun
    1: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Mon
    2: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Tue
    3: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Wed
    4: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Thu
    5: { enabled: false, ranges: [] }, // Fri
    6: { enabled: false, ranges: [] }, // Sat
  },
  formFields: []
};

class AppointmentStore {
  private settings: AppointmentSettings = DEFAULT_SETTINGS;
  private activeAppointment: Appointment | null = null;
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        this.currentUid = user ? user.uid : null;
        if (user) {
          this.subscribeToActiveAppointment();
        } else {
          this.activeAppointment = null;
          this.notify();
        }
      });
    }
    this.fetchSettings();
  }

  // --- Settings Management ---
  async fetchSettings() {
    if (!db) return;
    try {
      const snap = await getDoc(doc(db, 'appointment_settings', 'global'));
      if (snap.exists()) {
        this.settings = { ...DEFAULT_SETTINGS, ...snap.data() } as AppointmentSettings;
      } else {
        // Init default if not exists
        await setDoc(doc(db, 'appointment_settings', 'global'), DEFAULT_SETTINGS);
      }
      this.notify();
    } catch (e) {
      console.error("Error fetching settings", e);
    }
  }

  async updateSettings(newSettings: Partial<AppointmentSettings>) {
    if (!db) return;
    await setDoc(doc(db, 'appointment_settings', 'global'), newSettings, { merge: true });
    this.settings = { ...this.settings, ...newSettings };
    this.notify();
  }

  getSettings() {
    return this.settings;
  }

  // --- Active Appointment (One per user rule) ---
  private subscribeToActiveAppointment() {
    if (!db || !this.currentUid) return;

    const now = Date.now();
    const q = query(
      collection(db, 'appointments'),
      where('userId', '==', this.currentUid),
      where('status', '==', 'scheduled'),
      where('endAt', '>', now),
      orderBy('endAt', 'asc'),
      limit(1)
    );

    onSnapshot(q, (snap) => {
      if (!snap.empty) {
        const d = snap.docs[0].data();
        this.activeAppointment = { id: snap.docs[0].id, ...d } as Appointment;
      } else {
        this.activeAppointment = null;
      }
      this.notify();
    });
  }

  getActiveAppointment() {
    return this.activeAppointment;
  }

  // --- Slot Generation ---
  async getAvailableSlots(date: Date): Promise<string[]> {
    if (!db) return [];

    const dayIndex = date.getDay(); // 0 = Sun in JS? No, 0=Sun, 1=Mon... wait.
    // JS: 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat.
    // Our map keys align with this.

    const dayConfig = this.settings.weeklyAvailability[dayIndex];
    if (!dayConfig || !dayConfig.enabled) return [];

    // 1. Fetch existing appointments for this day
    const startOfDay = new Date(date);
    startOfDay.setHours(0,0,0,0);
    const endOfDay = new Date(date);
    endOfDay.setHours(23,59,59,999);

    const q = query(
      collection(db, 'appointments'),
      where('startAt', '>=', startOfDay.getTime()),
      where('startAt', '<=', endOfDay.getTime()),
      where('status', '==', 'scheduled')
    );

    const snap = await getDocs(q);
    const bookedRanges = snap.docs.map(d => ({
      start: d.data().startAt,
      end: d.data().endAt
    }));

    // 2. Generate Slots
    const slots: string[] = [];
    const durationMs = this.settings.durationMin * 60000;
    const bufferMs = this.settings.bufferMin * 60000;
    const minNoticeMs = this.settings.minNoticeHours * 3600000;
    const nowMs = Date.now();

    dayConfig.ranges.forEach(range => {
      const [startH, startM] = range.start.split(':').map(Number);
      const [endH, endM] = range.end.split(':').map(Number);

      let currentSlot = new Date(date);
      currentSlot.setHours(startH, startM, 0, 0);

      const rangeEnd = new Date(date);
      rangeEnd.setHours(endH, endM, 0, 0);

      while (currentSlot.getTime() + durationMs <= rangeEnd.getTime()) {
        const slotStartMs = currentSlot.getTime();
        const slotEndMs = slotStartMs + durationMs;

        // Check 1: In the past / Notice period
        if (slotStartMs < nowMs + minNoticeMs) {
          currentSlot = new Date(slotEndMs + bufferMs);
          continue;
        }

        // Check 2: Overlap
        const isBooked = bookedRanges.some(booking => {
          return (slotStartMs < booking.end && slotEndMs > booking.start);
        });

        if (!isBooked) {
          slots.push(currentSlot.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
        }

        currentSlot = new Date(slotEndMs + bufferMs);
      }
    });

    return slots;
  }

  // --- Actions ---
  async bookAppointment(data: any) {
    if (!db) throw new Error("DB not connected");

    // Check one active rule again (server side usually, but client safety here)
    if (this.currentUid && this.activeAppointment) {
      throw new Error("You already have an active appointment.");
    }

    const { date, time, ...details } = data;
    // Parse date+time to timestamp
    const [h, m] = time.split(':').map(Number);
    const startAt = new Date(date);
    startAt.setHours(h, m, 0, 0);
    const startAtMs = startAt.getTime();
    const durationMs = this.settings.durationMin * 60000;
    const endAtMs = startAtMs + durationMs;

    const payload = {
      userId: this.currentUid || null,
      guestName: details.guestName || null,
      guestEmail: details.guestEmail || null,
      guestPhone: details.guestPhone || null,
      meetingType: details.meetingType,
      topic: details.topic,
      notes: details.notes || '',
      startAt: startAtMs,
      endAt: endAtMs,
      status: 'scheduled',
      createdAt: serverTimestamp()
    };

    await addDoc(collection(db, 'appointments'), payload);
  }

  async cancelAppointment(id: string) {
    if (!db) return;
    await updateDoc(doc(db, 'appointments', id), { status: 'cancelled' });
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const appointmentStore = new AppointmentStore();

export const useAppointments = () => {
  const [activeAppointment, setActiveAppointment] = useState<Appointment | null>(appointmentStore.getActiveAppointment());
  const [settings, setSettings] = useState<AppointmentSettings>(appointmentStore.getSettings());

  useEffect(() => {
    const update = () => {
      setActiveAppointment(appointmentStore.getActiveAppointment());
      setSettings(appointmentStore.getSettings());
    };
    update();
    return appointmentStore.subscribe(update);
  }, []);

  return { activeAppointment, settings };
};

