import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, Clock, Video, MapPin, X, ChevronRight, ChevronLeft, Loader2, CheckCircle } from 'lucide-react';
import { useAppointments, appointmentStore } from '../lib/appointmentStore';
import { useTranslation } from '../lib/i18nContext';
import ConfirmModal from '../components/ConfirmModal';
import { auth } from '../lib/firebase';

// Helper: Generate Dates for the next X days
const getDates = (days: number) => {
  const dates = [];
  const today = new Date();
  for (let i = 0; i < days; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    dates.push(d);
  }
  return dates;
};

const BookingWizard: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { t, dir } = useTranslation();
  const { settings } = useAppointments();
  const [step, setStep] = useState(1);
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [availableSlots, setAvailableSlots] = useState<string[]>([]);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    topic: '',
    meetingType: 'online', // online | in_person
    notes: '',
    // Guest fields
    guestName: '',
    guestEmail: '',
    guestPhone: ''
  });

  const currentUser = auth.currentUser;

  // Fetch slots when date changes
  useEffect(() => {
    if (selectedDate) {
      setLoadingSlots(true);
      appointmentStore.getAvailableSlots(selectedDate)
        .then(slots => {
          setAvailableSlots(slots);
          setLoadingSlots(false);
        });
    }
  }, [selectedDate]);

  const handleBook = async () => {
    if (!selectedDate || !selectedTime) return;
    setIsSubmitting(true);
    try {
      await appointmentStore.bookAppointment({
        date: selectedDate,
        time: selectedTime,
        ...formData
      });
      setStep(4); // Success
    } catch (e) {
      alert(e.message);
      setIsSubmitting(false);
    }
  };

  const dates = getDates(settings.maxWindowDays);

  return (
    <div className="fixed inset-0 z-[60] bg-[#020617] flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-white/5 bg-slate-900/50 backdrop-blur-md">
        <button onClick={onClose} className="p-2 -ml-2 text-slate-400 hover:text-white">
          <X size={24} />
        </button>
        <h2 className="text-white font-bold text-lg">{t('appt.book_btn')}</h2>
        <div className="w-8" />
      </div>

      <div className="flex-1 overflow-y-auto p-6 pb-32">

        {/* Progress */}
        <div className="flex justify-center gap-2 mb-8">
          {[1, 2, 3].map(i => (
            <div key={i} className={`h-1.5 w-8 rounded-full transition-colors ${step >= i ? 'bg-primary' : 'bg-slate-800'}`} />
          ))}
        </div>

        {/* Step 1: Date */}
        {step === 1 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-4">
            <h3 className="text-xl font-bold text-white mb-4">{t('appt.step_date')}</h3>
            <div className="grid grid-cols-3 gap-3">
              {dates.map((date) => {
                const dayName = date.toLocaleDateString(dir === 'rtl' ? 'ar-KW' : 'en-US', { weekday: 'short' });
                const dayNum = date.getDate();
                const isSelected = selectedDate?.toDateString() === date.toDateString();
                // Check if enabled in settings
                const dayIndex = date.getDay(); // 0-6
                // Map JS Day 0 (Sun) to our store map keys (0=Sun) - Correct
                const isEnabled = settings.weeklyAvailability[dayIndex]?.enabled;

                return (
                  <button
                    key={date.toISOString()}
                    onClick={() => setSelectedDate(date)}
                    disabled={!isEnabled}
                    className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${
                      isSelected 
                        ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' 
                        : !isEnabled 
                          ? 'bg-slate-900/30 text-slate-600 border-white/5 cursor-not-allowed'
                          : 'bg-slate-800 text-slate-300 border-white/10 hover:bg-slate-700'
                    }`}
                  >
                    <span className="text-xs uppercase opacity-70">{dayName}</span>
                    <span className="text-lg font-bold">{dayNum}</span>
                  </button>
                );
              })}
            </div>
          </motion.div>
        )}

        {/* Step 2: Time */}
        {step === 2 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-4">
            <h3 className="text-xl font-bold text-white mb-2">{t('appt.step_time')}</h3>
            <p className="text-slate-400 text-sm mb-4">
              {selectedDate?.toLocaleDateString(dir === 'rtl' ? 'ar-KW' : 'en-US', { weekday: 'long', month: 'long', day: 'numeric'})}
            </p>

            {loadingSlots ? (
              <div className="flex justify-center py-10">
                <Loader2 className="animate-spin text-primary" size={32} />
              </div>
            ) : availableSlots.length === 0 ? (
              <div className="text-center py-10 text-slate-500 bg-slate-800/30 rounded-xl border border-white/5">
                <Clock size={32} className="mx-auto mb-2 opacity-50" />
                <p>No slots available on this date.</p>
              </div>
            ) : (
              <div className="grid grid-cols-3 gap-3">
                {availableSlots.map(time => (
                  <button
                    key={time}
                    onClick={() => setSelectedTime(time)}
                    className={`py-3 rounded-xl border font-medium text-sm transition-all ${
                      selectedTime === time 
                        ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' 
                        : 'bg-slate-800 text-slate-300 border-white/10 hover:bg-slate-700'
                    }`}
                  >
                    {time}
                  </button>
                ))}
              </div>
            )}
          </motion.div>
        )}

        {/* Step 3: Details */}
        {step === 3 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">
            <h3 className="text-xl font-bold text-white mb-2">{t('appt.step_details')}</h3>

            {/* Guest Fields if not logged in */}
            {!currentUser && (
              <div className="space-y-4 p-4 bg-slate-800/30 rounded-xl border border-white/5">
