};

export default AdminAppointments;

import { useState, useEffect } from 'react';
import { collection, doc, getDoc, setDoc, updateDoc, query, where, getDocs, onSnapshot, serverTimestamp, addDoc, orderBy, limit } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export interface AppointmentSettings {
  durationMin: number;
  dailyLimit: number;
  bufferMin: number;
  minNoticeHours: number;
  maxWindowDays: number;
  // 0=Sun, 1=Mon, ..., 6=Sat
  weeklyAvailability: Record<number, { enabled: boolean; ranges: { start: string; end: string }[] }>;
}

export interface Appointment {
  id: string;
  userId?: string;
  guestName?: string;
  guestEmail?: string;
  guestPhone?: string;
  startAt: number; // ms timestamp
  endAt: number;
  status: 'scheduled' | 'cancelled' | 'completed';
  meetingType: 'online' | 'in_person';
  topic: string;
  notes?: string;
  createdAt: number;
}

const DEFAULT_SETTINGS: AppointmentSettings = {
  durationMin: 30,
  dailyLimit: 10,
  bufferMin: 15,
  minNoticeHours: 2,
  maxWindowDays: 30,
  weeklyAvailability: {
    0: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Sun
    1: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Mon
    2: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Tue
    3: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Wed
    4: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Thu
    5: { enabled: false, ranges: [] }, // Fri
    6: { enabled: false, ranges: [] }, // Sat
  },
};

// Helper: Parse time string (HH:mm or h:mm AM/PM) into {h, m}
const parseTime = (timeStr: string): { h: number, m: number } | null => {
  if (!timeStr) return null;
  try {
    // Check for AM/PM
    const is12Hour = timeStr.match(/([0-9]{1,2}):([0-9]{2})\s*(AM|PM)/i);
    if (is12Hour) {
      let h = parseInt(is12Hour[1], 10);
      const m = parseInt(is12Hour[2], 10);
      const period = is12Hour[3].toUpperCase();
      if (period === 'PM' && h < 12) h += 12;
      if (period === 'AM' && h === 12) h = 0;
      return { h, m };
    }

    // Standard 24h HH:mm
    const parts = timeStr.split(':');
    if (parts.length >= 2) {
      return { h: parseInt(parts[0], 10), m: parseInt(parts[1], 10) };
    }
    return null;
  } catch (e) {
    console.warn("Time parse error:", timeStr);
    return null;
  }
};

class AppointmentStore {
  private settings: AppointmentSettings = DEFAULT_SETTINGS;
  private activeAppointment: Appointment | null = null;
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;
  private isSettingsLoaded = false;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        this.currentUid = user ? user.uid : null;
        if (user) {
          this.subscribeToActiveAppointment();
        } else {
          this.activeAppointment = null;
          this.notify();
        }
      });
    }
    this.fetchSettings();
  }

  // --- Settings Management ---
  async fetchSettings() {
    if (!db) return;
    try {
      const snap = await getDoc(doc(db, 'appointment_settings', 'global'));
      if (snap.exists()) {
        const data = snap.data();

        // Deep Merge & Normalize keys (ensure 0-6 exists)
        const mergedAvailability: any = { ...DEFAULT_SETTINGS.weeklyAvailability };

        if (data.weeklyAvailability) {
          for (let i = 0; i < 7; i++) {
            // Check for numeric key OR string key
            const config = data.weeklyAvailability[i] || data.weeklyAvailability[String(i)];
            if (config) {
              mergedAvailability[i] = config;
            }
          }
        }

        this.settings = { 
          ...DEFAULT_SETTINGS, 
          ...data,
          weeklyAvailability: mergedAvailability
        };

        // LOG A: Verify settings loaded
        console.log("APPOINTMENTS SETTINGS (Normalized):", this.settings.weeklyAvailability);

      } else {
        // Init default if not exists
        await setDoc(doc(db, 'appointment_settings', 'global'), DEFAULT_SETTINGS);
        console.log("Initialized default settings");
      }
      this.isSettingsLoaded = true;
      this.notify();
    } catch (e) {
      console.error("Error fetching settings", e);
    }
  }

  async updateSettings(newSettings: Partial<AppointmentSettings>) {
    if (!db) return;
    try {
      await setDoc(doc(db, 'appointment_settings', 'global'), newSettings, { merge: true });

      // Update local state deeply
      this.settings = { ...this.settings, ...newSettings };
      if (newSettings.weeklyAvailability) {
        this.settings.weeklyAvailability = {
          ...this.settings.weeklyAvailability,
          ...newSettings.weeklyAvailability
        };
      }
      this.notify();
    } catch (e) {
      console.error("Error saving settings:", e);
      throw e;
    }
  }

  getSettings() {
    return this.settings;
  }

  // --- Active Appointment (One per user rule) ---
  private subscribeToActiveAppointment() {
    if (!db || !this.currentUid) return;

    const now = Date.now();
    const q = query(
      collection(db, 'appointments'),
      where('userId', '==', this.currentUid),
      where('status', '==', 'scheduled'),
      where('endAt', '>', now), // Only future appointments
      orderBy('endAt', 'asc'),
      limit(1)
    );

    onSnapshot(q, (snap) => {
      if (!snap.empty) {
        const d = snap.docs[0].data();
        this.activeAppointment = { id: snap.docs[0].id, ...d } as Appointment;
      } else {
        this.activeAppointment = null;
      }
      this.notify();
    });
  }

  getActiveAppointment() {
    return this.activeAppointment;
  }

  // --- Slot Generation ---
  async getAvailableSlots(date: Date): Promise<string[]> {
    if (!db) return [];
    if (!this.isSettingsLoaded) await this.fetchSettings();

    try {
      // Normalize date to start of day (Local time)
      const selectedDate = new Date(date);
      selectedDate.setHours(0, 0, 0, 0);

      const weekday = selectedDate.getDay(); // 0-6 (Sun-Sat)

      // LOG B: Verify requested date and resolution
      console.log(`[DEBUG] Get Slots for ${date.toDateString()} (Weekday: ${weekday})`);

      const wa = this.settings.weeklyAvailability || {};

      // Robust Key Resolution: Try Number 0-6, then String "0"-"6", then assume undefined
      const dayConfig = wa[weekday] ?? wa[String(weekday)];

      if (!dayConfig) {
        console.log(`[DEBUG] No config found for day ${weekday}. Keys available:`, Object.keys(wa));
        return [];
      }

      console.log(`[DEBUG] Day Config Found: Enabled=${dayConfig.enabled}, Ranges=${dayConfig.ranges?.length}`);

      // 1. Basic Check: Is day enabled?
      if (!dayConfig.enabled || !dayConfig.ranges || dayConfig.ranges.length === 0) {
        return [];
      }

      // 2. Fetch existing appointments for this specific day
      const startOfDay = selectedDate.getTime();
      const endOfDay = startOfDay + 86400000; // +24 hours

      const q = query(
        collection(db, 'appointments'),
        where('startAt', '>=', startOfDay),
        where('startAt', '<', endOfDay),
        where('status', '==', 'scheduled')
      );

      let bookedRanges: { start: number; end: number }[] = [];
      try {
        const snap = await getDocs(q);
        bookedRanges = snap.docs.map(d => ({
          start: d.data().startAt,
          end: d.data().endAt
        }));

        // 3. Daily Limit Check
        if (bookedRanges.length >= this.settings.dailyLimit) {
          console.log(`[DEBUG] Daily limit reached (${bookedRanges.length}/${this.settings.dailyLimit})`);
          return []; // Limit reached
        }
      } catch (e) {
        console.error("Error fetching daily bookings:", e);
        return [];
      }

      // 4. Generate Slots
      const slots: string[] = [];

      // SAFETY: Ensure positive duration to prevent infinite loops (min 5 mins)
      const safeDuration = Math.max(5, this.settings.durationMin || 30);
      const durationMs = safeDuration * 60000;

      const bufferMs = (this.settings.bufferMin || 0) * 60000;
      const minNoticeMs = (this.settings.minNoticeHours || 0) * 3600000;
      const nowMs = Date.now();

      // Iterate through defined working ranges
      dayConfig.ranges.forEach((range, idx) => {
        // LOG C: Verify Range
        console.log(`[DEBUG] Range ${idx}: ${range.start} - ${range.end}`);

        const parsedStart = parseTime(range.start);
        const parsedEnd = parseTime(range.end);

        if (!parsedStart || !parsedEnd) {
            console.warn("[DEBUG] Invalid range time format", range);
            return;
        }

        // Create date objects for this range on the selected day
        let currentSlotStart = new Date(selectedDate);
        currentSlotStart.setHours(parsedStart.h, parsedStart.m, 0, 0);

        const rangeEnd = new Date(selectedDate);
        rangeEnd.setHours(parsedEnd.h, parsedEnd.m, 0, 0);

        // Safety break counter for while loop
        let safetyCount = 0;

        // Slot Generation Loop
        while (currentSlotStart.getTime() + durationMs <= rangeEnd.getTime()) {
          // Infinite loop protection
          safetyCount++;
          if (safetyCount > 200) {
            console.warn("[DEBUG] Loop protection triggered");
            break;
          }

          const slotStartMs = currentSlotStart.getTime();
          const slotEndMs = slotStartMs + durationMs;

          // Rule A: Minimum Notice & Past Time Check
          if (slotStartMs < (nowMs + minNoticeMs)) {
            // Move to next slot
            currentSlotStart = new Date(slotEndMs + bufferMs);
            continue;
          }

          // Rule B: Overlap Check
          const isBooked = bookedRanges.some(booking => {
            // Check overlap: (StartA < EndB) and (EndA > StartB)
            return (slotStartMs < booking.end && slotEndMs > booking.start);
          });

          if (!isBooked) {
            slots.push(currentSlotStart.toLocaleTimeString([], { 
              hour: '2-digit', 
              minute: '2-digit', 
              hour12: false // 24h format for simplicity "14:30"
            }));
          }

          // Move to next slot + buffer
          currentSlotStart = new Date(slotEndMs + bufferMs);
        }
      });

      // Deduplicate and Sort
      const uniqueSlots = [...new Set(slots)].sort();
      console.log(`[DEBUG] Generated ${uniqueSlots.length} slots`);
      return uniqueSlots;

    } catch (e) {
      console.error("Critical error generating slots:", e);
      return [];
    }
  }

  // --- Actions ---
  async bookAppointment(data: any) {
    if (!db) throw new Error("DB not connected");

    if (this.currentUid && this.activeAppointment) {
      throw new Error("You already have an active appointment.");
    }

    const { date, time, ...details } = data;

    // Construct Date from time string (HH:mm)
    const [h, m] = time.split(':').map(Number);
    const startAt = new Date(date);
    startAt.setHours(h, m, 0, 0);
    const startAtMs = startAt.getTime();

    const safeDuration = Math.max(5, this.settings.durationMin || 30);
    const durationMs = safeDuration * 60000;
    const endAtMs = startAtMs + durationMs;

    // Double check availability (Race condition mitigation)
    const q = query(
      collection(db, 'appointments'),
      where('startAt', '<', endAtMs),
      where('endAt', '>', startAtMs),
      where('status', '==', 'scheduled')
    );
    const conflicts = await getDocs(q);
    if (!conflicts.empty) {
      throw new Error("This slot was just booked. Please choose another time.");
    }

    const payload = {
      userId: this.currentUid || null,
      guestName: details.guestName || null,
      guestEmail: details.guestEmail || null,
      guestPhone: details.guestPhone || null,
      meetingType: details.meetingType,
      topic: details.topic,
      notes: details.notes || '',
      startAt: startAtMs,
      endAt: endAtMs,
      status: 'scheduled',
      createdAt: serverTimestamp()
    };

    await addDoc(collection(db, 'appointments'), payload);
  }

  async cancelAppointment(id: string) {
    if (!db) return;
    await updateDoc(doc(db, 'appointments', id), { status: 'cancelled' });
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const appointmentStore = new AppointmentStore();

export const useAppointments = () => {
  const [activeAppointment, setActiveAppointment] = useState<Appointment | null>(appointmentStore.getActiveAppointment());
  const [settings, setSettings] = useState<AppointmentSettings>(appointmentStore.getSettings());

  useEffect(() => {
    const update = () => {
      setActiveAppointment(appointmentStore.getActiveAppointment());
      setSettings(appointmentStore.getSettings());
    };

    update();

    return appointmentStore.subscribe(update);
  }, []);

  return { activeAppointment, settings };
};

// @ts-nocheck
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, Settings, Clock, List, Save, CheckCircle, Trash2, X, Plus, Loader2 } from 'lucide-react';
import { appointmentStore, AppointmentSettings, Appointment } from '../../lib/appointmentStore';
import { collection, query, orderBy, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from '../../lib/firebase';

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const AdminAppointments: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'schedule' | 'settings' | 'bookings'>('bookings');
  const [settings, setSettings] = useState<AppointmentSettings | null>(null);
  const [bookings, setBookings] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingId, setSavingId] = useState<number | null>(null); // Track which day is saving

  useEffect(() => {
    // Load Settings
    const loadData = async () => {
      await appointmentStore.fetchSettings();
      setSettings(appointmentStore.getSettings());
    };
    loadData();

    // Subscribe for live updates
    const unsubStore = appointmentStore.subscribe(() => {
      setSettings(appointmentStore.getSettings());
    });

    // Load Bookings Live
    const q = query(collection(db, 'appointments'), orderBy('startAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() } as Appointment));
      setBookings(data);
    });

    return () => {
      unsubscribe();
      unsubStore();
    };
  }, []);

  const handleSaveSettings = async () => {
    if (!settings) return;
    setLoading(true);
    try {
      await appointmentStore.updateSettings(settings);
      alert("Settings saved successfully!");
    } catch (e) {
      alert("Failed to save settings.");
    } finally {
      setLoading(false);
    }
  };

  // Immediate toggle save
  const handleUpdateAvailability = async (dayIndex: number, enabled: boolean) => {
    if (!settings) return;

    // Optimistic Update
    const updatedWeekly = { ...settings.weeklyAvailability };
    // Handle either structure if exists
    const currentConfig = updatedWeekly[dayIndex] || { enabled: false, ranges: [] };

    updatedWeekly[dayIndex] = { ...currentConfig, enabled };

    // Ensure at least one range if enabling
    if (enabled && (!updatedWeekly[dayIndex].ranges || updatedWeekly[dayIndex].ranges.length === 0)) {
       updatedWeekly[dayIndex].ranges = [{ start: "09:00", end: "17:00" }];
    }

    const newSettings = { ...settings, weeklyAvailability: updatedWeekly };
    setSettings(newSettings);

    setSavingId(dayIndex);
    try {
      await appointmentStore.updateSettings({ weeklyAvailability: updatedWeekly });
    } catch (e) {
      console.error("Failed to toggle availability", e);
    } finally {
      setSavingId(null);
    }
  };

  const handleAddRange = (dayIndex: number) => {
    if (!settings) return;
    const newWeekly = { ...settings.weeklyAvailability };
    newWeekly[dayIndex].ranges.push({ start: "09:00", end: "17:00" });
    setSettings({ ...settings, weeklyAvailability: newWeekly });
  };

  const handleRemoveRange = (dayIndex: number, rangeIndex: number) => {
    if (!settings) return;
    const newWeekly = { ...settings.weeklyAvailability };
    newWeekly[dayIndex].ranges = newWeekly[dayIndex].ranges.filter((_, i) => i !== rangeIndex);
    setSettings({ ...settings, weeklyAvailability: newWeekly });
  };

  const handleChangeRange = (dayIndex: number, rangeIndex: number, field: 'start' | 'end', value: string) => {
    if (!settings) return;
    const newWeekly = { ...settings.weeklyAvailability };
    newWeekly[dayIndex].ranges[rangeIndex][field] = value;
    setSettings({ ...settings, weeklyAvailability: newWeekly });
  };

  const handleCancelBooking = async (id: string) => {
    if(window.confirm("Cancel this appointment?")) {
      await updateDoc(doc(db, 'appointments', id), { status: 'cancelled' });
    }
  };

  const handleCompleteBooking = async (id: string) => {
    await updateDoc(doc(db, 'appointments', id), { status: 'completed' });
  };

  if (!settings) return <div className="flex items-center justify-center h-96"><Loader2 className="animate-spin text-white" /></div>;

  return (
    <div className="space-y-8 pb-20">

      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-white">Appointments</h1>
        <p className="text-slate-400 text-sm">Manage availability and view bookings.</p>
      </div>

      {/* Tabs */}
      <div className="flex bg-slate-800/50 p-1 rounded-xl w-fit border border-white/5">
        {[
          { id: 'bookings', label: 'Bookings', icon: List },
          { id: 'schedule', label: 'Availability', icon: Calendar },
          { id: 'settings', label: 'Settings', icon: Settings }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === tab.id 
                ? 'bg-primary text-white shadow-lg' 
                : 'text-slate-400 hover:text-white'
            }`}
          >
            <tab.icon size={16} />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="bg-[#0f172a] border border-white/5 rounded-2xl shadow-xl min-h-[500px]">

        {/* Bookings View */}
        {activeTab === 'bookings' && (
          <div className="p-6">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-xs text-slate-500 uppercase border-b border-white/5">
                    <th className="pb-3 pl-2">Date/Time</th>
                    <th className="pb-3">Customer</th>
                    <th className="pb-3">Topic</th>
                    <th className="pb-3">Status</th>
                    <th className="pb-3 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5 text-sm">
                  {bookings.map(appt => (
                    <tr key={appt.id} className="group hover:bg-white/5 transition-colors">
                      <td className="py-4 pl-2 text-white">
                        <div className="font-medium">{new Date(appt.startAt).toLocaleDateString()}</div>
                        <div className="text-xs text-slate-500">
                          {new Date(appt.startAt).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} - 
                          {new Date(appt.endAt).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                        </div>
                      </td>
                      <td className="py-4 text-slate-300">
                        <div className="font-bold">{appt.guestName || 'User'}</div>
                        <div className="text-xs text-slate-500">{appt.guestEmail || 'No Email'}</div>
                      </td>
                      <td className="py-4 text-slate-300">
                        <div className="truncate max-w-[150px]">{appt.topic}</div>
                        <div className="text-xs text-slate-500 capitalize">{appt.meetingType}</div>
                      </td>
                      <td className="py-4">
                        <span className={`px-2 py-1 rounded text-xs font-bold capitalize ${
                          appt.status === 'scheduled' ? 'bg-blue-500/20 text-blue-400' :
                          appt.status === 'completed' ? 'bg-emerald-500/20 text-emerald-400' :
                          'bg-red-500/20 text-red-400'
                        }`}>
                          {appt.status}
                        </span>
                      </td>
                      <td className="py-4 text-right">
                        {appt.status === 'scheduled' && (
                          <div className="flex justify-end gap-2">
                            <button onClick={() => handleCompleteBooking(appt.id)} className="p-2 hover:bg-emerald-500/20 text-emerald-400 rounded-lg transition-colors" title="Complete">
                              <CheckCircle size={16} />
                            </button>
                            <button onClick={() => handleCancelBooking(appt.id)} className="p-2 hover:bg-red-500/20 text-red-400 rounded-lg transition-colors" title="Cancel">
                              <X size={16} />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                  {bookings.length === 0 && (
                    <tr>
                      <td colSpan={5} className="text-center py-10 text-slate-500">No bookings found.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Schedule View */}
        {activeTab === 'schedule' && (
          <div className="p-6 space-y-6">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-white">Weekly Availability</h3>
              <button onClick={handleSaveSettings} className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 hover:bg-sky-400 transition-colors">
                <Save size={16} /> Save Changes
              </button>
            </div>

            <div className="space-y-4">
              {DAYS.map((dayName, idx) => {
                const dayConfig = settings.weeklyAvailability[idx] || settings.weeklyAvailability[String(idx)] || { enabled: false, ranges: [] };
                const isEnabled = dayConfig.enabled;

                return (
                  <div key={dayName} className={`flex flex-col md:flex-row gap-4 p-4 rounded-xl border transition-all ${isEnabled ? 'bg-slate-900/50 border-white/5' : 'bg-slate-900/20 border-white/5 opacity-70'}`}>

                    {/* Toggle Button Container */}
                    <div className="w-32 flex items-center gap-3">
                      <button 
                        type="button" // IMPORTANT: Prevents form submission
                        onClick={() => handleUpdateAvailability(idx, !isEnabled)}
                        className={`w-12 h-6 rounded-full p-1 transition-colors relative cursor-pointer focus:outline-none focus:ring-2 focus:ring-primary/50 ${isEnabled ? 'bg-primary' : 'bg-slate-700'}`}
                        aria-label={`Toggle ${dayName}`}
                        title={isEnabled ? 'Turn Off' : 'Turn On'}
                      >
                        <div className={`w-4 h-4 bg-white rounded-full transition-transform duration-200 shadow-sm ${isEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
                      </button>

                      <div className="flex flex-col">
                        <span className={`font-bold ${isEnabled ? 'text-white' : 'text-slate-500'}`}>{dayName}</span>
                        {savingId === idx && <span className="text-[10px] text-primary animate-pulse">Saving...</span>}
                      </div>
                    </div>

                    {/* Ranges Section */}
                    <div className="flex-1 space-y-2">
                      {isEnabled ? (
                        <>
                          {dayConfig.ranges.map((range, rIdx) => (
                            <div key={rIdx} className="flex items-center gap-2 flex-wrap">
                              <input 
                                type="time" 
                                value={range.start}
                                onChange={(e) => handleChangeRange(idx, rIdx, 'start', e.target.value)}
                                className="bg-slate-800 text-white px-3 py-2 rounded-lg border border-white/10 focus:border-primary outline-none text-sm"
                              />
                              <span className="text-slate-500">-</span>
                              <input 
                                type="time" 
                                value={range.end}
                                onChange={(e) => handleChangeRange(idx, rIdx, 'end', e.target.value)}
                                className="bg-slate-800 text-white px-3 py-2 rounded-lg border border-white/10 focus:border-primary outline-none text-sm"
                              />
                              <button onClick={() => handleRemoveRange(idx, rIdx)} className="p-2 text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                                <Trash2 size={16} />
                              </button>
                            </div>
                          ))}
                          <button onClick={() => handleAddRange(idx)} className="text-xs text-primary font-bold flex items-center gap-1 mt-2 hover:underline">
                            <Plus size={14} /> Add Range
                          </button>
                        </>
                      ) : (
                        <span className="text-slate-600 text-sm italic flex items-center h-full">Unavailable</span>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Settings View */}
        {activeTab === 'settings' && (
          <div className="p-6 max-w-2xl">
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-400">Duration (Minutes)</label>
                  <input 
                    type="number" 
                    min="5"
                    value={settings.durationMin}
                    onChange={(e) => setSettings({...settings, durationMin: parseInt(e.target.value) || 30})}
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-400">Buffer After Meeting (Minutes)</label>
                  <input 
                    type="number" 
                    value={settings.bufferMin}
                    onChange={(e) => setSettings({...settings, bufferMin: parseInt(e.target.value) || 0})}
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-400">Min Notice (Hours)</label>
                  <input 
                    type="number" 
                    value={settings.minNoticeHours}
                    onChange={(e) => setSettings({...settings, minNoticeHours: parseInt(e.target.value) || 2})}
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-400">Booking Window (Days)</label>
                  <input 
                    type="number" 
                    value={settings.maxWindowDays}
                    onChange={(e) => setSettings({...settings, maxWindowDays: parseInt(e.target.value) || 30})}
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                  />
                </div>
              </div>

              <div className="space-y-2">
                 <label className="text-sm font-bold text-slate-400">Daily Meeting Limit</label>
                 <input 
                    type="number" 
                    value={settings.dailyLimit}
                    onChange={(e) => setSettings({...settings, dailyLimit: parseInt(e.target.value) || 10})}
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                  />
                  <p className="text-xs text-slate-500">Max number of appointments allowed per day.</p>
              </div>

              <div className="pt-6">
                <button onClick={handleSaveSettings} disabled={loading} className="w-full bg-primary text-white font-bold py-3 rounded-xl shadow-lg hover:shadow-primary/20 transition-all disabled:opacity-50">
                  {loading ? 'Saving...' : 'Save Configuration'}
                </button>
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default AdminAppointments;

import { useState, useEffect } from 'react';
import { collection, doc, getDoc, setDoc, updateDoc, query, where, getDocs, onSnapshot, serverTimestamp, addDoc, orderBy, limit } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

export interface AppointmentSettings {
  durationMin: number;
  dailyLimit: number;
  bufferMin: number;
  minNoticeHours: number;
  maxWindowDays: number;
  // 0=Sun, 1=Mon, ..., 6=Sat
  weeklyAvailability: Record<number, { enabled: boolean; ranges: { start: string; end: string }[] }>;
}

export interface Appointment {
  id: string;
  userId?: string;
  guestName?: string;
  guestEmail?: string;
  guestPhone?: string;
  startAt: number; // ms timestamp
  endAt: number;
  status: 'scheduled' | 'cancelled' | 'completed';
  meetingType: 'online' | 'in_person';
  topic: string;
  notes?: string;
  createdAt: number;
}

const DEFAULT_SETTINGS: AppointmentSettings = {
  durationMin: 30,
  dailyLimit: 10,
  bufferMin: 15,
  minNoticeHours: 2,
  maxWindowDays: 30,
  weeklyAvailability: {
    0: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Sun
    1: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Mon
    2: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Tue
    3: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Wed
    4: { enabled: true, ranges: [{ start: "09:00", end: "17:00" }] }, // Thu
    5: { enabled: false, ranges: [] }, // Fri
    6: { enabled: false, ranges: [] }, // Sat
  },
};

// Helper: Parse time string (HH:mm or h:mm AM/PM) into {h, m}
const parseTime = (timeStr: string): { h: number, m: number } | null => {
  if (!timeStr) return null;
  try {
    const trimmed = timeStr.trim();
    // Check for AM/PM
    const is12Hour = trimmed.match(/^([0-9]{1,2}):([0-9]{2})\s*(AM|PM)$/i);
    if (is12Hour) {
      let h = parseInt(is12Hour[1], 10);
      const m = parseInt(is12Hour[2], 10);
      const period = is12Hour[3].toUpperCase();
      if (period === 'PM' && h < 12) h += 12;
      if (period === 'AM' && h === 12) h = 0;
      return { h, m };
    }

    // Standard 24h HH:mm
    const parts = trimmed.split(':');
    if (parts.length >= 2) {
      return { h: parseInt(parts[0], 10), m: parseInt(parts[1], 10) };
    }
    return null;
  } catch (e) {
    console.warn("Time parse error:", timeStr);
    return null;
  }
};

class AppointmentStore {
  private settings: AppointmentSettings = DEFAULT_SETTINGS;
  private activeAppointment: Appointment | null = null;
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;
  private isSettingsLoaded = false;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        this.currentUid = user ? user.uid : null;
        if (user) {
          this.subscribeToActiveAppointment();
        } else {
          this.activeAppointment = null;
          this.notify();
        }
      });
    }
    this.fetchSettings();
  }

  // --- Settings Management ---
  async fetchSettings() {
    if (!db) return;
    try {
      const snap = await getDoc(doc(db, 'appointment_settings', 'global'));
      if (snap.exists()) {
        const data = snap.data();

        // Normalize keys during fetch to ensure local state uses 0-6
        const mergedAvailability = { ...DEFAULT_SETTINGS.weeklyAvailability };
        const incomingAvailability = data.weeklyAvailability || {};

        // Try to map incoming keys to 0-6
        for (let i = 0; i < 7; i++) {
            // Check 0-6 number
            if (incomingAvailability[i]) mergedAvailability[i] = incomingAvailability[i];
            // Check "0"-"6" string
            else if (incomingAvailability[String(i)]) mergedAvailability[i] = incomingAvailability[String(i)];
        }

        this.settings = { 
          ...DEFAULT_SETTINGS, 
          ...data,
          weeklyAvailability: mergedAvailability
        };

        // DEBUG LOG A
        console.log("APPOINTMENTS SETTINGS FROM DB:", JSON.stringify(this.settings, null, 2));

      } else {
        // Init default if not exists
        await setDoc(doc(db, 'appointment_settings', 'global'), DEFAULT_SETTINGS);
        console.log("Initialized default settings");
      }
      this.isSettingsLoaded = true;
      this.notify();
    } catch (e) {
      console.error("Error fetching settings", e);
    }
  }

  async updateSettings(newSettings: Partial<AppointmentSettings>) {
    if (!db) return;
    try {
      await setDoc(doc(db, 'appointment_settings', 'global'), newSettings, { merge: true });

      this.settings = { ...this.settings, ...newSettings };
      if (newSettings.weeklyAvailability) {
        this.settings.weeklyAvailability = {
          ...this.settings.weeklyAvailability,
          ...newSettings.weeklyAvailability
        };
      }
      this.notify();
    } catch (e) {
      console.error("Error saving settings:", e);
      throw e;
    }
  }

  getSettings() {
    return this.settings;
  }

  // --- Active Appointment (One per user rule) ---
  private subscribeToActiveAppointment() {
    if (!db || !this.currentUid) return;

    const now = Date.now();
    const q = query(
      collection(db, 'appointments'),
      where('userId', '==', this.currentUid),
      where('status', '==', 'scheduled'),
      where('endAt', '>', now), // Only future appointments
      orderBy('endAt', 'asc'),
      limit(1)
    );

    onSnapshot(q, (snap) => {
      if (!snap.empty) {
        const d = snap.docs[0].data();
        this.activeAppointment = { id: snap.docs[0].id, ...d } as Appointment;
      } else {
        this.activeAppointment = null;
      }
      this.notify();
    });
  }

  getActiveAppointment() {
    return this.activeAppointment;
  }

  // --- Slot Generation ---
  async getAvailableSlots(date: Date): Promise<string[]> {
    if (!db) return [];
    if (!this.isSettingsLoaded) await this.fetchSettings();

    try {
      // Normalize date to start of day (Local time)
      const selectedDate = new Date(date);
      selectedDate.setHours(0, 0, 0, 0);

      const weekday = selectedDate.getDay(); // 0-6 (Sun-Sat)

      // DEBUG LOG B
      console.log("GET SLOTS FOR DATE:", date.toISOString());
      console.log("WEEKDAY getDay():", weekday);
      console.log("weeklyAvailability keys:", Object.keys(this.settings.weeklyAvailability || {}));

      const wa = this.settings.weeklyAvailability || {};

      // Robust resolution as requested
      let dayConfig = wa[weekday];
      let resolutionMethod = 'number_index';

      if (!dayConfig) {
        dayConfig = wa[String(weekday)];
        resolutionMethod = 'string_index';
      }
      if (!dayConfig) {
         // Fallback for 1-7 indexing? 
         // If getDay() is 0 (Sun), maybe stored as 7 or 1? 
         // Assuming standard 0-6 for now based on DEFAULT_SETTINGS
         console.log("Day config not found for index", weekday);
      }

      console.log(`DAY CONFIG (${resolutionMethod}):`, JSON.stringify(dayConfig, null, 2));

      // 1. Basic Check: Is day enabled?
      if (!dayConfig || !dayConfig.enabled || !dayConfig.ranges || dayConfig.ranges.length === 0) {
        console.log(`Day ${weekday} disabled or empty ranges`);
        return [];
      }

      // 2. Fetch existing appointments
      const startOfDay = selectedDate.getTime();
      const endOfDay = startOfDay + 86400000;

      const q = query(
        collection(db, 'appointments'),
        where('startAt', '>=', startOfDay),
        where('startAt', '<', endOfDay),
        where('status', '==', 'scheduled')
      );

      let bookedRanges: { start: number; end: number }[] = [];
      try {
        const snap = await getDocs(q);
        bookedRanges = snap.docs.map(d => ({
          start: d.data().startAt,
          end: d.data().endAt
        }));

        // 3. Daily Limit Check
        if (bookedRanges.length >= (this.settings.dailyLimit || 10)) {
          console.log("Daily limit reached");
          return [];
        }
      } catch (e) {
        console.error("Error fetching daily bookings:", e);
        return [];
      }

      // 4. Generate Slots
      const slots: string[] = [];

      // Enforce safe duration
      let durationMin = this.settings.durationMin;
      if (!durationMin || durationMin < 5) durationMin = 30;
      const durationMs = durationMin * 60000;

      const bufferMs = (this.settings.bufferMin || 0) * 60000;
      const minNoticeMs = (this.settings.minNoticeHours || 0) * 3600000;
      const nowMs = Date.now();

      dayConfig.ranges.forEach((range, idx) => {
        // DEBUG LOG C
        console.log(`RANGE ${idx}:`, range.start, range.end, "DURATION:", durationMin);

        const parsedStart = parseTime(range.start);
        const parsedEnd = parseTime(range.end);

        if (!parsedStart || !parsedEnd) {
            console.warn("Invalid range time format:", range);
            return;
        }

        let currentSlotStart = new Date(selectedDate);
        currentSlotStart.setHours(parsedStart.h, parsedStart.m, 0, 0);

        const rangeEnd = new Date(selectedDate);
        rangeEnd.setHours(parsedEnd.h, parsedEnd.m, 0, 0);

        let safetyCount = 0;

        while (currentSlotStart.getTime() + durationMs <= rangeEnd.getTime()) {
          safetyCount++;
          if (safetyCount > 200) {
            console.warn("Slot generation overflow protection triggered");
            break;
          }

          const slotStartMs = currentSlotStart.getTime();
          const slotEndMs = slotStartMs + durationMs;

          // Rule A: Minimum Notice & Past Time Check
          if (slotStartMs < (nowMs + minNoticeMs)) {
            currentSlotStart = new Date(slotEndMs + bufferMs);
            continue;
          }

          // Rule B: Overlap Check
          const isBooked = bookedRanges.some(booking => {
            return (slotStartMs < booking.end && slotEndMs > booking.start);
          });

          if (!isBooked) {
            slots.push(currentSlotStart.toLocaleTimeString([], { 
              hour: '2-digit', 
              minute: '2-digit', 
              hour12: false
            }));
          }

          currentSlotStart = new Date(slotEndMs + bufferMs);
        }
      });

      const uniqueSlots = [...new Set(slots)].sort();
      console.log("GENERATED SLOTS:", uniqueSlots);
      return uniqueSlots;

    } catch (e) {
      console.error("Critical error generating slots:", e);
      return [];
    }
  }

  // --- Actions ---
  async bookAppointment(data: any) {
    if (!db) throw new Error("DB not connected");

    if (this.currentUid && this.activeAppointment) {
      throw new Error("You already have an active appointment.");
    }

    const { date, time, ...details } = data;

    const [h, m] = time.split(':').map(Number);
    const startAt = new Date(date);
    startAt.setHours(h, m, 0, 0);
    const startAtMs = startAt.getTime();

    let safeDuration = this.settings.durationMin;
    if (!safeDuration || safeDuration < 5) safeDuration = 30;

    const durationMs = safeDuration * 60000;
    const endAtMs = startAtMs + durationMs;

    // Double check availability (Race condition mitigation)
    const q = query(
      collection(db, 'appointments'),
      where('startAt', '<', endAtMs),
      where('endAt', '>', startAtMs),
      where('status', '==', 'scheduled')
    );
    const conflicts = await getDocs(q);
    if (!conflicts.empty) {
      throw new Error("This slot was just booked. Please choose another time.");
    }

    const payload = {
      userId: this.currentUid || null,
      guestName: details.guestName || null,
      guestEmail: details.guestEmail || null,
      guestPhone: details.guestPhone || null,
      meetingType: details.meetingType,
      topic: details.topic,
      notes: details.notes || '',
      startAt: startAtMs,
      endAt: endAtMs,
      status: 'scheduled',
      createdAt: serverTimestamp()
    };

    await addDoc(collection(db, 'appointments'), payload);
  }

  async cancelAppointment(id: string) {
    if (!db) return;
    await updateDoc(doc(db, 'appointments', id), { status: 'cancelled' });
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const appointmentStore = new AppointmentStore();

export const useAppointments = () => {
  const [activeAppointment, setActiveAppointment] = useState<Appointment | null>(appointmentStore.getActiveAppointment());
  const [settings, setSettings] = useState<AppointmentSettings>(appointmentStore.getSettings());

  useEffect(() => {
    const update = () => {
      setActiveAppointment(appointmentStore.getActiveAppointment());
      setSettings(appointmentStore.getSettings());
    };

    update();

    return appointmentStore.subscribe(update);
  }, []);

  return { activeAppointment, settings };
};

