    return () => {
      isActive = false;
    };
  }, [selectedDate]);

  const handleBook = async () => {
    if (!selectedDate || !selectedTime) return;
    setIsSubmitting(true);
    try {
      await appointmentStore.bookAppointment({
        date: selectedDate,
        time: selectedTime,
        ...formData
      });
