          ))}
        </div>

        {/* Step 1: Date & Time (Unified) */}
        {step === 1 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-8">

            {/* Date Section */}
            <div className="space-y-4">
              <h3 className="text-xl font-bold text-white">{t('appt.step_date')}</h3>
              <div className="grid grid-cols-3 gap-3">
                {dates.map((date) => {
                  const dayName = date.toLocaleDateString(dir === 'rtl' ? 'ar-KW' : 'en-US', { weekday: 'short' });
                  const dayNum = date.getDate();
                  const isSelected = selectedDate?.toDateString() === date.toDateString();
                  // Normalize weekday to 0-6 correctly for settings check
                  const dayIndex = date.getDay();
                  // Check robustly if this day is enabled
                  const wa = settings.weeklyAvailability || {};
                  const dayConfig = wa[dayIndex] ?? wa[String(dayIndex)];
                  const isEnabled = dayConfig?.enabled;

                  return (
