              {t('appt.book_btn')}
            </button>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showWizard && <BookingWizard onClose={() => setShowWizard(false)} />}
      </AnimatePresence>

      <ConfirmModal
        isOpen={showCancel}
        title={t('appt.cancel_btn')}
        message={t('appt.cancel_confirm')}
        confirmText="Yes, Cancel"
        isDestructive={true}
        onConfirm={handleCancel}
        onCancel={() => setShowCancel(false)}
      />
    </motion.div>
  );
};

