// @ts-nocheck
import React, { useEffect, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { CheckCircle, AlertTriangle, Loader2 } from 'lucide-react';
import { leadStore } from '../lib/leadStore';
import Signup from './Signup'; // Reuse signup form, but modify behavior slightly via context or props? 
// Better: Duplicate simple signup form here OR reuse Signup logic. 
// Since we need to call `leadStore.claimProject` after auth, we'll wrap the standard auth flow.
// Actually, `Signup` page creates user and then navigates away. 
// We need to Intercept that.
// Let's implement a specific Signup form for claiming here to ensure the sequence is correct.

import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { useTranslation } from '../lib/i18nContext';
import PhoneInput from '../components/PhoneInput';
import { User, Mail, Lock, Phone as PhoneIcon } from 'lucide-react';

const ClaimProject: React.FC = () => {
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');
  const navigate = useNavigate();
  const { t } = useTranslation();

  const [status, setStatus] = useState<'validating' | 'valid' | 'invalid' | 'claiming' | 'success'>('validating');
  const [errorMsg, setErrorMsg] = useState('');
  const [leadId, setLeadId] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: ''
  });

  useEffect(() => {
    if (!token) {
        setStatus('invalid');
        setErrorMsg("Missing token.");
        return;
    }

    leadStore.validateToken(token).then(res => {
        if (res.valid && res.leadId) {
            setLeadId(res.leadId);
            setStatus('valid');
        } else {
            setStatus('invalid');
            setErrorMsg(res.error || "Token invalid.");
        }
    });
  }, [token]);

  const handleClaim = async (e: React.FormEvent) => {
    e.preventDefault();
    if (status !== 'valid' || !token || !leadId) return;

    setStatus('claiming');
    try {
        // 1. Create Auth
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;
        await updateProfile(user, { displayName: `${formData.firstName} ${formData.lastName}` });

        // 2. Create User Doc
        if (db) {
            await setDoc(doc(db, 'users', user.uid), {
              id: user.uid,
              firstName: formData.firstName,
              lastName: formData.lastName,
              email: formData.email,
              phone: formData.phone,
              role: 'Customer',
              status: 'Active',
              createdAt: serverTimestamp(),
              registeredAt: serverTimestamp(),
              lastLoginAt: serverTimestamp(),
              migrationDone: true 
            });
        }

        // 3. Claim Project
        await leadStore.claimProject(token, leadId);

        setStatus('success');
        setTimeout(() => {
            navigate('/home');
        }, 2000);

    } catch (err: any) {
        console.error(err);
        alert("Error: " + err.message);
        setStatus('valid'); // Revert to allow retry
    }
  };

  if (status === 'validating') {
      return (
          <div className="h-screen flex items-center justify-center bg-[#020617] text-white">
              <Loader2 className="animate-spin text-primary" size={40} />
          </div>
      );
  }

  if (status === 'invalid') {
      return (
        <div className="h-screen flex items-center justify-center bg-[#020617] text-white p-6 text-center">
            <div className="bg-red-500/10 border border-red-500/20 p-8 rounded-3xl max-w-sm">
                <AlertTriangle size={40} className="text-red-500 mx-auto mb-4" />
                <h1 className="text-xl font-bold mb-2">Invalid Link</h1>
                <p className="text-slate-400 text-sm">{errorMsg}</p>
                <button onClick={() => navigate('/')} className="mt-6 text-sm text-white underline">Go Home</button>
            </div>
        </div>
      );
  }

  if (status === 'success') {
      return (
        <div className="h-screen flex items-center justify-center bg-[#020617] text-white p-6 text-center">
            <div className="bg-emerald-500/10 border border-emerald-500/20 p-8 rounded-3xl max-w-sm">
