import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight, Check, X, Smartphone, Globe, CreditCard, Store, ShoppingBag, Zap, Palette, User, Mail, Phone, Lock, Briefcase, Loader2, Send } from 'lucide-react';
import { userProjectsStore } from '../lib/userProjectsStore';
import { leadStore } from '../lib/leadStore'; // Import leadStore
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { auth } from '../lib/firebase';
import { useTranslation } from '../lib/i18nContext';
