          className="flex-1 bg-slate-800/50 border border-slate-700/50 border-s-0 rounded-e-xl py-3 px-3 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary transition-all font-mono text-left"
          required={required}
        />
      </div>

      {/* Dropdown - Anchored to start (Right in RTL, Left in LTR) using 'start-0' */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 5 }}
            className="absolute top-full start-0 mt-2 w-64 max-h-60 overflow-y-auto bg-[#0f172a] border border-white/10 rounded-xl shadow-2xl z-50 custom-scrollbar"
          >
            {COUNTRIES.map((c) => (
              <button
                key={c.code}
                type="button"
                onClick={() => handleCountrySelect(c)}
                className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-white/5 transition-colors text-start border-b border-white/5 last:border-0 ${
                  selectedCountry.code === c.code ? 'bg-primary/10' : ''
                }`}
              >
                <span className="text-xl shrink-0">{c.flag}</span>
                <div className="flex-1">
                  <div className="text-sm text-white font-medium">{c.name}</div>
                  {/* Ensure dial code in dropdown is also LTR to avoid "965+" */}
                  <div className="text-xs text-slate-500 text-left" dir="ltr">{c.dial_code}</div>
                </div>
                {selectedCountry.code === c.code && <Check size={16} className="text-primary" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

