// @ts-nocheck
import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, Mail, Phone, Save, Shield, CheckCircle, Loader2, Key, Lock } from 'lucide-react';
import { updateProfile, onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, updateDoc } from 'firebase/firestore';
import { auth, db } from '../../lib/firebase';
import AvatarInitial from '../../components/AvatarInitial';

const AdminAccount: React.FC = () => {
  const [user, setUser] = useState(auth.currentUser);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(false);

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    phone: '',
    role: '',
    email: ''
  });

  // 1. Ensure we catch Auth updates. 
  // Without this, if auth.currentUser is null on mount, the page stays loading forever.
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      if (!currentUser) {
        setIsLoading(false); // Stop loading if not logged in (ProtectedRoute will handle redirect)
      }
    });
    return () => unsubscribe();
  }, []);

  // 2. Fetch Data when User is available
  useEffect(() => {
    const fetchAdminData = async () => {
      if (!user) return; // Wait for auth

      try {
        const docRef = doc(db, 'admins', user.uid);
        const snap = await getDoc(docRef);

        if (snap.exists()) {
          const data = snap.data();
          const nameParts = (data.name || '').split(' ');
          const firstName = nameParts[0] || '';
          const lastName = nameParts.slice(1).join(' ') || '';

          setFormData({
            firstName,
            lastName,
            phone: data.phone || '',
            role: data.role || 'Admin',
            email: data.email || user.email || ''
          });
        } else {
          // Fallback if no firestore doc exists yet
          const nameParts = (user.displayName || '').split(' ');
          setFormData({
            firstName: nameParts[0] || '',
            lastName: nameParts.slice(1).join(' ') || '',
            phone: '',
            role: 'Admin',
            email: user.email || ''
          });
        }
      } catch (err) {
        console.error("Error loading profile", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAdminData();
  }, [user]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsSaving(true);
    setSuccess(false);

    try {
      const fullName = `${formData.firstName} ${formData.lastName}`.trim();

      // 1. Update Auth Profile
      await updateProfile(user, {
        displayName: fullName
      });

      // 2. Update Firestore
      const docRef = doc(db, 'admins', user.uid);
      await updateDoc(docRef, {
        name: fullName,
        phone: formData.phone
      });

      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      console.error("Save failed", err);
      alert("Failed to update profile.");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full text-slate-500 min-h-[50vh]">
        <Loader2 className="animate-spin mr-2" /> Loading profile...
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto space-y-8 pb-20">

      {/* Header */}
      <div>
