                {language === 'en' ? 'عربي' : 'English'}
              </button>
            ) : (
              <div className="w-10" />
            )}
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 relative overflow-hidden">
          <AnimatePresence initial={false} custom={direction}>
            <motion.div
              key={step}
              custom={direction}
              initial={{ x: direction > 0 ? (dir === 'rtl' ? -300 : 300) : (dir === 'rtl' ? 300 : -300), opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: direction > 0 ? (dir === 'rtl' ? 300 : -300) : (dir === 'rtl' ? -300 : 300), opacity: 0 }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="absolute inset-0 w-full h-full"
            >
              {renderStep()}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Footer / Controls */}
        <div className={`p-6 pb-28 border-t border-white/5 bg-[#0f172a] z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.2)] transition-all duration-300 ${step !== 0 && nextButtonHidden ? 'opacity-0 pointer-events-none absolute bottom-0 w-full' : 'opacity-100'}`}>

          {/* Error Message */}
          {errors.length > 0 && (
            <motion.div 
              initial={{ opacity: 0, y: 10 }} 
              animate={{ opacity: 1, y: 0 }}
              className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-medium text-center"
            >
              {errors[0]}
            </motion.div>
          )}

          {step === 0 ? null : (
            <button 
              onClick={step === 12 ? handleCreate : nextStep}
              disabled={isLoading}
              className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center space-x-2 rtl:space-x-reverse disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                 <Loader2 size={24} className="animate-spin" />
              ) : (
                <>
                   <span>{step === 12 ? (isLeadMode ? 'Submit Request' : (isAuthenticated ? t('wizard.create_btn') : t('wizard.create_account_project'))) : step === 11 ? (isLeadMode ? 'Review' : t('wizard.create_account_only')) : t('wizard.next')}</span>
                   {step !== 12 && (dir === 'rtl' ? <ChevronLeft size={20} /> : <ChevronRight size={20} />)}
                </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

