interface AuthRequiredModalProps {
  isOpen: boolean;
  onClose: () => void;
  redirectTo?: string; // Optional: where to go after login
}

const AuthRequiredModal: React.FC<AuthRequiredModalProps> = ({ isOpen, onClose, redirectTo }) => {
  const navigate = useNavigate();
  const { t, dir } = useTranslation();

  const handleAction = (path: string) => {
    // If a specific redirect path is provided, save it. 
    // If not, we might be already on the intended path (guarded route), or just clicking a button.
    // Ideally the guard sets the path before opening the modal, but we can double check.
    if (redirectTo) {
        guestStore.setIntendedPath(redirectTo);
    }
    navigate(path);
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm"
