            <Route path="/more/terms" element={<MoreTerms />} />
            <Route path="/more/privacy" element={<MorePrivacy />} />

            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </AnimatePresence>
      </ErrorBoundary>

      {/* Persistent Bottom Navigation */}
      {showBottomNav && <BottomNav />}
    </MobileShell>
  );
};

// --- Secure Admin Route Protection ---
const ProtectedAdminRoute = ({ children }: { children: React.ReactNode }) => {
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        // Check admins/{uid}
        try {
          const snap = await getDoc(doc(db, 'admins', user.uid));
          if (snap.exists() && snap.data().status === 'Active') {
            setIsAdmin(true);
          } else {
            setIsAdmin(false);
          }
        } catch (e) {
          console.error("Admin check failed", e);
          setIsAdmin(false);
        }
      } else {
        setIsAdmin(false);
      }
    });
    return () => unsubscribe();
  }, []);

  if (isAdmin === null) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#020617] text-white">
        Loading...
      </div>
    );
  }

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return <>{children}</>;
};

// Global Auth & Redirect Handler
const AuthRedirectHandler = () => {
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (auth) {
      const unsubscribe = onAuthStateChanged(auth, (user) => {
        if (user) {
          // User Logged In
          guestStore.setGuest(false); // Clear guest status

          // Redirect to intended path if exists
          const intended = guestStore.intendedPath;
          if (intended) {
            guestStore.setIntendedPath(null);
            navigate(intended);
          } else if (location.pathname === '/login' || location.pathname === '/signup') {
            // Default after login
            navigate('/home');
          }
        } else {
          // User Logged Out (or not logged in)
          // If not guest and accessing protected, Router handles it.
          // Just ensure guest flag is respected or cleared if explicit logout?
          // Explicit logout handles guestStore.setGuest(false) usually.
        }
      });
      return () => unsubscribe();
    }
  }, [navigate, location]);

  return null;
}

const App: React.FC = () => {
  return (
    <HashRouter>
      <I18nProvider>
        <AuthGuardProvider>
          <AuthRedirectHandler />
          <Routes>
            {/* Admin Routes - Full Screen, No MobileShell */}
            <Route path="/admin/login" element={<AdminLogin />} />

            <Route path="/admin/*" element={
              <ProtectedAdminRoute>
                <AdminLayout>
                  <Routes>
                    <Route path="projects" element={<AdminProjects />} />
                    <Route path="user-projects" element={<AdminUserProjects />} />
                    <Route path="live-chat" element={<AdminLiveChat />} />
                    <Route path="users" element={<AdminUsers />} />
                    <Route path="employees" element={<AdminEmployees />} />
                    <Route path="roles" element={<AdminRoles />} />
                    <Route path="account" element={<AdminAccount />} />
                    <Route path="appointments" element={<AdminAppointments />} />
                    <Route path="leads" element={<AdminLeads />} /> {/* New */}

                    {/* Default admin route */}
                    <Route path="*" element={<Navigate to="/admin/leads" replace />} />
                  </Routes>
                </AdminLayout>
              </ProtectedAdminRoute>
            } />

            {/* Main App Routes - Wrapped in MobileShell */}
            <Route path="/*" element={<MobileAppLayout />} />
          </Routes>
        </AuthGuardProvider>
      </I18nProvider>
    </HashRouter>
  );
};

