import { useAuthGuard } from '../lib/authGuardContext';

const BottomNav: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { unreadCount } = useNotifications();
  const { t } = useTranslation();
  const { requireAuth } = useAuthGuard();

  const tabs = [
    { id: 'home', icon: Home, label: t('home.my_apps'), path: '/home', protected: false },
    { id: 'support', icon: MessageCircle, label: t('status.support'), path: '/support', protected: true },
    { id: 'appointments', icon: Calendar, label: t('appt.title'), path: '/appointments', protected: true },
    { id: 'notifications', icon: Bell, label: t('notif.title'), path: '/notifications', badge: unreadCount, protected: true },
    { id: 'more', icon: MoreHorizontal, label: t('more.title'), path: '/more', protected: false },
  ];

  const handleNav = (path: string, isProtected: boolean) => {
    if (isProtected) {
      requireAuth(() => navigate(path));
    } else {
      navigate(path);
    }
  };

  return (
    <div className="fixed bottom-0 left-0 right-0 max-w-[430px] mx-auto z-50 px-2 pb-2">
      <div className="glass-panel rounded-2xl h-16 flex items-center justify-around px-1 shadow-lg shadow-black/40">
        {tabs.map((tab) => {
          const isActive = location.pathname === tab.path;
          const Icon = tab.icon;
          const showBadge = tab.id === 'notifications' && (tab.badge || 0) > 0;

          return (
            <button
              key={tab.id}
              onClick={() => handleNav(tab.path, tab.protected)}
              aria-label={tab.label}
              className="flex items-center justify-center w-12 h-12 relative"
            >
              {isActive && (
                <motion.div
                  layoutId="activeTab"
                  className="absolute inset-0 bg-primary/10 rounded-xl"
                  initial={false}
                  transition={{ type: "spring", stiffness: 500, damping: 30 }}
                />
              )}

              <div className="relative">
                <Icon
                  size={24}
                  className={`transition-all duration-300 ${
                    isActive 
                      ? 'text-primary drop-shadow-[0_0_8px_rgba(29,183,240,0.6)] scale-110' 
                      : 'text-slate-400 hover:text-slate-300'
                  }`}
                />

                <AnimatePresence>
                  {showBadge && (
                    <motion.div
                      initial={{ scale: 0 }}
                      animate={{ scale: 1 }}
                      exit={{ scale: 0 }}
                      className="absolute -top-1.5 -right-1.5 rtl:-left-1.5 rtl:right-auto w-5 h-5 bg-red-500 rounded-full flex items-center justify-center border-2 border-[#0f172a]"
                    >
                      <span className="text-[10px] font-bold text-white">
                        {tab.badge && tab.badge > 9 ? '9+' : tab.badge}
                      </span>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

