import { APP_NAME } from './constants';

// Reusing the sound from Admin Dashboard for consistency
// Ideally this file should be downloaded to /public/sounds/notification.mp3 for offline support
const SOUND_URL = "https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3";

export const requestNotificationPermission = async () => {
  if (!("Notification" in window)) return;

  if (Notification.permission === "default") {
    try {
      await Notification.requestPermission();
    } catch (e) {
      console.warn("Notification permission request failed", e);
    }
  }
};

export const playMessageSound = () => {
  try {
    const audio = new Audio(SOUND_URL);
    audio.volume = 0.6;
    // User interaction is usually required for audio. 
    // In a chat context, the user has likely interacted with the app recently.
    audio.play().catch(e => {
      console.warn("Audio play blocked (user gesture required or background restricted)", e);
    });
  } catch (e) {
    console.error("Sound playback error", e);
  }
};

export const showMessageNotification = (senderName: string, text: string) => {
  if (!("Notification" in window)) return;

  if (Notification.permission === "granted") {
    // Truncate body if too long (max ~80 chars requested)
    const body = text.length > 80 ? text.substring(0, 80) + "..." : (text || "You have a new message");

    try {
      const notification = new Notification(senderName || APP_NAME, {
        body: body,
        icon: "https://raiyansoft.com/wp-content/uploads/2024/05/cropped-App-Icon-1.png",
        tag: 'chat-message', // Prevents duplicate stacking
        // @ts-ignore
        silent: true // We play our own sound via Audio API for consistent behavior in foreground
      });

      // Close automatically after 5 seconds
      setTimeout(() => notification.close(), 5000);

      notification.onclick = () => {
        window.focus();
        notification.close();
        // Navigation logic could go here if using a router outside react context
        window.location.hash = '#/support';
      };
    } catch (e) {
      console.error("Notification creation error", e);
    }
  }
};

import { useEffect, useState } from 'react';
import { collection, addDoc, query, onSnapshot, serverTimestamp, orderBy, setDoc, doc, increment } from 'firebase/firestore';
import { db, auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { playMessageSound, showMessageNotification } from './chatNotifications';

export interface Message {
  id: string;
  text: string;
  sender: 'customer' | 'staff';
  createdAt: number;
  senderName?: string;
}

class ChatStore {
  private messages: Message[] = [];
  private listeners: (() => void)[] = [];
  private currentUid: string | null = null;
  private unsubscribe: (() => void) | null = null;
  private isFirstLoad = true;

  constructor() {
    if (auth) {
      onAuthStateChanged(auth, (user) => {
        if (user) {
          this.subscribeToFirestore(user.uid);
        } else {
          this.messages = [];
          this.currentUid = null;
          if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
          }
          this.notify();
        }
      });
    }
  }

  private subscribeToFirestore(uid: string) {
    if (this.currentUid === uid) return;
    this.currentUid = uid;
    this.isFirstLoad = true; // Reset flag on new subscription

    if (this.unsubscribe) this.unsubscribe();
    if (!db) return;

    // Listen to subcollection: conversations/{uid}/messages
    const q = query(
      collection(db, 'conversations', uid, 'messages'),
      orderBy('createdAt', 'asc')
    );

    this.unsubscribe = onSnapshot(q, (snapshot) => {
      // Detect new messages for notification
      if (!this.isFirstLoad) {
        snapshot.docChanges().forEach((change) => {
          if (change.type === 'added') {
            const data = change.doc.data();
            // Trigger only for messages from STAFF (incoming)
            if (data.sender === 'staff') {
              playMessageSound();
              showMessageNotification(data.senderName || 'Support', data.text);
            }
          }
        });
      }

      this.messages = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          text: data.text,
          sender: data.sender,
          senderName: data.senderName,
          // Handle Timestamp or millis
          createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : Date.now()
        } as Message;
      });

      this.isFirstLoad = false;
      this.notify();
    });
  }

  private notify() {
    this.listeners.forEach(l => l());
  }

  subscribe(listener: () => void) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  getMessages() {
    return [...this.messages];
  }

  async sendMessage(text: string) {
    if (!this.currentUid || !db) return;

    const user = auth.currentUser;
    const conversationId = this.currentUid;

    try {
      const timestamp = serverTimestamp();

      // 1. Add Message to Subcollection
      await addDoc(collection(db, 'conversations', conversationId, 'messages'), {
        text,
        sender: 'customer',
        senderName: user?.displayName || 'Customer',
        createdAt: timestamp
      });

      // 2. Update Parent Conversation Document
      // Uses atomic increment for unread count to prevent race conditions
      await setDoc(doc(db, 'conversations', conversationId), {
        customerId: conversationId,
        customerName: user?.displayName || 'Anonymous',
        status: 'open',
        lastMessageText: text,
        lastMessageAt: timestamp,
        lastMessageSender: 'customer',
        unreadForAdmin: increment(1)
      }, { merge: true });

    } catch (e) {
      console.error("Error sending message", e);
    }
  }
}

export const chatStore = new ChatStore();

export const useMessages = () => {
  const [messages, setMessages] = useState<Message[]>(chatStore.getMessages());

  useEffect(() => {
    const update = () => {
      setMessages(chatStore.getMessages());
    };

    update();
    return chatStore.subscribe(update);
  }, []);

  return { messages };
};

