                <label className="text-xs font-bold text-slate-400 uppercase block mb-2">{t('wizard.step_payments')}</label>
                <div className="flex rounded-lg overflow-hidden border border-white/10">
                   <button onClick={() => setFormData({...formData, hasPayments: true})} className={`flex-1 py-2 text-xs font-medium transition-colors ${formData.hasPayments ? 'bg-primary text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}>{t('wizard.yes')}</button>
                   <div className="w-px bg-white/10"></div>
                   <button onClick={() => setFormData({...formData, hasPayments: false})} className={`flex-1 py-2 text-xs font-medium transition-colors ${!formData.hasPayments ? 'bg-slate-700 text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}>{t('wizard.no')}</button>
                </div>
             </div>
             <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-2">{t('wizard.step_existing_biz')}</label>
                <div className="flex rounded-lg overflow-hidden border border-white/10">
                   <button onClick={() => setFormData({...formData, hasExistingBusiness: true})} className={`flex-1 py-2 text-xs font-medium transition-colors ${formData.hasExistingBusiness ? 'bg-primary text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}>{t('wizard.yes')}</button>
                   <div className="w-px bg-white/10"></div>
                   <button onClick={() => setFormData({...formData, hasExistingBusiness: false})} className={`flex-1 py-2 text-xs font-medium transition-colors ${!formData.hasExistingBusiness ? 'bg-slate-700 text-white' : 'bg-slate-900 text-slate-400 hover:bg-slate-800'}`}>{t('wizard.no')}</button>
                </div>
             </div>
          </div>
        </div>

        {/* Branding */}
        <div className="bg-slate-800/30 p-4 rounded-2xl border border-white/5 space-y-4">
          <h3 className="text-sm font-bold text-white border-b border-white/5 pb-2">{t('wizard.branding')}</h3>
          <div className="space-y-1">
             <label className="text-xs font-bold text-slate-400 uppercase">{t('wizard.step_color')}</label>
             <div className="flex gap-3 items-center">
                <input type="color" value={formData.brandColor} onChange={e => setFormData({...formData, brandColor: e.target.value})} className="h-10 w-14 rounded-lg cursor-pointer bg-transparent border border-white/10 p-0.5" />
                <input type="text" value={formData.brandColor} onChange={e => setFormData({...formData, brandColor: e.target.value})} className="flex-1 bg-slate-900 border border-white/10 rounded-lg px-3 py-2 text-white focus:border-primary focus:outline-none uppercase font-mono transition-colors" />
             </div>
             <div className="flex gap-2 mt-2 overflow-x-auto no-scrollbar pt-1">
               {PRESET_COLORS.map(c => (
                 <button key={c.hex} onClick={() => setFormData({...formData, brandColor: c.hex})} className={`w-6 h-6 rounded-full border border-white/10 shrink-0 ${formData.brandColor.toLowerCase() === c.hex.toLowerCase() ? 'ring-2 ring-primary ring-offset-1 ring-offset-slate-900' : ''}`} style={{ backgroundColor: c.hex }} />
               ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );

  // Main Render Switch
  const renderStep = () => {
    switch (step) {
      case 0: return renderIntro();
      case 1: return renderSingleSelectAuto(t('wizard.step_platforms'), PLATFORMS, formData.platforms, 'platforms', 'platform');
      case 2: return renderSingleSelectAuto(t('wizard.step_languages'), LANGUAGES, formData.languages, 'languages', 'lang');
      case 3: return renderSingleSelectAuto(t('wizard.step_markets'), MARKETS, formData.markets, 'markets', 'market');
      case 4: return renderIndustryStep();
      case 5: return renderSingleChoiceAuto(t('wizard.step_payments'), [{label:t('wizard.yes'), value: true}, {label: t('wizard.no'), value: false}], formData.hasPayments, 'hasPayments', true);
      case 6: return renderSingleChoiceAuto(t('wizard.step_existing_biz'), [{label:t('wizard.yes'), value: true}, {label: t('wizard.no'), value: false}], formData.hasExistingBusiness, 'hasExistingBusiness', true);
      case 7: return renderSingleChoiceAuto(t('wizard.step_service'), SERVICE_MODELS, formData.serviceModel, 'serviceModel', false, 'service');
      case 8: return renderSingleChoiceAuto(t('wizard.step_ref'), CLOSEST_APPS, formData.closestApp, 'closestApp');
      case 9: return renderTextInput(t('wizard.step_name'), formData.name, 'name', 'wizard.name_placeholder');
      case 10: return renderColorPicker();
      case 11: return renderSignupOrContact();
      case 12: return renderReview();
      default: return null;
    }
  };

  const nextButtonHidden = isNextHidden();

  return (
    <div className="fixed inset-0 z-50 flex justify-center items-start md:items-center bg-[#020617] md:bg-black/60 md:backdrop-blur-sm" dir={dir}>
      {/* Mobile-width Container */}
      <div className="w-full max-w-[430px] h-full bg-[#020617] flex flex-col relative shadow-2xl overflow-hidden md:border md:border-white/5">

        {/* Header */}
        <div className="px-6 py-4 flex items-center justify-between border-b border-white/5 bg-[#0f172a]">
          <button onClick={step === 0 ? onClose : prevStep} className="p-2 -ml-2 text-slate-400 hover:text-white transition-colors">
            {step === 0 ? <X size={24} /> : (dir === 'rtl' ? <ChevronRight size={24} /> : <ChevronLeft size={24} />)}
          </button>
          <div className="flex space-x-1.5 rtl:space-x-reverse">
            {Array.from({ length: isAuthenticated && !isLeadMode ? 12 : 13 }).map((_, i) => (
               <div 
                 key={i} 
                 className={`h-1.5 rounded-full transition-all duration-300 ${i === step ? 'w-6 bg-primary' : i < step ? 'w-1.5 bg-primary/50' : 'w-1.5 bg-slate-800'}`}
               />
            ))}
          </div>
          {/* Language Toggle or Spacer */}
          <div className="min-w-[40px] flex justify-end">
            {isLeadMode ? (
              <button
                onClick={() => setLanguage(language === 'en' ? 'ar' : 'en')}
                className="text-xs font-bold text-primary hover:text-white transition-colors border border-primary/30 rounded-lg px-3 py-1.5 bg-primary/10"
              >
                {language === 'en' ? 'عربي' : 'English'}
              </button>
            ) : (
              <div className="w-10" />
            )}
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 relative overflow-hidden">
          <AnimatePresence initial={false} custom={direction}>
            <motion.div
              key={step}
              custom={direction}
              initial={{ x: direction > 0 ? (dir === 'rtl' ? -300 : 300) : (dir === 'rtl' ? 300 : -300), opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: direction > 0 ? (dir === 'rtl' ? 300 : -300) : (dir === 'rtl' ? -300 : 300), opacity: 0 }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className="absolute inset-0 w-full h-full"
            >
              {renderStep()}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Footer / Controls */}
        <div className={`p-6 pb-28 border-t border-white/5 bg-[#0f172a] z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.2)] transition-all duration-300 ${step !== 0 && nextButtonHidden ? 'opacity-0 pointer-events-none absolute bottom-0 w-full' : 'opacity-100'}`}>

          {/* Error Message */}
          {errors.length > 0 && (
            <motion.div 
              initial={{ opacity: 0, y: 10 }} 
              animate={{ opacity: 1, y: 0 }}
              className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-medium text-center"
            >
              {errors[0]}
            </motion.div>
          )}

          {step === 0 ? null : (
            <button 
              onClick={step === 12 ? handleCreate : nextStep}
              disabled={isLoading}
              className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center space-x-2 rtl:space-x-reverse disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                 <Loader2 size={24} className="animate-spin" />
              ) : (
                <>
                   <span>{step === 12 ? (isLeadMode ? t('lead_contact.submit_btn') : (isAuthenticated ? t('wizard.create_btn') : t('wizard.create_account_project'))) : step === 11 ? (isLeadMode ? t('lead_contact.review_btn') : t('wizard.create_account_only')) : t('wizard.next')}</span>
                   {step !== 12 && (dir === 'rtl' ? <ChevronLeft size={20} /> : <ChevronRight size={20} />)}
                </>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProjectWizard;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  X, ChevronRight, ChevronLeft, CheckCircle2, 
  MousePointerClick, Edit3, Lightbulb, Layers, Map,
  Smartphone, Monitor, Globe, ShoppingCart, 
  Briefcase, GraduationCap, Utensils, Stethoscope, 
  Truck, HelpCircle, Loader2
} from 'lucide-react';
import { useTranslation } from '../lib/i18nContext';
import { auth } from '../lib/firebase';
import { userProjectsStore } from '../lib/userProjectsStore';
import { leadStore } from '../lib/leadStore';
import PhoneInput from './PhoneInput';

interface ProjectWizardProps {
  onClose: () => void;
  onComplete: () => void;
  isLeadMode?: boolean;
  source?: string;
}

const INDUSTRIES = [
  { id: 'Food & Delivery', icon: Utensils, label: 'Food & Delivery' },
  { id: 'E-Commerce', icon: ShoppingCart, label: 'E-Commerce' },
  { id: 'Healthcare', icon: Stethoscope, label: 'Healthcare' },
  { id: 'Education', icon: GraduationCap, label: 'Education' },
  { id: 'Logistics', icon: Truck, label: 'Logistics' },
  { id: 'Business', icon: Briefcase, label: 'Business' },
  { id: 'Other', icon: HelpCircle, label: 'Other' },
];

const PLATFORMS = [
  { id: 'Mobile App', icon: Smartphone, label: 'wizard.mobile' },
  { id: 'Web Platform', icon: Monitor, label: 'wizard.web' },
  { id: 'Website', icon: Globe, label: 'wizard.web' },
];

const ProjectWizard: React.FC<ProjectWizardProps> = ({ onClose, onComplete, isLeadMode = false, source = 'app' }) => {
  const { t, dir } = useTranslation();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const user = auth.currentUser;

  const [formData, setFormData] = useState({
    industry: '',
    name: '',
    description: '',
    platforms: [] as string[],
    contactName: user?.displayName || '',
    contactPhone: '',
    contactEmail: user?.email || '',
  });

  const handleNext = () => {
    if (step < 3) setStep(step + 1);
  };

  const handleBack = () => {
    if (step > 1) setStep(step - 1);
  };

  const togglePlatform = (id: string) => {
    setFormData(prev => ({
      ...prev,
      platforms: prev.platforms.includes(id)
        ? prev.platforms.filter(p => p !== id)
        : [...prev.platforms, id]
    }));
  };

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const payload = {
        name: formData.name,
        description: formData.description,
        industry: formData.industry,
        platforms: formData.platforms,
        status: 'pricing', // Default status for new project
      };

      if (isLeadMode || !user) {
        // Guest / Lead Mode
        await leadStore.submitLead({
          name: formData.contactName,
          phone: formData.contactPhone,
          email: formData.contactEmail,
          projectPayload: payload,
          source
        });
      } else {
        // Authenticated User Mode
        await userProjectsStore.addProject(payload);
      }

      onComplete();
    } catch (error) {
      console.error("Submission failed", error);
      alert("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const isStep1Valid = !!formData.industry;
  const isStep2Valid = !!formData.name && !!formData.description && formData.platforms.length > 0;
  const isStep3Valid = isLeadMode || !user 
    ? (!!formData.contactName && !!formData.contactPhone) 
    : true; // Logged in users are auto-valid

  return (
    <div className="fixed inset-0 z-[60] bg-[#020617] flex flex-col" dir={dir}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-white/5 bg-slate-900/50 backdrop-blur-md shrink-0">
        <button onClick={onClose} className="p-2 -ml-2 text-slate-400 hover:text-white">
          <X size={24} />
        </button>
        <h2 className="text-white font-bold text-lg">{t('wizard.title')}</h2>
        <div className="w-8" />
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6 pb-32">

        {/* Progress & Steps Info */}
        <div className="mb-8">
           {/* Visual Progress Bar */}
           <div className="flex justify-center gap-2 mb-6">
              {[1, 2, 3].map(i => (
                <div key={i} className={`h-1.5 w-8 rounded-full transition-colors ${step >= i ? 'bg-primary' : 'bg-slate-800'}`} />
              ))}
           </div>

           {/* Steps Row */}
           <div className="flex items-center justify-between w-full px-4 relative mb-6">
              {/* Connector Line */}
              <div className="absolute top-1/2 left-4 right-4 h-0.5 bg-slate-800 -z-10" />

              <div className="flex flex-col items-center gap-2 bg-[#020617] px-2">
                 <div className={`w-8 h-8 rounded-full border flex items-center justify-center ${step >= 1 ? 'bg-primary border-primary text-white' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    <MousePointerClick size={14} />
                 </div>
                 <span className="text-[10px] text-slate-500 font-medium">{t('wizard.step_1_label')}</span>
              </div>
              <div className="flex flex-col items-center gap-2 bg-[#020617] px-2">
                 <div className={`w-8 h-8 rounded-full border flex items-center justify-center ${step >= 2 ? 'bg-primary border-primary text-white' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    <Edit3 size={14} />
                 </div>
                 <span className="text-[10px] text-slate-500 font-medium">{t('wizard.step_2_label')}</span>
              </div>
              <div className="flex flex-col items-center gap-2 bg-[#020617] px-2">
                 <div className={`w-8 h-8 rounded-full border flex items-center justify-center ${step >= 3 ? 'bg-primary border-primary text-white' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    <CheckCircle2 size={14} />
                 </div>
                 <span className="text-[10px] text-slate-500 font-medium">{t('wizard.step_3_label')}</span>
              </div>
           </div>

           {/* Info Cards */}
           {step === 1 && (
             <div className="grid grid-cols-3 gap-3 w-full mb-6">
                <div className="bg-slate-800/40 border border-white/5 p-3 rounded-xl flex flex-col items-center justify-center gap-2 h-20">
                   <Lightbulb size={20} className="text-yellow-400" />
                   <span className="text-[10px] font-bold text-slate-300 leading-tight text-center">{t('wizard.card_idea')}</span>
                </div>
                <div className="bg-slate-800/40 border border-white/5 p-3 rounded-xl flex flex-col items-center justify-center gap-2 h-20">
                   <Layers size={20} className="text-blue-400" />
                   <span className="text-[10px] font-bold text-slate-300 leading-tight text-center">{t('wizard.card_platforms')}</span>
                </div>
                <div className="bg-slate-800/40 border border-white/5 p-3 rounded-xl flex flex-col items-center justify-center gap-2 h-20">
                   <Map size={20} className="text-purple-400" />
                   <span className="text-[10px] font-bold text-slate-300 leading-tight text-center">{t('wizard.card_plan')}</span>
                </div>
             </div>
           )}
        </div>

        {/* STEP 1: Industry */}
        {step === 1 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-4">
            <h3 className="text-xl font-bold text-white">{t('wizard.select_industry')}</h3>
            <div className="grid grid-cols-2 gap-3">
              {INDUSTRIES.map((ind) => (
                <button
                  key={ind.id}
                  onClick={() => setFormData({...formData, industry: ind.id})}
                  className={`p-4 rounded-xl border flex flex-col items-center gap-3 transition-all ${
                    formData.industry === ind.id 
                      ? 'bg-primary/20 border-primary text-white' 
                      : 'bg-slate-800/50 border-white/5 text-slate-400 hover:bg-slate-800'
                  }`}
                >
                  <ind.icon size={24} />
                  <span className="text-xs font-bold text-center">{ind.label}</span>
                </button>
              ))}
            </div>
          </motion.div>
        )}

        {/* STEP 2: Details */}
        {step === 2 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">

            <div className="space-y-1">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.name_label')}</label>
              <input 
                type="text" 
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                placeholder={t('wizard.name_ph')}
                className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none transition-colors"
              />
            </div>

            <div className="space-y-3">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.select_platforms')}</label>
              <div className="flex flex-wrap gap-3">
                {PLATFORMS.map(p => {
                  const isSelected = formData.platforms.includes(p.id);
                  return (
                    <button
                      key={p.id}
                      onClick={() => togglePlatform(p.id)}
                      className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border transition-all ${
                        isSelected 
                          ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' 
                          : 'bg-slate-800 text-slate-400 border-white/5 hover:bg-slate-700'
                      }`}
                    >
                      <p.icon size={16} />
                      <span className="text-xs font-bold">{t(p.label)}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.desc_label')}</label>
              <textarea 
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
                placeholder={t('wizard.desc_ph')}
                className="w-full h-32 bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none resize-none transition-colors"
              />
            </div>

          </motion.div>
        )}

        {/* STEP 3: Contact/Review */}
        {step === 3 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">

            <div className="bg-slate-800/30 border border-white/5 rounded-2xl p-6 text-center space-y-2">
               <h3 className="text-lg font-bold text-white">{formData.name}</h3>
               <p className="text-slate-400 text-sm">{formData.industry}</p>
               <div className="flex justify-center gap-2 mt-2">
                 {formData.platforms.map(p => (
                   <span key={p} className="text-[10px] bg-slate-700 px-2 py-1 rounded text-slate-300">{p}</span>
                 ))}
               </div>
            </div>

            {(isLeadMode || !user) && (
              <div className="space-y-4">
                <h3 className="text-lg font-bold text-white">{t('wizard.contact_title')}</h3>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.firstname')}</label>
                  <input 
                    type="text" 
                    value={formData.contactName}
                    onChange={e => setFormData({...formData, contactName: e.target.value})}
                    className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.phone')}</label>
                  <PhoneInput 
                    value={formData.contactPhone}
                    onChange={val => setFormData({...formData, contactPhone: val})}
                    required
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.email')} (Optional)</label>
                  <input 
                    type="email" 
                    dir="ltr"
                    value={formData.contactEmail}
                    onChange={e => setFormData({...formData, contactEmail: e.target.value})}
                    className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none"
                  />
                </div>
              </div>
            )}

            <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-xl flex items-start gap-3">
               <HelpCircle className="text-amber-400 shrink-0 mt-0.5" size={18} />
               <div>
                 <p className="text-amber-200 text-sm font-bold mb-1">{t('wizard.no_commit')}</p>
                 <p className="text-amber-400/80 text-xs">Our team will analyze your request and provide a FREE consultation.</p>
               </div>
            </div>

          </motion.div>
        )}

      </div>

      {/* Footer Nav */}
      <div className="p-6 border-t border-white/5 bg-[#0f172a] flex justify-between gap-4">
        <button 
          onClick={handleBack}
          disabled={step === 1}
          className={`px-6 py-3 rounded-xl font-bold text-slate-400 transition-colors ${step === 1 ? 'opacity-0 pointer-events-none' : 'hover:text-white'}`}
        >
          {t('wizard.back')}
        </button>

        {step < 3 ? (
          <button 
            onClick={handleNext}
            disabled={step === 1 ? !isStep1Valid : !isStep2Valid}
            className="flex-1 bg-primary text-white font-bold py-3 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {t('wizard.next')}
            {dir === 'rtl' ? <ChevronLeft size={18} /> : <ChevronRight size={18} />}
          </button>
        ) : (
          <button 
            onClick={handleSubmit}
            disabled={!isStep3Valid || loading}
            className="flex-1 bg-emerald-500 text-white font-bold py-3 rounded-xl shadow-[0_0_20px_rgba(16,185,129,0.3)] hover:shadow-[0_0_25px_rgba(16,185,129,0.5)] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="animate-spin" /> : t('wizard.submit')}
          </button>
        )}
      </div>
    </div>
  );
};

export default ProjectWizard;

import React, { useState } from 'react';
