import { 
  X, ChevronRight, ChevronLeft, CheckCircle2, 
  MousePointerClick, Edit3, Lightbulb, Rocket,
  Smartphone, Monitor, Globe, ShoppingCart, 
  Briefcase, GraduationCap, Utensils, Stethoscope, 
  Truck, HelpCircle, Loader2
} from 'lucide-react';
import { useTranslation } from '../lib/i18nContext';
import { auth } from '../lib/firebase';
import { userProjectsStore } from '../lib/userProjectsStore';
import { leadStore } from '../lib/leadStore';
import PhoneInput from './PhoneInput';

interface ProjectWizardProps {
  onClose: () => void;
  onComplete: () => void;
  isLeadMode?: boolean;
  source?: string;
}

const INDUSTRIES = [
