           {step === 1 && (
             <div className="flex justify-center items-center gap-10 w-full mb-8 py-2 opacity-50">
                <Lightbulb size={32} className="text-slate-500" />
                <Smartphone size={32} className="text-slate-500" />
                <Rocket size={32} className="text-slate-500" />
             </div>
           )}
        </div>

        {/* STEP 1: Industry */}
        {step === 1 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-4">
            <h3 className="text-xl font-bold text-white">{t('wizard.select_industry')}</h3>
            <div className="grid grid-cols-2 gap-3">
              {INDUSTRIES.map((ind) => (
                <button
                  key={ind.id}
                  onClick={() => setFormData({...formData, industry: ind.id})}
                  className={`p-4 rounded-xl border flex flex-col items-center gap-3 transition-all ${
                    formData.industry === ind.id 
                      ? 'bg-primary/20 border-primary text-white' 
                      : 'bg-slate-800/50 border-white/5 text-slate-400 hover:bg-slate-800'
                  }`}
                >
                  <ind.icon size={24} />
                  <span className="text-xs font-bold text-center">{ind.label}</span>
                </button>
              ))}
            </div>
          </motion.div>
        )}

        {/* STEP 2: Details */}
        {step === 2 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">

            <div className="space-y-1">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.name_label')}</label>
              <input 
                type="text" 
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                placeholder={t('wizard.name_ph')}
                className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none transition-colors"
              />
            </div>

            <div className="space-y-3">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.select_platforms')}</label>
              <div className="flex flex-wrap gap-3">
                {PLATFORMS.map(p => {
                  const isSelected = formData.platforms.includes(p.id);
                  return (
                    <button
                      key={p.id}
                      onClick={() => togglePlatform(p.id)}
                      className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border transition-all ${
                        isSelected 
                          ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' 
                          : 'bg-slate-800 text-slate-400 border-white/5 hover:bg-slate-700'
                      }`}
                    >
                      <p.icon size={16} />
                      <span className="text-xs font-bold">{t(p.label)}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-xs text-slate-400 ml-1">{t('wizard.desc_label')}</label>
              <textarea 
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
                placeholder={t('wizard.desc_ph')}
                className="w-full h-32 bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none resize-none transition-colors"
              />
            </div>

          </motion.div>
        )}

        {/* STEP 3: Contact/Review */}
        {step === 3 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-6">

            <div className="bg-slate-800/30 border border-white/5 rounded-2xl p-6 text-center space-y-2">
               <h3 className="text-lg font-bold text-white">{formData.name}</h3>
               <p className="text-slate-400 text-sm">{formData.industry}</p>
               <div className="flex justify-center gap-2 mt-2">
                 {formData.platforms.map(p => (
                   <span key={p} className="text-[10px] bg-slate-700 px-2 py-1 rounded text-slate-300">{p}</span>
                 ))}
               </div>
            </div>

            {(isLeadMode || !user) && (
              <div className="space-y-4">
                <h3 className="text-lg font-bold text-white">{t('wizard.contact_title')}</h3>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.firstname')}</label>
                  <input 
                    type="text" 
                    value={formData.contactName}
                    onChange={e => setFormData({...formData, contactName: e.target.value})}
                    className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.phone')}</label>
                  <PhoneInput 
                    value={formData.contactPhone}
                    onChange={val => setFormData({...formData, contactPhone: val})}
                    required
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-xs text-slate-400 ml-1">{t('auth.email') (Optional)}</label>
                  <input 
                    type="email" 
                    dir="ltr"
                    value={formData.contactEmail}
                    onChange={e => setFormData({...formData, contactEmail: e.target.value})}
                    className="w-full bg-slate-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-primary focus:outline-none"
                  />
                </div>
              </div>
            )}

            <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-xl flex items-start gap-3">
               <HelpCircle className="text-amber-400 shrink-0 mt-0.5" size={18} />
               <div>
                 <p className="text-amber-200 text-sm font-bold mb-1">{t('wizard.no_commit')}</p>
                 <p className="text-amber-400/80 text-xs">Our team will analyze your request and provide a FREE consultation.</p>
               </div>
            </div>

          </motion.div>
        )}

      </div>

      {/* Footer Nav */}
      <div className="p-6 border-t border-white/5 bg-[#0f172a] flex justify-between gap-4">
        <button 
          onClick={handleBack}
          disabled={step === 1}
          className={`px-6 py-3 rounded-xl font-bold text-slate-400 transition-colors ${step === 1 ? 'opacity-0 pointer-events-none' : 'hover:text-white'}`}
        >
          {t('wizard.back')}
        </button>

        {step < 3 ? (
          <button 
            onClick={handleNext}
            disabled={step === 1 ? !isStep1Valid : !isStep2Valid}
            className="flex-1 bg-primary text-white font-bold py-3 rounded-xl shadow-[0_0_20px_rgba(29,183,240,0.3)] hover:shadow-[0_0_25px_rgba(29,183,240,0.5)] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {t('wizard.next')}
            {dir === 'rtl' ? <ChevronLeft size={18} /> : <ChevronRight size={18} />}
          </button>
        ) : (
          <button 
            onClick={handleSubmit}
            disabled={!isStep3Valid || loading}
            className="flex-1 bg-emerald-500 text-white font-bold py-3 rounded-xl shadow-[0_0_20px_rgba(16,185,129,0.3)] hover:shadow-[0_0_25px_rgba(16,185,129,0.5)] transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="animate-spin" /> : t('wizard.submit')}
          </button>
        )}
      </div>
    </div>
  );
};

export default ProjectWizard;

import { collection, addDoc, serverTimestamp, query, orderBy, onSnapshot, updateDoc, doc, getDocs, where, deleteDoc } from 'firebase/firestore';
import { db, auth } from './firebase';
import { sanitizeForFirestore } from './firestoreSanitize';
import { userProjectsStore } from './userProjectsStore';

export interface Lead {
  id: string;
  name: string;
  phone: string; // E.164
  email?: string;
  source?: string;
  projectPayload: any;
  status: 'new' | 'reviewing' | 'approved' | 'rejected' | 'claimed';
  createdAt: number;
  rejectReason?: string;
}

export interface ClaimToken {
  id: string;
  token: string;
  leadId: string;
  expiresAt: number;
  used: boolean;
}

class LeadStore {
  private leads: Lead[] = [];
  private listeners: (() => void)[] = [];
  private unsubscribe: (() => void) | null = null;

  // --- ADMIN ACTIONS ---

  subscribeToLeads(listener: () => void) {
    if (!db) return () => {};
    // Ensure only admins call this (usually handled by UI guard, but firestore rules enforce data)

    const q = query(collection(db, 'leads'), orderBy('createdAt', 'desc'));

    this.unsubscribe = onSnapshot(q, (snap) => {
      this.leads = snap.docs.map(d => ({
        id: d.id,
        ...d.data(),
        createdAt: d.data().createdAt?.toMillis?.() || Date.now()
      })) as Lead[];
      listener();
    }, (err) => {
      console.error("Leads subscription error:", err);
    });

    return () => {
      if (this.unsubscribe) {
        this.unsubscribe();
        this.unsubscribe = null;
      }
    };
  }

  getLeads() {
    return [...this.leads];
  }

  async updateLeadStatus(id: string, status: Lead['status'], reason?: string) {
    if (!db) return;
    const update: any = { status };
    if (reason) update.rejectReason = reason;
    await updateDoc(doc(db, 'leads', id), update);
  }

  async generateClaimToken(leadId: string): Promise<string> {
    if (!db) throw new Error("DB not connected");

    const token = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
    const expiresAt = Date.now() + (7 * 24 * 60 * 60 * 1000); // 7 days

    await addDoc(collection(db, 'lead_claim_tokens'), {
      token,
      leadId,
      expiresAt,
      used: false,
      createdAt: serverTimestamp()
    });

    return token;
  }

  // --- PUBLIC ACTIONS ---

  async submitLead(data: { name: string; phone: string; email?: string; projectPayload: any; source?: string }) {
    if (!db) throw new Error("DB not connected");

    await addDoc(collection(db, 'leads'), {
      ...sanitizeForFirestore(data),
      status: 'new',
      createdAt: serverTimestamp()
    });
  }

  async validateToken(token: string): Promise<{ valid: boolean; leadId?: string; error?: string }> {
    if (!db) return { valid: false, error: "System error" };

    const q = query(collection(db, 'lead_claim_tokens'), where('token', '==', token), where('used', '==', false));
    const snap = await getDocs(q);

    if (snap.empty) {
      return { valid: false, error: "Invalid or used token." };
    }

    const data = snap.docs[0].data();
    if (Date.now() > data.expiresAt) {
      return { valid: false, error: "Token expired." };
    }

    return { valid: true, leadId: data.leadId };
  }

  async claimProject(token: string, leadId: string) {
    // Should be called AFTER user is authenticated
    const user = auth.currentUser;
    if (!db || !user) throw new Error("Must be logged in to claim");

    // 1. Get Lead Data
    const leadDoc = await getDocs(query(collection(db, 'leads'), where('__name__', '==', leadId)));
    if (leadDoc.empty) throw new Error("Lead not found");
    const leadData = leadDoc.docs[0].data() as Lead;

    if (leadData.status === 'claimed') throw new Error("Project already claimed");

    // 2. Create Real Project
    await userProjectsStore.addProject({
      ...leadData.projectPayload,
      name: leadData.projectPayload.name || 'My New Project', // Ensure name exists
      status: 'pricing' // Default status
    });

    // 3. Mark Token Used
    const tokenQ = query(collection(db, 'lead_claim_tokens'), where('token', '==', token));
    const tokenSnap = await getDocs(tokenQ);
    if (!tokenSnap.empty) {
      await updateDoc(tokenSnap.docs[0].ref, { used: true, claimedBy: user.uid, claimedAt: serverTimestamp() });
    }

    // 4. Update Lead Status
    await updateDoc(doc(db, 'leads', leadId), { status: 'claimed', claimedBy: user.uid });
  }
}

export const leadStore = new LeadStore();
